pragma solidity ^0.4.24;

import "./Baz.sol";

contract Bar {
    uint s;
    Baz baz;

    constructor () public {
        baz = new Baz();
        s = baz.add(0, 0);
    }

    function bar (uint i) public returns (uint) {
        uint sum = baz.add(s, i);
        s = sum;
        return sum;
    }
}

pragma solidity ^0.4.24;

contract Baz {
    function add (uint a, uint b) public pure returns (uint) {
        return a + b;
    }
}

pragma solidity ^0.4.24;

import "./FooBase.sol";
import "./Bar.sol";

contract Foo is FooBase {
    Bar bar;

    constructor (address a) public {
        bar = Bar(a);
    }

    function callBar(uint i) public {
        uint ret = bar.bar(i);
        s += ret;
    }
}

pragma solidity ^0.4.24;

contract FooBase {
    uint s;

    function foo (uint c) public {
        for (uint i = 0; i < c; i++) {
            callBar(i);
        }

        if (s > 1) {
            s += 1;
        }
    }

    function callBar(uint i) public {}
}

