        let data := add(transactions, add(i, 0x20))
        _success := call(gas(), to, 0, data, dataLength, 0, 0)
        if eq(_success, 0) {
          break
        }
        // Next entry starts at 32 bytes + data length
        i := add(i, add(0x20, dataLength))
      }
    }
