    IERC20(_path[0]).approve(ROUTER, _amountIn);
    IUniswapV2Router02(ROUTER).swapExactTokensForTokens(
      _amountIn,
      0, // Slippage protection is done in AsyncSwapper abstract
      _path,
      _receiver,
      block.timestamp
    // SWC-135-Code With No Effects: L53
