        _MAINTAINER_ = maintainer;
        _MT_FEE_RATE_MODEL_ = IFeeRateModel(mtFeeRateModel);

        require(lpFeeRate <= 1e18, "LP_FEE_RATE_OUT_OF_RANGE");
