        name = IERC20ForCheck(token).name();
        symbol = IERC20ForCheck(token).symbol();
        decimals = IERC20ForCheck(token).decimals();

        balance = IERC20ForCheck(token).balanceOf(user);
        allownance = IERC20ForCheck(token).allowance(user,spender);
   }
