pragma solidity ^0.5.0;

import "./aliana/AlianaOwnership.sol";
import "@openzeppelin/contracts/token/ERC20/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./aliana/IGeneScience.sol";

/// @title A facet of AlianaCore that manages Aliana siring, gestation, and birth.
/// @dev See the AlianaCore contract documentation to understand how the various contract facets are arranged.
contract Aliana is AlianaOwnership {
    constructor(IGeneScience _geneAddr) public {
        require(_geneAddr.isGeneScience(), "Aliana: isGeneScience false");
        setGeneScienceAddress(_geneAddr);
        require(
            _createAliana(0, 0, 0, address(this)) == 0,
            "Aliana: card #0 must be my own"
        );
    }

    /// @notice Have a pregnant Aliana give birth!
    /// @param _matronId A Aliana ready to give birth.
    /// @return The Aliana ID of the new kitten.
    /// @dev Looks at a given Aliana and, if pregnant and if the gestation period has passed,
    ///  combines the genes of the two parents to create a new kitten. The new Aliana is assigned
    ///  to the current owner of the matron. Upon successful completion, both the matron and the
    ///  new kitten will be ready to breed again. Note that anyone can call this function (if they
    ///  are willing to pay the gas!), but the new kitten always goes to the mother's owner.
    function mix(uint256 _matronId, uint256 _sireId)
        external
        whenNotPaused
        returns (uint256)
    {
        require(
            _matronId != _sireId,
            "Aliana: only different aliana can be merged"
        );
        require(ownerOf(_matronId) == msg.sender, "Aliana: must be the owner");
        require(ownerOf(_sireId) == msg.sender, "Aliana: must be the owner");

        // Grab a reference to the matron in storage.
        Aliana storage matron = alianas[_matronId];

        Aliana storage sire = alianas[_sireId];

        // Check that the matron is a valid cat.
        require(matron.birthTime != 0, "Aliana: matron birthTime not valid");

        // Check that the matron is a valid cat.
        require(sire.birthTime != 0, "Aliana: sire birthTime not valid");

        uint256 totalCats = totalAlianaSupply();
        // Call the sooper-sekret gene mixing operation.
        uint256 childGenes = geneScience.mixGenes(
            int256(_matronId),
            int256(_sireId),
            matron.genes,
            sire.genes,
            totalCats
        );

        _burn(msg.sender, _matronId);
        _burn(msg.sender, _sireId);

        // Make the new kitten!
        uint256 kittenId = _createAliana(
            _matronId,
            _sireId,
            childGenes,
            msg.sender
        );

        emit Mix(msg.sender, _matronId, _sireId, kittenId);

        // return the new kitten's ID
        return kittenId;
    }

    function burn(uint256 _tokenID) external {
        require(ownerOf(_tokenID) == msg.sender, "Aliana: must be the owner");
        _burn(msg.sender, _tokenID);
    }

    function geneLpLabor(int256 _id, uint256 _gene)
        public
        view
        returns (uint256)
    {
        return geneScience.geneLpLabor(_id, _gene);
    }

    function geneLpLabors(int256[] calldata _ids, uint256[] calldata _genes)
        external
        view
        returns (uint256[] memory)
    {
        uint256[] memory res = new uint256[](_genes.length);
        for (uint256 i = 0; i < _genes.length; i++) {
            res[i] = geneScience.geneLpLabor(_ids[i], _genes[i]);
        }
        return res;
    }

    /// @dev we can create Official alianas, up to a limit. Only callable by Official contract
    /// @param _genes the encoded genes of the kitten to be created, any value is accepted
    /// @param _owner the future owner of the created alianas. Default to contract COO
    function createOfficialAliana(uint256 _genes, address _owner)
        external
        onlyWhitelisted
        returns (uint256)
    {
        return _createAliana(0, 0, _genes, _owner);
    }

    /// @dev we can create Official alianas, up to a limit. Only callable by Official contract
    /// @param _genes the encoded genes of the kitten to be created, any value is accepted
    /// @param _owner the future owner of the created alianas. Default to contract COO
    function createOfficialAliana(
        uint256 _matronId,
        uint256 _sireId,
        uint256 _genes,
        address _owner
    ) external onlyWhitelisted returns (uint256) {
        return _createAliana(_matronId, _sireId, _genes, _owner);
    }

    /// @dev we can create promo alianas, up to a limit. Only callable by COO
    /// @param _genes the encoded genes of the kitten to be created, any value is accepted
    /// @param _owner the future owner of the created alianas. Default to contract COO
    function createPromoAliana(uint256 _genes, address _owner)
        external
        onlyCLevel
        returns (uint256)
    {
        address alianaOwner = _owner;
        if (alianaOwner == address(0)) {
            alianaOwner = msg.sender;
        }

        return _createAliana(0, 0, _genes, alianaOwner);
    }

    event Mix(
        address indexed src,
        uint256 indexed matronId,
        uint256 indexed sireId,
        uint256 kittenId
    );
}

pragma solidity ^0.5.0;

import "./aliana/GFAccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./aliana/IAliana.sol";

/// @title all functions related to creating kittens
contract AlianaMinting is GFAccessControl {
    using SafeMath for uint256;
    using SafeERC20 for IERC20;

    // The gae TOKEN
    IERC20 public gftToken;
    IAliana public aliana;

    struct itmap {
        mapping(uint256 => IndexValue) data;
        KeyFlag[] keys;
        uint256 size;
    }
    struct IndexValue {
        uint256 keyIndex;
        uint256 value;
    }
    struct KeyFlag {
        uint256 key;
        bool deleted;
    }

    function insert(
        itmap storage self,
        uint256 key,
        uint256 value
    ) internal returns (bool replaced) {
        uint256 keyIndex = self.data[key].keyIndex;
        self.data[key].value = value;
        if (keyIndex > 0) return true;
        else {
            keyIndex = self.keys.length++;
            self.data[key].keyIndex = keyIndex + 1;
            self.keys[keyIndex].key = key;
            self.size++;
            return false;
        }
    }

    function remove(itmap storage self, uint256 key)
        internal
        returns (bool success)
    {
        uint256 keyIndex = self.data[key].keyIndex;
        if (keyIndex == 0) return false;
        delete self.data[key];
        self.keys[keyIndex - 1].deleted = true;
        self.size--;
        return true;
    }

    function contains(itmap storage self, uint256 key)
        internal
        view
        returns (bool)
    {
        return self.data[key].keyIndex > 0;
    }

    function iterate_start(itmap storage self)
        internal
        view
        returns (uint256 keyIndex)
    {
        return iterate_next(self, uint256(-1));
    }

    function iterate_valid(itmap storage self, uint256 keyIndex)
        internal
        view
        returns (bool)
    {
        return keyIndex < self.keys.length;
    }

    function iterate_next(itmap storage self, uint256 keyIndex)
        internal
        view
        returns (uint256 r_keyIndex)
    {
        keyIndex++;
        while (keyIndex < self.keys.length && self.keys[keyIndex].deleted)
            keyIndex++;
        return keyIndex;
    }

    function iterate_get(itmap storage self, uint256 keyIndex)
        internal
        view
        returns (uint256 key, uint256 value)
    {
        key = self.keys[keyIndex].key;
        value = self.data[key].value;
    }

    // Info of each user.
    struct UserInfo {
        uint256 amount; // How many LP tokens the user has provided.
        itmap amountToken;
        uint256 rewardDebt; // Reward debt. See explanation below.
        uint256 balance;
        //
        // We do some fancy math here. Basically, any point in time, the amount of GFTs
        // entitled to a user but is pending to be distributed is:
        //
        //   pending reward = (user.amount * accGFTPerShare) - user.rewardDebt
        //
        // Whenever a user deposits or withdraws LP tokens to a pool. Here's what happens:
        //   1. Update accGFTPerShare and lastRewardBlock
        //   2. User receives the pending reward sent to his/her address.
        //   3. User's `amount` gets updated.
        //   4. User's `rewardDebt` gets updated.
    }

    // Accumulated GFTs per share, times 1e12. See below.
    uint256 public accGFTPerShare;
    // Last block reward block height
    uint256 public lastRewardBlock;
    // Reward per block
    uint256 public rewardPerBlock;
    // This Mine total labor force
    uint256 public labor;
    // Reward to distribute
    uint256 public rewardToDistribute;
    uint256 public maxMintingNumPerAddress = 9;

    // Info of each user that stakes LP tokens.
    mapping(address => UserInfo) userInfo;

    event RewardAdded(uint256 amount, bool isBlockReward);
    event Deposit(
        address indexed user,
        uint256 indexed tokenId,
        uint256 amount,
        uint256 pending
    );
    event Withdraw(
        address indexed user,
        uint256 indexed tokenId,
        uint256 amount,
        uint256 pending
    );
    event WithdrawPending(address indexed user, uint256 pending);
    event EmergencyWithdraw(address indexed user, uint256 amount);

    constructor(IERC20 _gftToken, IAliana _alianaAddr) public {
        require(_alianaAddr.isAliana(), "AlianaMinting: isAliana false");
        gftToken = _gftToken;
        aliana = _alianaAddr;
        lastRewardBlock = block.number;
        // times 1e10. See below.
        uint256 defaultPerDayIn5SecBlock = 2000;
        setRewardPerBlock(
            defaultPerDayIn5SecBlock.mul(1e18).div((24 * 60 * 60) / 5)
        );
    }

    function setMaxMintingNumPerAddress(uint256 _maxMintingNumPerAddress)
        public
        onlyCEO
    {
        maxMintingNumPerAddress = _maxMintingNumPerAddress;
    }

    function setRewardPerBlock(uint256 _rewardPerBlock) public onlyCEO {
        updateBlockReward();
        rewardPerBlock = _rewardPerBlock;
    }

    // View function to see pending reward on frontend.
    function pendingReward(address _user) external view returns (uint256) {
        UserInfo storage user = userInfo[_user];
        if (rewardPerBlock == 0) {
            return 0;
        }
        uint256 acps = accGFTPerShare;
        if (rewardPerBlock > 0) {
            uint256 lpSupply = labor;
            if (block.number > lastRewardBlock && lpSupply > 0) {
                acps = acps.add(rewardPending().mul(1e12).div(lpSupply));
            }
        }
        return user.amount.mul(acps).div(1e12).sub(user.rewardDebt);
    }

    function rewardPending() internal view returns (uint256) {
        uint256 reward = block.number.sub(lastRewardBlock).mul(rewardPerBlock);
        uint256 gaeBalance = gftToken.balanceOf(address(this)).sub(
            rewardToDistribute
        );
        if (gaeBalance < reward) {
            return gaeBalance;
        }
        return reward;
    }

    // Update reward variables to be up-to-date.
    function updateBlockReward() public {
        if (block.number <= lastRewardBlock || rewardPerBlock == 0) {
            return;
        }
        uint256 lpSupply = labor;
        uint256 reward = rewardPending();
        if (lpSupply == 0 || reward == 0) {
            lastRewardBlock = block.number;
            return;
        }
        rewardToDistribute = rewardToDistribute.add(reward);
        emit RewardAdded(reward, true);
        lastRewardBlock = block.number;
        accGFTPerShare = accGFTPerShare.add(reward.mul(1e12).div(lpSupply));
    }

    function _depositFrom(address _from, uint256 _tokenId)
        internal
        whenNotPaused
    {
        require(
            aliana.ownerOf(_tokenId) == _from,
            "AlianaMinting: must be the owner"
        );
        UserInfo storage user = userInfo[_from];
        if (maxMintingNumPerAddress > 0) {
            require(
                user.amountToken.size < maxMintingNumPerAddress,
                "AlianaMinting: too much mining at the same time"
            );
        }
        (, , , , uint256 _amount) = aliana.getAliana(_tokenId);
        require(_amount > 0, "AlianaMinting: gene _amount must > 0");

        updateBlockReward();
        uint256 takePending;
        if (user.amount > 0) {
            uint256 pending = user.amount.mul(accGFTPerShare).div(1e12).sub(
                user.rewardDebt
            );
            if (pending > 0) {
                safeGFTTransfer(_from, pending);
            }
            takePending = pending;
        }

        aliana.transferFrom(address(_from), address(this), _tokenId);
        // SWC-104-Unchecked Call Return Value: L254
        insert(user.amountToken, _tokenId, _amount);
        user.balance = user.balance.add(1);

        user.amount = user.amount.add(_amount);
        labor = labor.add(_amount);

        user.rewardDebt = user.amount.mul(accGFTPerShare).div(1e12);
        emit Deposit(_from, _tokenId, _amount, takePending);
    }

    // Deposit LP tokens to Mine for GFT allocation.
    function deposit(uint256 _tokenId) public whenNotPaused {
        _depositFrom(msg.sender, _tokenId);
    }

    // Deposit LP tokens to Mine for GFT allocation.
    function deposits(uint256[] memory _tokenIds) public whenNotPaused {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            deposit(_tokenIds[i]);
        }
    }

    // Withdraw LP tokens from Mine.
    function withdrawPending() public {
        UserInfo storage user = userInfo[msg.sender];
        updateBlockReward();
        uint256 pending = user.amount.mul(accGFTPerShare).div(1e12).sub(
            user.rewardDebt
        );
        if (pending > 0) {
            safeGFTTransfer(msg.sender, pending);
        }
        user.rewardDebt = user.amount.mul(accGFTPerShare).div(1e12);
        emit WithdrawPending(msg.sender, pending);
    }

    // Withdraw LP tokens from Mine.
    function withdraw(uint256 _tokenId) public {
        return _withdrawFrom(msg.sender, _tokenId);
    }

    function _withdrawFrom(address _from, uint256 _tokenId) internal {
        UserInfo storage user = userInfo[_from];
        uint256 _amount = user.amountToken.data[_tokenId].value;

        require(_amount > 0, "AlianaMinting: withdraw: not good 1");
        require(user.amount >= _amount, "AlianaMinting: withdraw: not good 2");

        updateBlockReward();
        uint256 pending = user.amount.mul(accGFTPerShare).div(1e12).sub(
            user.rewardDebt
        );
        if (pending > 0) {
            safeGFTTransfer(_from, pending);
        }

        require(
            remove(user.amountToken, _tokenId),
            "AlianaMinting: withdraw: not good, remove from amountToken"
        );
        user.balance = user.balance.sub(1);
        user.amount = user.amount.sub(_amount);
        aliana.safeTransferFrom(address(this), address(_from), _tokenId, "");

        user.rewardDebt = user.amount.mul(accGFTPerShare).div(1e12);
        labor = labor.sub(_amount);
        emit Withdraw(_from, _tokenId, _amount, pending);
    }

    // Withdraw LP tokens from Mine.
    function withdraws(uint256[] memory _tokenIds) public {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            withdraw(_tokenIds[i]);
        }
    }

    // Withdraw LP tokens from Mine.
    function withdrawsByCEO(address _from, uint256[] memory _tokenIds)
        public
        onlyCEO
    {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            _withdrawFrom(_from, _tokenIds[i]);
        }
    }

    // Withdraw without caring about rewards. EMERGENCY ONLY.
    function emergencyWithdraw() public {
        _emergencyWithdrawFrom(msg.sender);
    }

    // Withdraw without caring about rewards. EMERGENCY ONLY.
    function emergencyWithdrawByCEO(address _from) public onlyCEO {
        _emergencyWithdrawFrom(_from);
    }

    function _emergencyWithdrawFrom(address _from) internal {
        UserInfo storage user = userInfo[_from];
        uint256 amount = user.amount;

        for (
            uint256 i = iterate_start(user.amountToken);
            iterate_valid(user.amountToken, i);
            i = iterate_next(user.amountToken, i)
        ) {
            uint256 key = 0;
            uint256 value = 0;
            (key, value) = iterate_get(user.amountToken, i);
            aliana.safeTransferFrom(address(this), address(_from), key, "");
        }

        user.amount = 0;
        user.rewardDebt = 0;
        delete user.amountToken;
        user.balance = 0;
        labor = labor.sub(amount);
        emit EmergencyWithdraw(_from, amount);
    }

    // Safe GFT transfer function, just in case if rounding error causes pool to not have enough GFTs.
    function safeGFTTransfer(address _to, uint256 _amount) internal {
        uint256 gaeBalance = gftToken.balanceOf(address(this));
        require(gaeBalance >= _amount, "AlianaMinting: insufficient balance");
        rewardToDistribute = rewardToDistribute.sub(_amount);
        require(
            gftToken.transfer(_to, _amount),
            "AlianaMinting: failed to transfer gae token"
        );
    }

    function depositedTokens(address _owner)
        public
        view
        returns (uint256[] memory ownerTokens)
    {
        require(_owner != address(0), "AlianaMinting: zero address");

        UserInfo storage user = userInfo[_owner];
        uint256[] memory result = new uint256[](user.balance);
        uint256 resultIndex = 0;
        for (
            uint256 i = iterate_start(user.amountToken);
            iterate_valid(user.amountToken, i);
            i = iterate_next(user.amountToken, i)
        ) {
            uint256 key = 0;
            uint256 value = 0;
            (key, value) = iterate_get(user.amountToken, i);
            result[resultIndex] = key;
            resultIndex++;
        }
        return result;
    }

    /**
     * @dev Gets the balance of the specified address.
     * @param _owner address to query the balance of
     * @return uint256 representing the amount owned by the passed address
     */
    function depositedBalanceOf(address _owner) public view returns (uint256) {
        require(_owner != address(0), "AlianaMinting: zero address");
        UserInfo storage user = userInfo[_owner];
        return user.balance;
    }

    function receiveApproval(
        address _sender,
        uint256 _value,
        address _tokenContract,
        bytes memory _extraData
    ) public {
        require(_value >= 0, "AlianaMinting: approval negative");
        uint256 action;
        assembly {
            action := mload(add(_extraData, 0x20))
        }
        require(action == 1, "AlianaMinting: unknow action");
        if (action == 1) {
            // deposit
            require(
                _tokenContract == address(aliana),
                "AlianaMinting: approval and want mint use aliana, but used token isn't Aliana"
            );
            uint256 tokenId;
            assembly {
                tokenId := mload(add(_extraData, 0x40))
            }
            _depositFrom(_sender, tokenId);
        }
    }
}

pragma solidity ^0.5.0;

import "./aliana/GFAccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./aliana/IAliana.sol";

contract AlianaSale is GFAccessControl {
    using SafeMath for uint256;

    // The gae TOKEN
    IERC20 public gaeToken;
    IAliana public aliana;

    // Mapping from owner to list of owned token IDs
    mapping(address => uint256[]) private _ownedTokensSale;

    // Mapping from token ID to index of the owner tokens list
    mapping(uint256 => uint256) private _ownedTokensIndexSale;

    // Array with all token ids, used for enumeration
    uint256[] private _allTokensSale;

    // Mapping from token id to position in the allTokens array
    mapping(uint256 => uint256) private _allTokensIndexSale;

    // Mapping from token id to position in the allTokens array
    mapping(uint256 => AlianaSaleInfo) private _allSaleAlianaInfo;

    // Cut owner takes on each auction, measured in basis points (1/100 of a percent).
    // Values 0-10,000 map to 0%-100%
    uint256 public ownerCutSale;
    uint256 public cutedSaleBalance;

    // Info of each sale aliana.
    struct AlianaSaleInfo {
        uint256 tokenId;
        uint256 beginBlock;
        uint256 price;
        address seller;
    }

    event CreateAlianaSale(
        address indexed seller,
        uint256 indexed tokenId,
        uint256 price
    );
    event CancelAlianaSale(address indexed seller, uint256 tokenId);
    event BuySaleAliana(
        address indexed seller,
        address indexed buyer,
        uint256 indexed tokenId
    );

    constructor(IERC20 _gaeToken, IAliana _alianaAddr) public {
        require(_alianaAddr.isAliana(), "AlianaSale: isAliana false");
        gaeToken = _gaeToken;
        aliana = _alianaAddr;
        ownerCutSale = 300;
    }

    /// @dev Update the value of ownerCutSale, can only be called by the CEO.
    function setOwnerCutSale(uint256 num) external onlyCEO {
        require(num <= 10000, "AlianaSale: num not valid");
        ownerCutSale = num;
    }

    function withdrawOwnerCutSale(uint256 num) external onlyCLevel {
        require(num <= cutedSaleBalance, "AlianaSale: num <= cutedSaleBalance");

        require(
            gaeToken.transferFrom(address(this), msg.sender, num),
            "AlianaSale: failed to transfer gae token"
        );

        cutedSaleBalance = cutedSaleBalance.sub(num);
    }

    /// @notice Returns all the relevant information about a specific aliana.
    /// @param _tokenId The ID of the aliana of interest.
    function getAlianaSaleInfo(uint256 _tokenId)
        external
        view
        returns (
            uint256 beginBlock,
            uint256 price,
            address seller
        )
    {
        AlianaSaleInfo storage info = _allSaleAlianaInfo[_tokenId];
        beginBlock = info.beginBlock;
        price = info.price;
        seller = info.seller;
        if (!_isOnSale(info)) {
            beginBlock = 0;
            price = 0;
            seller = address(0);
        }
    }

    function createAlianaSale(uint256 _tokenId, uint256 _price)
        external
        whenNotPaused
    {
        _createAlianaSaleFrom(msg.sender, _tokenId, _price);
    }

    function _createAlianaSaleFrom(
        address _from,
        uint256 _tokenId,
        uint256 _price
    ) internal whenNotPaused {
        require(_price > 0, "AlianaSale: price can't be 0");
        require(
            aliana.ownerOf(_tokenId) == _from,
            "AlianaSale: must be the owner"
        );

        aliana.transferFrom(address(_from), address(this), _tokenId);

        _addTokenToOwnerEnumerationSale(_from, _tokenId);

        _addTokenToAllTokensEnumerationSale(_tokenId);

        AlianaSaleInfo storage info = _allSaleAlianaInfo[_tokenId];
        info.tokenId = _tokenId;
        info.beginBlock = block.number;
        info.price = _price;
        info.seller = _from;

        emit CreateAlianaSale(_from, _tokenId, _price);
    }

    function adminCancelAlianaSales(uint256[] memory _tokenIds)
        public
        onlyCLevel
    {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            uint256 _tokenId = _tokenIds[i];
            AlianaSaleInfo storage info = _allSaleAlianaInfo[_tokenId];
            if (_isOnSale(info)) {
                aliana.transferFrom(
                    address(this),
                    address(info.seller),
                    _tokenId
                );
                _burnSale(info.seller, _tokenId);
                emit CancelAlianaSale(info.seller, _tokenId);
            }
        }
    }

    function cancelAlianaSale(uint256 _tokenId) external {
        _cancelAlianaSaleFrom(msg.sender, _tokenId);
    }

    function _cancelAlianaSaleFrom(address _from, uint256 _tokenId) internal {
        AlianaSaleInfo storage info = _allSaleAlianaInfo[_tokenId];
        require(_isOnSale(info), "AlianaSale: target token not on sale");
        address seller = info.seller;
        require(_from == seller, "AlianaSale: you're not the seller");

        aliana.transferFrom(address(this), address(info.seller), _tokenId);

        _burnSale(info.seller, _tokenId);

        emit CancelAlianaSale(info.seller, _tokenId);
    }

    function buySaleAliana(uint256 _tokenId) external whenNotPaused {
        _buySaleAlianaFrom(msg.sender, _tokenId);
    }

    function _buySaleAlianaFrom(address buyer, uint256 _tokenId)
        internal
        whenNotPaused
    {
        AlianaSaleInfo storage info = _allSaleAlianaInfo[_tokenId];
        require(_isOnSale(info), "AlianaSale: target token not on sale");

        require(
            gaeToken.transferFrom(buyer, address(this), info.price),
            "AlianaSale: failed to transfer gae token to contract"
        );

        uint256 auctioneerCut = _computeCutSale(info.price);
        uint256 sellerGet = info.price - auctioneerCut;
        cutedSaleBalance = cutedSaleBalance.add(auctioneerCut);

        require(
            gaeToken.transferFrom(address(this), info.seller, sellerGet),
            "AlianaSale: failed to transfer gae token to seller"
        );

        aliana.transferFrom(address(this), address(buyer), _tokenId);

        emit BuySaleAliana(info.seller, buyer, _tokenId);
        _burnSale(info.seller, _tokenId);
    }

    /// @dev Computes owner's cut of a sale.
    /// @param _price - Sale price of NFT.
    function _computeCutSale(uint256 _price) internal view returns (uint256) {
        // NOTE: We don't use SafeMath (or similar) in this function because
        //  all of our entry functions carefully cap the maximum values for
        //  currency (at 128-bits), and ownerCut <= 10000 (see the require()
        //  statement in the ClockAuction constructor). The result of this
        //  function is always guaranteed to be <= _price.
        return (_price * ownerCutSale) / 10000;
    }

    function _burnSale(address _seller, uint256 _tokenId) internal {
        _removeTokenFromOwnerEnumerationSale(_seller, _tokenId);
        // Since _tokenId will be deleted, we can clear its slot in _ownedTokensIndex to trigger a gas refund
        _ownedTokensIndexSale[_tokenId] = 0;
        _removeTokenFromAllTokensEnumerationSale(_tokenId);

        AlianaSaleInfo storage info = _allSaleAlianaInfo[_tokenId];
        info.beginBlock = 0;
        info.seller = address(0);
        info.price = 0;
    }

    /// @dev Returns true if the NFT is on sale.
    /// @param _info - Auction to check.
    function _isOnSale(AlianaSaleInfo storage _info)
        internal
        view
        returns (bool)
    {
        return (_info.beginBlock > 0);
    }

    function totalSale() public view returns (uint256) {
        return _allTokensSale.length;
    }

    /**
     * @dev Gets the list of token IDs of the sale.
     * @return uint256[] List of token IDs sale.
     */
    function allTokensSale() external view returns (uint256[] memory tokenIds) {
        return _allTokensSale;
    }

    /**
     * @dev Gets the list of token IDs of the sale.
     * @return uint256[] List of token IDs sale.
     */
    function listTokensSale(uint256 _skip, uint256 _limit)
        external
        view
        returns (uint256[] memory tokenIds)
    {
        uint256 totalCount = totalSale();
        if (_limit == 0 || _skip >= totalCount) {
            // Return an empty array
            return new uint256[](0);
        } else {
            uint256 tokenCount = _limit;
            if (_skip.add(_limit) > totalCount) {
                tokenCount = totalCount - _skip;
            }
            uint256 end = _skip.add(tokenCount);
            uint256[] memory result = new uint256[](tokenCount);
            uint256 resultIndex = 0;

            // We count on the fact that all cats have IDs starting at 1 and increasing
            // sequentially up to the totalCat count.
            uint256 i;

            for (i = _skip; i < end; i++) {
                result[resultIndex] = _allTokensSale[i];
                resultIndex++;
            }

            return result;
        }
    }

    /// @notice Returns a list of all Aliana IDs assigned to an address.
    /// @param _owner The owner whose Kitties we are interested in.
    /// @dev This method MUST NEVER be called by smart contract code. First, it's fairly
    ///  expensive (it walks the entire Aliana array looking for cats belonging to owner),
    ///  but it also returns a dynamic array, which is only supported for web3 calls, and
    ///  not contract-to-contract calls.
    function tokensOfOwnerSale(address _owner)
        external
        view
        returns (uint256[] memory ownerTokens)
    {
        return _tokensOfOwnerSale(_owner);
    }

    /**
     * @dev Gets the list of token IDs of the requested owner.
     * @param owner address owning the tokens
     * @return uint256[] List of token IDs owned by the requested address
     */
    function _tokensOfOwnerSale(address owner)
        internal
        view
        returns (uint256[] storage)
    {
        return _ownedTokensSale[owner];
    }

    /**
     * @dev Private function to add a token to this extension's ownership-tracking data structures.
     * @param to address representing the new owner of the given token ID
     * @param tokenId uint256 ID of the token to be added to the tokens list of the given address
     */
    function _addTokenToOwnerEnumerationSale(address to, uint256 tokenId)
        private
    {
        _ownedTokensIndexSale[tokenId] = _ownedTokensSale[to].length;
        _ownedTokensSale[to].push(tokenId);
    }

    /**
     * @dev Private function to add a token to this extension's token tracking data structures.
     * @param tokenId uint256 ID of the token to be added to the tokens list
     */
    function _addTokenToAllTokensEnumerationSale(uint256 tokenId) private {
        _allTokensIndexSale[tokenId] = _allTokensSale.length;
        _allTokensSale.push(tokenId);
    }

    /**
     * @dev Private function to remove a token from this extension's ownership-tracking data structures. Note that
     * while the token is not assigned a new owner, the `_ownedTokensIndex` mapping is _not_ updated: this allows for
     * gas optimizations e.g. when performing a transfer operation (avoiding double writes).
     * This has O(1) time complexity, but alters the order of the _ownedTokens array.
     * @param from address representing the previous owner of the given token ID
     * @param tokenId uint256 ID of the token to be removed from the tokens list of the given address
     */
    function _removeTokenFromOwnerEnumerationSale(address from, uint256 tokenId)
        private
    {
        // To prevent a gap in from's tokens array, we store the last token in the index of the token to delete, and
        // then delete the last slot (swap and pop).

        uint256 lastTokenIndex = _ownedTokensSale[from].length.sub(1);
        uint256 tokenIndex = _ownedTokensIndexSale[tokenId];

        // When the token to delete is the last token, the swap operation is unnecessary
        if (tokenIndex != lastTokenIndex) {
            uint256 lastTokenId = _ownedTokensSale[from][lastTokenIndex];

            _ownedTokensSale[from][tokenIndex] = lastTokenId; // Move the last token to the slot of the to-delete token
            _ownedTokensIndexSale[lastTokenId] = tokenIndex; // Update the moved token's index
        }

        // This also deletes the contents at the last position of the array
        _ownedTokensSale[from].length--;

        // Note that _ownedTokensIndex[tokenId] hasn't been cleared: it still points to the old slot (now occupied by
        // lastTokenId, or just over the end of the array if the token was the last one).
    }

    /**
     * @dev Private function to remove a token from this extension's token tracking data structures.
     * This has O(1) time complexity, but alters the order of the _allTokens array.
     * @param tokenId uint256 ID of the token to be removed from the tokens list
     */
    function _removeTokenFromAllTokensEnumerationSale(uint256 tokenId) private {
        // To prevent a gap in the tokens array, we store the last token in the index of the token to delete, and
        // then delete the last slot (swap and pop).

        uint256 lastTokenIndex = _allTokensSale.length.sub(1);
        uint256 tokenIndex = _allTokensIndexSale[tokenId];

        // When the token to delete is the last token, the swap operation is unnecessary. However, since this occurs so
        // rarely (when the last minted token is burnt) that we still do the swap here to avoid the gas cost of adding
        // an 'if' statement (like in _removeTokenFromOwnerEnumeration)
        uint256 lastTokenId = _allTokensSale[lastTokenIndex];

        _allTokensSale[tokenIndex] = lastTokenId; // Move the last token to the slot of the to-delete token
        _allTokensIndexSale[lastTokenId] = tokenIndex; // Update the moved token's index

        // This also deletes the contents at the last position of the array
        _allTokensSale.length--;
        _allTokensIndexSale[tokenId] = 0;
    }

    function receiveApproval(
        address _sender,
        uint256 _value,
        address _tokenContract,
        bytes memory _extraData
    ) public {
        require(_value >= 0, "AlianaSale: approval negative");
        uint256 action;
        assembly {
            action := mload(add(_extraData, 0x20))
        }
        require(action == 1 || action == 2, "AlianaSale: unknow action");
        if (action == 1) {
            // buy
            require(
                _tokenContract == address(gaeToken),
                "AlianaSale: approval and want buy a aliana, but used token isn't GFT"
            );
            uint256 tokenId;
            assembly {
                tokenId := mload(add(_extraData, 0x40))
            }
            _buySaleAlianaFrom(_sender, tokenId);
        } else if (action == 2) {
            // sale
            require(
                _tokenContract == address(aliana),
                "AlianaSale: approval and want sale a aliana, but used token isn't Aliana"
            );
            uint256 tokenId;
            uint256 price;
            assembly {
                tokenId := mload(add(_extraData, 0x40))
                price := mload(add(_extraData, 0x60))
            }
            _createAlianaSaleFrom(_sender, tokenId, price);
        }
    }
}

pragma solidity ^0.5.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./aliana/GFAccessControl.sol";
import "./aliana/IAliana.sol";
import "./aliana/AuctionOwner.sol";
import "./aliana/IGeneScience.sol";
import "./math/SafeMath.sol";

/// @title Auction Core
/// @dev Contains models, variables, and internal methods for the auction.
/// @notice We omit a fallback function to prevent accidental sends to this contract.
contract ClockAuctionBase is AuctionOwner, GFAccessControl {
    uint256 maxBiddingNum;
    uint256[] biddingId;
    uint256 public lastBiddingId;
    uint256 c_startingPrice = 1e16; // 0.01 GFT
    uint256 c_duration = 50; // 300s
    uint256 c_minAddPrice = 1e16; // 0.01 GFT

    // Represents an auction on an NFT
    struct Auction {
        uint256 currentPrice;
        address buyer;
        uint64 endAt;
        bool taked;
    }

    // Reference to contract tracking NFT ownership
    IAliana public alianaContract;

    // Cut owner takes on each auction, measured in basis points (1/100 of a percent).
    // Values 0-10,000 map to 0%-100%
    uint256 public ownerCut;

    // The gae TOKEN
    IERC20 public gaeToken;

    /// @dev The address of the sibling contract that is used to implement the sooper-sekret
    ///  genetic combination algorithm.
    IGeneScience public geneScience;

    /// @dev Update the address of the genetic contract, can only be called by the CEO.
    /// @param _address An address of a GeneScience contract instance to be used from this point forward.
    function setGeneScienceAddress(IGeneScience _address) public onlyCEO {
        // NOTE: verify that a contract is what we expect - https://github.com/Lunyr/crowdsale-contracts/blob/cfadd15986c30521d8ba7d5b6f57b4fefcc7ac38/contracts/LunyrToken.sol#L117
        require(_address.isGeneScience(), "Aliana: not gene");

        // Set the new contract address
        geneScience = _address;
    }

    // Map from token ID to their corresponding auction.
    mapping(uint256 => Auction) tokenIdToAuction;

    event TakeBid(
        uint256 indexed tokenId,
        address indexed winner,
        uint256 totalPrice
    );

    event Bid(uint256 indexed tokenId, address indexed buyer, uint256 price);

    constructor(IERC20 _gaeToken, IGeneScience _geneAddr) public {
        gaeToken = _gaeToken;
        updateMaxBiddingNum(20);
        setGeneScienceAddress(_geneAddr);
    }

    function updateMaxBiddingNum(uint256 _value) public onlyCEO {
        maxBiddingNum = _value;
        for (uint256 i = maxBiddingNum; i < biddingId.length; i++) {
            Auction storage auction = tokenIdToAuction[biddingId[i]];
            require(
                !_hasAuctionByInfo(auction) || !_isOnAuction(auction),
                "Auction: reduced capacity auction in bidding"
            );
        }
        biddingId.length = maxBiddingNum;
        _updateBidding();
    }

    function getStartingPrice() public view returns (uint256) {
        return c_startingPrice;
    }

    function setStartingPrice(uint256 _value) public onlyCEO {
        c_startingPrice = _value;
    }

    function getDuration() public view returns (uint256) {
        return c_duration;
    }

    function setDuration(uint256 _value) public onlyCEO {
        c_duration = _value;
    }

    function getMinAddPrice() public view returns (uint256) {
        return c_minAddPrice;
    }

    function setMinAddPrice(uint256 _value) public onlyCEO {
        c_minAddPrice = _value;
    }

    function minAddPrice() public view returns (uint256) {
        return c_minAddPrice;
    }

    function _updateBidding() internal {
        uint256 _lastBidding = lastBiddingId;
        for (uint256 i = 0; i < maxBiddingNum; i++) {
            uint256 id = biddingId[i];
            if (id != 0) {
                Auction storage auction = tokenIdToAuction[id];
                if (_hasAuctionByInfo(auction)) {
                    if (_isOnAuction(auction)) {
                        continue;
                    }
                } else {
                    continue;
                }
            }
            // set bidding id
            biddingId[i] = _lastBidding + 1;
            _lastBidding = _lastBidding + 1;
        }
        if (lastBiddingId != _lastBidding) {
            lastBiddingId = _lastBidding;
        }
    }

    function _isBidding(uint256 _id) internal view returns (bool) {
        uint256[] memory list = _biddingIdList();
        for (uint256 i = 0; i < list.length; i++) {
            if (list[i] == _id) {
                return true;
            }
        }
        return false;
    }

    function _isBiddingNoCheck(uint256 _id) internal view returns (bool) {
        for (uint256 i = 0; i < biddingId.length; i++) {
            if (biddingId[i] == _id) {
                return true;
            }
        }
        return false;
    }

    function _biddingNum() internal view returns (uint256) {
        return maxBiddingNum;
    }

    function _biddingIdList() internal view returns (uint256[] memory) {
        uint256[] memory result = new uint256[](maxBiddingNum);
        uint256 resultIndex = 0;
        uint256 addNum = 1;
        for (uint256 i = 0; i < maxBiddingNum; i++) {
            uint256 id = biddingId[i];
            if (id != 0) {
                Auction storage auction = tokenIdToAuction[id];
                if (_hasAuctionByInfo(auction)) {
                    if (!_isOnAuction(auction)) {
                        id = lastBiddingId + addNum;
                        addNum = addNum + 1;
                    }
                }
            } else {
                id = lastBiddingId + addNum;
                addNum = addNum + 1;
            }
            result[resultIndex] = id;
            resultIndex = resultIndex + 1;
            if (resultIndex == maxBiddingNum) {
                break;
            }
        }
        return result;
    }

    function _getGene(uint256 _id) internal view returns (uint256) {
        return geneScience.getAuctionGene(_id);
    }

    function _getBiddingGene(uint256 _id) internal view returns (uint256) {
        require(
            _id <= lastBiddingId || _isBidding(_id),
            "Auction: id must in bidding"
        );
        require(_id > 0, "Auction: id must gt 0");
        return _getGene(_id);
    }

    function _getBiddingGeneNoCheck(uint256 _id)
        internal
        view
        returns (uint256)
    {
        return _getGene(_id);
    }

    function _tokensOfOwnerAuctionOn(address _owner, bool on)
        internal
        view
        returns (uint256[] memory)
    {
        uint256[] memory list = _tokensOfOwnerAuction(_owner);
        uint256 num;
        for (uint256 i = 0; i < list.length; i++) {
            uint256 id = list[i];
            Auction storage auction = tokenIdToAuction[id];
            if (_isOnAuction(auction) == on) {
                num++;
            }
        }
        uint256 resultIndex = 0;
        uint256[] memory result = new uint256[](num);
        for (uint256 i = 0; i < list.length; i++) {
            uint256 id = list[i];
            Auction storage auction = tokenIdToAuction[id];
            if (_isOnAuction(auction) == on) {
                result[resultIndex] = id;
                resultIndex++;
                if (resultIndex >= num) {
                    break;
                }
            }
        }
        return result;
    }

    function _hasAuction(uint256 _id) internal view returns (bool) {
        // Get a reference to the auction struct
        Auction storage auction = tokenIdToAuction[_id];
        return auction.endAt > 0;
    }

    function _hasAuctionByInfo(Auction storage _auction)
        internal
        view
        returns (bool)
    {
        return _auction.endAt > 0;
    }

    /// @dev Computes the price and transfers winnings.
    /// Does NOT transfer ownership of token.
    function _bidFrom(
        address _buyer,
        uint256 _id,
        uint256 _bidAmount
    ) internal whenNotPaused {
        // Get a reference to the auction struct
        Auction storage auction = tokenIdToAuction[_id];
        if (!_hasAuctionByInfo(auction)) {
            _updateBidding();
            require(
                _isBiddingNoCheck(_id),
                "Auction: target id is not in the bidding"
            );
            auction.currentPrice = uint128(c_startingPrice);
            auction.endAt = uint64(block.number + c_duration);
        } else {
            require(
                _isBiddingNoCheck(_id),
                "Auction: target id is not in the bidding"
            );
        }

        // Explicitly check that this auction is currently live.
        // (Because of how Ethereum mappings work, we can't just count
        // on the lookup above failing. An invalid _id will just
        // return an auction object that is all zeros.)
        require(
            _isOnAuction(auction),
            "Auction: target id is not in the auction"
        );

        // Check that the bid is greater than or equal to the current price
        uint256 minPrice = auction.currentPrice;
        if (auction.buyer != address(0)) {
            minPrice = auction.currentPrice.add(c_minAddPrice);
        }
        require(_bidAmount >= minPrice, "Auction: underbid");

        if (auction.buyer != address(0)) {
            require(
                gaeToken.transferFrom(
                    _buyer,
                    auction.buyer,
                    auction.currentPrice
                ),
                "Auction: failed to transfer gae token to old buyer"
            );
            _removeTokenFromOwnerEnumerationAuction(auction.buyer, _id);
            uint256 inAmount = _bidAmount.sub(auction.currentPrice);
            require(
                gaeToken.transferFrom(_buyer, address(this), inAmount),
                "Auction: failed to transfer gae token to contract"
            );
        } else {
            require(
                gaeToken.transferFrom(_buyer, address(this), _bidAmount),
                "Auction: failed to transfer gae token to contract"
            );
        }
        auction.currentPrice = _bidAmount;
        auction.buyer = _buyer;
        auction.endAt = uint64(block.number + c_duration);
        _addTokenToOwnerEnumerationAuction(_buyer, _id);
        emit Bid(_id, _buyer, _bidAmount);
    }

    function _takeBid(uint256 _id) internal {
        // Get a reference to the auction struct
        Auction storage auction = tokenIdToAuction[_id];
        address buyer = auction.buyer;
        // Explicitly check that this auction is currently live.
        // (Because of how Ethereum mappings work, we can't just count
        // on the lookup above failing. An invalid _id will just
        // return an auction object that is all zeros.)
        require(_hasAuctionByInfo(auction), "Auction: no target auction");
        require(!_isOnAuction(auction), "Auction: target id still in auction");
        require(!auction.taked, "Auction: already take");
        require(buyer != address(0), "Auction: no buyer");

        alianaContract.createOfficialAliana(_getBiddingGeneNoCheck(_id), buyer);
        auction.taked = true;
        _removeTokenFromOwnerEnumerationAuction(buyer, _id);
        // Tell the world!
        emit TakeBid(_id, buyer, auction.currentPrice);
    }

    // _takeBids LP tokens from Mine.
    function _takeBids(uint32[] memory _tokenIds) internal {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            _takeBid(_tokenIds[i]);
        }
    }

    // _takeBids256 LP tokens from Mine.
    function _takeBids256(uint256[] memory _tokenIds) internal {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            _takeBid(_tokenIds[i]);
        }
    }

    /// @dev Adds an auction to the list of open auctions. Also fires the
    ///  AuctionCreated event.
    /// @param _tokenId The ID of the token to be put on auction.
    /// @param _auction Auction to add.
    function _addAuction(uint256 _tokenId, Auction memory _auction)
        internal
        whenNotPaused
    {
        // Require that all auctions have a duration of
        // at least one minute. (Keeps our math from getting hairy!)
        require(c_duration >= 1, "Auction: duration < 1");

        tokenIdToAuction[_tokenId] = _auction;
    }

    /// @dev Returns true if the NFT is on auction.
    /// @param _auction - Auction to check.
    function _isOnAuction(Auction storage _auction)
        internal
        view
        returns (bool)
    {
        if (_auction.endAt <= block.number || _auction.taked) {
            return false;
        }
        return true;
    }
}

/// @title Clock auction modified for sale of alianas
/// @notice We omit a fallback function to prevent accidental sends to this contract.
contract Auction is ClockAuctionBase {
    function isAuction() public pure returns (bool) {
        return true;
    }

    /// @dev Constructor creates a reference to the NFT ownership contract
    ///  and verifies the owner cut is in the valid range.
    /// @param _alianaAddress - address of a deployed contract implementing
    ///  the Nonfungible Interface.
    /// @param _cut - percent cut the owner takes on each auction, must be
    ///  between 0-10,000.
    constructor(
        IAliana _alianaAddress,
        uint256 _cut,
        IERC20 gaeToken,
        IGeneScience _geneAddr
    ) public ClockAuctionBase(gaeToken, _geneAddr) {
        require(_cut <= 10000, "Auction: cut too large");
        ownerCut = _cut;

        require(_alianaAddress.isAliana(), "Auction: not aliana");

        alianaContract = _alianaAddress;
    }

    /// @dev Returns auction info for an NFT on auction.
    /// @param _tokenId - ID of NFT on auction.
    function getAuction(uint256 _tokenId)
        external
        view
        returns (
            uint256 currentPrice,
            uint256 endAt,
            uint256 gene,
            uint256 lpLabor,
            address buyer,
            bool taked
        )
    {
        Auction storage auction = tokenIdToAuction[_tokenId];
        currentPrice = auction.currentPrice;
        endAt = auction.endAt;
        gene = _getBiddingGeneNoCheck(_tokenId);
        buyer = auction.buyer;
        taked = auction.taked;
        if (!_hasAuctionByInfo(auction)) {
            gene = _getBiddingGene(_tokenId);
            currentPrice = uint128(c_startingPrice);
        }
        lpLabor = alianaContract.geneLpLabor(int256(_tokenId), gene);
    }

    /// @dev Returns the current price of an auction.
    /// @param _tokenId - ID of the token price we are checking.
    function getCurrentPrice(uint256 _tokenId) external view returns (uint256) {
        return tokenIdToAuction[_tokenId].currentPrice;
    }

    function updateBidding() external {
        _updateBidding();
    }

    function biddingNum() external view returns (uint256) {
        return _biddingNum();
    }

    function biddingIdList() external view returns (uint256[] memory) {
        return _biddingIdList();
    }

    function getBiddingGene(uint256 _id) external view returns (uint256) {
        return _getBiddingGene(_id);
    }

    /// @notice Returns a list of all Aliana IDs assigned to an address.
    /// @param _owner The owner whose Kitties we are interested in.
    /// @dev This method MUST NEVER be called by smart contract code. First, it's fairly
    ///  expensive (it walks the entire Aliana array looking for cats belonging to owner),
    ///  but it also returns a dynamic array, which is only supported for web3 calls, and
    ///  not contract-to-contract calls.
    function tokensOfOwnerAuction(address _owner)
        external
        view
        returns (uint256[] memory)
    {
        return _tokensOfOwnerAuction(_owner);
    }

    function tokensOfOwnerAuctionOn(address _owner, bool on)
        external
        view
        returns (uint256[] memory)
    {
        return _tokensOfOwnerAuctionOn(_owner, on);
    }

    /// @dev Updates lastSalePrice if seller is the nft contract
    /// Otherwise, works the same as default bid method.
    function bid(uint32 _tokenId, uint256 _price) external {
        // _bid verifies token ID size
        _bidFrom(msg.sender, _tokenId, _price);
    }

    function takeBid(uint32 _tokenId) external {
        // _bid verifies token ID size
        _takeBid(_tokenId);
    }

    function takeBids(uint32[] calldata _tokenIds) external {
        _takeBids(_tokenIds);
    }

    // takeMyBids LP tokens from Mine.
    function takeMyBids() external {
        _takeBids256(_tokensOfOwnerAuctionOn(msg.sender, false));
    }

    // takeBidsOf LP tokens from Mine.
    function takeBidsOf(address addr) external {
        _takeBids256(_tokensOfOwnerAuctionOn(addr, false));
    }

    function receiveApproval(
        address _sender,
        uint256 _value,
        address _tokenContract,
        bytes memory _extraData
    ) public {
        require(_value > 0, "Auction: approval zero");
        uint256 action;
        assembly {
            action := mload(add(_extraData, 0x20))
        }
        require(action == 2, "Auction: unknow action");
        if (action == 2) {
            // buy
            require(
                _tokenContract == address(gaeToken),
                "Auction: approval and want buy a aliana, but used token isn't GFT"
            );
            uint256 tokenId;
            uint256 price;
            assembly {
                tokenId := mload(add(_extraData, 0x40))
                price := mload(add(_extraData, 0x60))
            }
            _bidFrom(_sender, tokenId, price);
        }
    }
}

pragma solidity ^0.5.0;

import "./aliana/GFAccessControl.sol";
import "@openzeppelin/contracts/token/ERC20/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./aliana/IAliana.sol";

/// @title all functions related to creating kittens
contract FakeAliana is GFAccessControl {
    using SafeMath for uint256;
    using SafeERC20 for IERC20;

    IAliana public aliana;

    // Info of each user that stakes LP tokens.
    mapping(address => bool) mixedFakeCard;

    event MixFake(address indexed user, uint256 id, uint256 newID);

    constructor(IAliana _alianaAddr) public {
        require(_alianaAddr.isAliana(), "FakeAliana: isAliana false");
        aliana = _alianaAddr;
    }

    function _mixFrom(address _from, uint256 _tokenId)
        internal
        whenNotPaused
        returns (uint256)
    {
        require(!mixedFakeCard[_from], "FakeAliana: insufficient balance");
        require(
            aliana.ownerOf(_tokenId) == _from,
            "FakeAliana: must be the owner"
        );
        mixedFakeCard[_from] = true;
        emit MixFake(_from, _tokenId, _tokenId);
        return _tokenId;
    }

    function mix(uint256 _tokenId) public returns (uint256) {
        return _mixFrom(msg.sender, _tokenId);
    }

    function haveFake(address _addr) public view returns (bool) {
        return !mixedFakeCard[_addr];
    }

    function receiveApproval(
        address _sender,
        uint256 _value,
        address _tokenContract,
        bytes memory _extraData
    ) public {
        require(_value >= 0, "FakeAliana: approval negative");
        uint256 action;
        assembly {
            action := mload(add(_extraData, 0x20))
        }
        require(action == 1, "FakeAliana: unknow action");
        if (action == 1) {
            // mix
            require(
                _tokenContract == address(aliana),
                "FakeAliana: approval and want mint use aliana, but used token isn't Aliana"
            );
            uint256 tokenId;
            assembly {
                tokenId := mload(add(_extraData, 0x40))
            }
            _mixFrom(_sender, tokenId);
        }
    }
}

pragma solidity ^0.5.0;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./aliana/GFAccessControl.sol";
import "./aliana/IAliana.sol";
import "./aliana/AuctionOwner.sol";
import "./math/SafeMath.sol";

/// @title Auction Core
/// @dev Contains models, variables, and internal methods for the auction.
/// @notice We omit a fallback function to prevent accidental sends to this contract.
contract FlashSaleBase is AuctionOwner, GFAccessControl {
    using SafeMath for uint256;
    uint256 maxBiddingNum;
    uint256[] biddingId;
    uint256 public lastBiddingId;
    uint256 c_startingPrice = 1e16; // 0.01 GFT
    uint256 c_duration = 50; // 300s
    uint256 c_minAddPrice = 1e16; // 0.01 GFT
    uint256 c_startBlockOffset; // begin of the block
    uint256 c_cycleBlock; // cycle time
    uint256 c_maxCycle; // max cycle

    // Represents an auction on an NFT
    struct Auction {
        uint256 currentPrice;
        address buyer;
        uint64 endAt;
        bool taked;
    }

    // Reference to contract tracking NFT ownership
    IAliana public alianaContract;

    // Cut owner takes on each auction, measured in basis points (1/100 of a percent).
    // Values 0-10,000 map to 0%-100%
    uint256 public ownerCut;

    // The gae TOKEN
    IERC20 public gaeToken;

    // Map from token ID to their corresponding auction.
    mapping(uint256 => Auction) tokenIdToAuction;

    struct GeneEntry {
        uint256 gene;
        bool used;
    }
    // Map from token ID to their gene value.
    mapping(uint256 => GeneEntry) tokenIdToGene;

    event TakeBid(
        uint256 indexed tokenId,
        address indexed winner,
        uint256 totalPrice
    );

    event Bid(uint256 indexed tokenId, address indexed buyer, uint256 price);

    constructor(IERC20 _gaeToken, uint256 _cycleBlock) public {
        gaeToken = _gaeToken;
        updateMaxBiddingNum(6);
        setStartBlockOffset(block.number);
        setCycleBlock(_cycleBlock);
    }

    function updateMaxBiddingNum(uint256 _value) public onlyCEO {
        maxBiddingNum = _value;
        for (uint256 i = maxBiddingNum; i < biddingId.length; i++) {
            Auction storage auction = tokenIdToAuction[biddingId[i]];
            require(
                !_hasAuctionByInfo(auction) || !_isOnAuction(auction),
                "FlashSale: reduced capacity auction in bidding"
            );
        }
        biddingId.length = maxBiddingNum;
        _updateBidding();
    }

    function getStartingPrice() public view returns (uint256) {
        return c_startingPrice;
    }

    function setStartingPrice(uint256 _value) public onlyCEO {
        c_startingPrice = _value;
    }

    function getCycleBlock() public view returns (uint256) {
        return c_cycleBlock;
    }

    function setCycleBlock(uint256 _cycleBlock) public onlyCEO {
        require(_cycleBlock > 0, "require _cycleBlock > 0");
        require(_cycleBlock > c_duration, "require _cycleBlock > c_duration");
        c_cycleBlock = _cycleBlock;
    }

    function getStartBlockOffset() public view returns (uint256) {
        return c_startBlockOffset;
    }

    function setStartBlockOffset(uint256 _startBlockOffset) public onlyCEO {
        require(
            _startBlockOffset <= block.number,
            "require _startBlockOffset <= block.number"
        );
        c_startBlockOffset = _startBlockOffset;
    }

    function getMaxCycle() public view returns (uint256) {
        return c_maxCycle;
    }

    function setMaxCycle(uint256 _maxCycle) public onlyCEO {
        c_maxCycle = _maxCycle;
    }

    function getDuration() public view returns (uint256) {
        return c_duration;
    }

    function setDuration(uint256 _value) public onlyCEO {
        require(_value > 0, "require _value > 0");
        require(c_cycleBlock > _value, "require c_cycleBlock > _value");
        c_duration = _value;
    }

    function getLatestActivity()
        public
        view
        returns (uint256 begin, uint256 end)
    {
        uint256 cycleNum = getCurrentCycleNum();
        if (cycleNum >= c_maxCycle) {
            return (0, 0);
        }
        end = c_startBlockOffset.add(cycleNum.add(1).mul(c_cycleBlock));
        begin = end.sub(c_duration);
        return (begin, end);
    }

    function isNowInActivity() public view returns (bool) {
        (uint256 begin, uint256 end) = getLatestActivity();
        return block.number >= begin && block.number < end;
    }

    function getCurrentCycleNum() public view returns (uint256) {
        uint256 n = block.number;
        return n.sub(c_startBlockOffset).div(c_cycleBlock);
    }

    function getMinAddPrice() public view returns (uint256) {
        return c_minAddPrice;
    }

    function setMinAddPrice(uint256 _value) public onlyCEO {
        c_minAddPrice = _value;
    }

    function minAddPrice() public view returns (uint256) {
        return c_minAddPrice;
    }

    function _updateBidding() internal {
        uint256 _lastBidding = lastBiddingId;
        for (uint256 i = 0; i < maxBiddingNum; i++) {
            uint256 id = biddingId[i];
            if (id != 0) {
                Auction storage auction = tokenIdToAuction[id];
                if (_hasAuctionByInfo(auction)) {
                    if (_isOnAuction(auction)) {
                        continue;
                    }
                } else {
                    continue;
                }
            }
            // set bidding id
            biddingId[i] = _lastBidding + 1;
            _lastBidding = _lastBidding + 1;
        }
        if (lastBiddingId != _lastBidding) {
            lastBiddingId = _lastBidding;
        }
    }

    function _isBidding(uint256 _id) internal view returns (bool) {
        uint256[] memory list = _biddingIdList();
        for (uint256 i = 0; i < list.length; i++) {
            if (list[i] == _id) {
                return true;
            }
        }
        return false;
    }

    function _isBiddingNoCheck(uint256 _id) internal view returns (bool) {
        for (uint256 i = 0; i < biddingId.length; i++) {
            if (biddingId[i] == _id) {
                return true;
            }
        }
        return false;
    }

    function _biddingNum() internal view returns (uint256) {
        return maxBiddingNum;
    }

    function _biddingIdList() internal view returns (uint256[] memory) {
        uint256[] memory result = new uint256[](maxBiddingNum);
        uint256 resultIndex = 0;
        uint256 addNum = 1;
        for (uint256 i = 0; i < maxBiddingNum; i++) {
            uint256 id = biddingId[i];
            if (id != 0) {
                Auction storage auction = tokenIdToAuction[id];
                if (_hasAuctionByInfo(auction)) {
                    if (!_isOnAuction(auction)) {
                        id = lastBiddingId + addNum;
                        addNum = addNum + 1;
                    }
                }
            } else {
                id = lastBiddingId + addNum;
                addNum = addNum + 1;
            }
            result[resultIndex] = id;
            resultIndex = resultIndex + 1;
            if (resultIndex == maxBiddingNum) {
                break;
            }
        }
        return result;
    }

    function _getGene(uint256 _id) internal view returns (uint256) {
        GeneEntry storage gene = tokenIdToGene[_id];
        require(gene.used, "target gene not set");
        return gene.gene;
    }

    function _getBiddingGene(uint256 _id) internal view returns (uint256) {
        require(
            _id <= lastBiddingId || _isBidding(_id),
            "FlashSale: id must in bidding"
        );
        require(_id > 0, "FlashSale: id must gt 0");
        return _getGene(_id);
    }

    function _getBiddingGeneNoCheck(uint256 _id)
        internal
        view
        returns (uint256)
    {
        return _getGene(_id);
    }

    function _tokensOfOwnerAuctionOn(address _owner, bool on)
        internal
        view
        returns (uint256[] memory)
    {
        uint256[] memory list = _tokensOfOwnerAuction(_owner);
        uint256 num;
        for (uint256 i = 0; i < list.length; i++) {
            uint256 id = list[i];
            Auction storage auction = tokenIdToAuction[id];
            if (_isOnAuction(auction) == on) {
                num++;
            }
        }
        uint256 resultIndex = 0;
        uint256[] memory result = new uint256[](num);
        for (uint256 i = 0; i < list.length; i++) {
            uint256 id = list[i];
            Auction storage auction = tokenIdToAuction[id];
            if (_isOnAuction(auction) == on) {
                result[resultIndex] = id;
                resultIndex++;
                if (resultIndex >= num) {
                    break;
                }
            }
        }
        return result;
    }

    function _hasAuction(uint256 _id) internal view returns (bool) {
        // Get a reference to the auction struct
        Auction storage auction = tokenIdToAuction[_id];
        return auction.endAt > 0;
    }

    function _hasAuctionByInfo(Auction storage _auction)
        internal
        view
        returns (bool)
    {
        return _auction.endAt > 0;
    }

    /// @dev Computes the price and transfers winnings.
    /// Does NOT transfer ownership of token.
    function _bidFrom(
        address _buyer,
        uint256 _id,
        uint256 _bidAmount
    ) internal whenNotPaused {
        require(isNowInActivity(), "not in activity");

        // Get a reference to the auction struct
        Auction storage auction = tokenIdToAuction[_id];
        if (!_hasAuctionByInfo(auction)) {
            _updateBidding();
            require(
                _isBiddingNoCheck(_id),
                "FlashSale: target id is not in the bidding"
            );
            auction.currentPrice = uint128(c_startingPrice);
            (, uint256 end) = getLatestActivity();
            auction.endAt = uint64(end);
        } else {
            require(
                _isBiddingNoCheck(_id),
                "FlashSale: target id is not in the bidding"
            );
        }

        // Explicitly check that this auction is currently live.
        // (Because of how Ethereum mappings work, we can't just count
        // on the lookup above failing. An invalid _id will just
        // return an auction object that is all zeros.)
        require(
            _isOnAuction(auction),
            "FlashSale: target id is not in the auction"
        );

        // Check that the bid is greater than or equal to the current price
        uint256 minPrice = auction.currentPrice;
        if (auction.buyer != address(0)) {
            minPrice = auction.currentPrice.add(c_minAddPrice);
        }
        require(_bidAmount >= minPrice, "FlashSale: underbid");

        if (auction.buyer != address(0)) {
            require(
                gaeToken.transferFrom(
                    _buyer,
                    auction.buyer,
                    auction.currentPrice
                ),
                "FlashSale: failed to transfer gae token to old buyer"
            );
            _removeTokenFromOwnerEnumerationAuction(auction.buyer, _id);
            uint256 inAmount = _bidAmount.sub(auction.currentPrice);
            require(
                gaeToken.transferFrom(_buyer, address(this), inAmount),
                "FlashSale: failed to transfer gae token to contract"
            );
        } else {
            require(
                gaeToken.transferFrom(_buyer, address(this), _bidAmount),
                "FlashSale: failed to transfer gae token to contract"
            );
        }
        auction.currentPrice = _bidAmount;
        auction.buyer = _buyer;
        _addTokenToOwnerEnumerationAuction(_buyer, _id);
        emit Bid(_id, _buyer, _bidAmount);
    }

    function _takeBid(uint256 _id) internal {
        // Get a reference to the auction struct
        Auction storage auction = tokenIdToAuction[_id];
        address buyer = auction.buyer;
        // Explicitly check that this auction is currently live.
        // (Because of how Ethereum mappings work, we can't just count
        // on the lookup above failing. An invalid _id will just
        // return an auction object that is all zeros.)
        require(_hasAuctionByInfo(auction), "FlashSale: no target auction");
        require(
            !_isOnAuction(auction),
            "FlashSale: target id still in auction"
        );
        require(!auction.taked, "FlashSale: already take");
        require(buyer != address(0), "FlashSale: no buyer");

        alianaContract.createOfficialAliana(_getBiddingGeneNoCheck(_id), buyer);
        auction.taked = true;
        _removeTokenFromOwnerEnumerationAuction(buyer, _id);
        // Tell the world!
        emit TakeBid(_id, buyer, auction.currentPrice);
    }

    // _takeBids LP tokens from Mine.
    function _takeBids(uint32[] memory _tokenIds) internal {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            _takeBid(_tokenIds[i]);
        }
    }

    // _takeBids256 LP tokens from Mine.
    function _takeBids256(uint256[] memory _tokenIds) internal {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            _takeBid(_tokenIds[i]);
        }
    }

    /// @dev Adds an auction to the list of open auctions. Also fires the
    ///  AuctionCreated event.
    /// @param _tokenId The ID of the token to be put on auction.
    /// @param _auction Auction to add.
    function _addAuction(uint256 _tokenId, Auction memory _auction)
        internal
        whenNotPaused
    {
        // Require that all auctions have a duration of
        // at least one minute. (Keeps our math from getting hairy!)
        require(c_duration >= 1, "FlashSale: duration < 1");

        tokenIdToAuction[_tokenId] = _auction;
    }

    /// @dev Returns true if the NFT is on auction.
    /// @param _auction - Auction to check.
    function _isOnAuction(Auction storage _auction)
        internal
        view
        returns (bool)
    {
        if (_auction.endAt <= block.number || _auction.taked) {
            return false;
        }
        return true;
    }
}

/// @title Clock auction modified for sale of alianas
/// @notice We omit a fallback function to prevent accidental sends to this contract.
contract FlashSale is FlashSaleBase {
    function isFlashSale() public pure returns (bool) {
        return true;
    }

    /// @dev Constructor creates a reference to the NFT ownership contract
    ///  and verifies the owner cut is in the valid range.
    /// @param _alianaAddress - address of a deployed contract implementing
    ///  the Nonfungible Interface.
    /// @param _cut - percent cut the owner takes on each auction, must be
    ///  between 0-10,000.
    constructor(
        IAliana _alianaAddress,
        uint256 _cut,
        IERC20 gaeToken,
        uint256 _cycleBlock
    ) public FlashSaleBase(gaeToken, _cycleBlock) {
        require(_cut <= 10000, "FlashSale: cut too large");
        ownerCut = _cut;

        require(_alianaAddress.isAliana(), "FlashSale: not aliana");

        alianaContract = _alianaAddress;
    }

    /// @dev Returns auction info for an NFT on auction.
    /// @param _tokenId - ID of NFT on auction.
    function getAuction(uint256 _tokenId)
        external
        view
        returns (
            uint256 currentPrice,
            uint256 endAt,
            uint256 gene,
            uint256 lpLabor,
            address buyer,
            bool taked
        )
    {
        Auction storage auction = tokenIdToAuction[_tokenId];
        currentPrice = auction.currentPrice;
        endAt = auction.endAt;
        gene = _getBiddingGeneNoCheck(_tokenId);
        buyer = auction.buyer;
        taked = auction.taked;
        if (!_hasAuctionByInfo(auction)) {
            gene = _getBiddingGene(_tokenId);
            currentPrice = uint128(c_startingPrice);
        }
        lpLabor = alianaContract.geneLpLabor(int256(_tokenId), gene);
    }

    /// @dev Returns the current price of an auction.
    /// @param _tokenId - ID of the token price we are checking.
    function getCurrentPrice(uint256 _tokenId) external view returns (uint256) {
        return tokenIdToAuction[_tokenId].currentPrice;
    }

    function updateBidding() external {
        _updateBidding();
    }

    function biddingNum() external view returns (uint256) {
        return _biddingNum();
    }

    function biddingIdList() external view returns (uint256[] memory) {
        return _biddingIdList();
    }

    function getBiddingGene(uint256 _id) external view returns (uint256) {
        return _getBiddingGene(_id);
    }

    /// @notice Returns a list of all Aliana IDs assigned to an address.
    /// @param _owner The owner whose Kitties we are interested in.
    /// @dev This method MUST NEVER be called by smart contract code. First, it's fairly
    ///  expensive (it walks the entire Aliana array looking for cats belonging to owner),
    ///  but it also returns a dynamic array, which is only supported for web3 calls, and
    ///  not contract-to-contract calls.
    function tokensOfOwnerAuction(address _owner)
        external
        view
        returns (uint256[] memory)
    {
        return _tokensOfOwnerAuction(_owner);
    }

    function tokensOfOwnerAuctionOn(address _owner, bool on)
        external
        view
        returns (uint256[] memory)
    {
        return _tokensOfOwnerAuctionOn(_owner, on);
    }

    /// @dev Updates lastSalePrice if seller is the nft contract
    /// Otherwise, works the same as default bid method.
    function bid(uint32 _tokenId, uint256 _price) external {
        // _bid verifies token ID size
        _bidFrom(msg.sender, _tokenId, _price);
    }

    function takeBid(uint32 _tokenId) external {
        // _bid verifies token ID size
        _takeBid(_tokenId);
    }

    function takeBids(uint32[] calldata _tokenIds) external {
        _takeBids(_tokenIds);
    }

    function setTokenGene(
        uint256[] calldata _tokenIds,
        uint256[] calldata _gene
    ) external onlyCEO {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            tokenIdToGene[_tokenIds[i]].gene = _gene[i];
            tokenIdToGene[_tokenIds[i]].used = true;
        }
    }

    function unsetTokenGene(uint256[] calldata _tokenIds) external onlyCEO {
        for (uint256 i = 0; i < _tokenIds.length; i++) {
            tokenIdToGene[_tokenIds[i]].used = false;
        }
    }

    // takeMyBids LP tokens from Mine.
    function takeMyBids() external {
        _takeBids256(_tokensOfOwnerAuctionOn(msg.sender, false));
    }

    // takeBidsOf LP tokens from Mine.
    function takeBidsOf(address addr) external {
        _takeBids256(_tokensOfOwnerAuctionOn(addr, false));
    }

    function receiveApproval(
        address _sender,
        uint256 _value,
        address _tokenContract,
        bytes memory _extraData
    ) public {
        require(_value > 0, "FlashSale: approval zero");
        uint256 action;
        assembly {
            action := mload(add(_extraData, 0x20))
        }
        require(action == 2, "FlashSale: unknow action");
        if (action == 2) {
            // buy
            require(
                _tokenContract == address(gaeToken),
                "FlashSale: approval and want buy a aliana, but used token isn't GFT"
            );
            uint256 tokenId;
            uint256 price;
            assembly {
                tokenId := mload(add(_extraData, 0x40))
                price := mload(add(_extraData, 0x60))
            }
            _bidFrom(_sender, tokenId, price);
        }
    }
}

