import "./math/SafeMath.sol";
import "./token/IERC20.sol";
import "./token/IERC223.sol";
import "./token/ISmartToken.sol";
import "./token/DSToken.sol";
import "./token/IApproveAndCallFallBack.sol";
import "./token/ITokenController.sol";
import "./token/IERC223Receiving.sol";

contract GFS is DSToken("GFS", "Game Fantasy Star"), IERC223, ISmartToken {
    using SafeMath for uint256;
    address private _newOwner;
    bool public _transfersEnabled = true; // true if transfer/transferFrom are enabled, false if not

    uint256 private _cap;

    address private _controller;

    // allows execution only when transfers aren't disabled
    modifier transfersAllowed() {
        assert(_transfersEnabled);
        _;
    }

    constructor() public {
        _controller = msg.sender;
        uint256 perCoin = 1e18;
        _cap = perCoin.mul(3000 * 10000);
    }

    //////////
    // IOwned Methods
    //////////

    /**
        @dev allows transferring the contract ownership
        the new owner still needs to accept the transfer
        can only be called by the contract owner
        @param newOwner_    new contract owner
    */
    function transferOwnership(address newOwner_) public auth {
        require(newOwner_ != _owner, "GFS-already-an-owner");
        _newOwner = newOwner_;
    }

    /**
        @dev used by a new owner to accept an ownership transfer
    */
    function acceptOwnership() public {
        require(msg.sender == _newOwner, "GFS-not-new-owner");
        _owner = _newOwner;
        _newOwner = address(0);
    }

    //////////
    // SmartToken Methods
    //////////
    /**
        @dev disables/enables transfers
        can only be called by the contract owner
        @param disable_    true to disable transfers, false to enable them
    */
    function disableTransfers(bool disable_) public auth {
        _transfersEnabled = !disable_;
    }

    function issue(address to_, uint256 amount_) public auth stoppable {
        mint(to_, amount_);
    }

    //////////
    // Cap Methods
    //////////
    function cap() public view returns (uint256) {
        return _cap;
    }

    //////////
    // Cap Methods
    //////////
    function changeCap(uint256 newCap_) public auth {
        require(newCap_ >= totalSupply());

        _cap = newCap_;
    }

    //////////
    // Controller Methods
    //////////
    /// @notice Changes the _controller of the contract
    /// @param newController_ The new _controller of the contract
    function changeController(address newController_) public auth {
        _controller = newController_;
    }

    /// @notice Send `amount_` tokens to `to_` from `from_` on the condition it
    ///  is approved by `from_`
    /// @param from_ The address holding the tokens being transferred
    /// @param to_ The address of the recipient
    /// @param amount_ The amount of tokens to be transferred
    /// @return True if the transfer was successful
    function transferFrom(
        address from_,
        address to_,
        uint256 amount_
    ) public transfersAllowed returns (bool success) {
        // Alerts the token _controller of the transfer
        if (isContract(_controller)) {
            if (!ITokenController(_controller).onTransfer(from_, to_, amount_))
                revert();
        }

        success = super.transferFrom(from_, to_, amount_);
    }

    /*
     * ERC 223
     * Added support for the ERC 223 "tokenFallback" method in a "transfer" function with a payload.
     */
    function transferFrom(
        address from_,
        address to_,
        uint256 amount_,
        bytes memory data_
    ) public transfersAllowed returns (bool success) {
        // Alerts the token _controller of the transfer
        if (isContract(_controller)) {
            if (!ITokenController(_controller).onTransfer(from_, to_, amount_))
                revert();
        }

        require(
            super.transferFrom(from_, to_, amount_),
            "GFS-insufficient-balance"
        );

        if (isContract(to_)) {
            IERC223Receiving receiver = IERC223Receiving(to_);
            receiver.tokenFallback(from_, amount_, data_);
        }

        emit ERC223Transfer(from_, to_, amount_, data_);

        return true;
    }

    /*
     * ERC 223
     * Added support for the ERC 223 "tokenFallback" method in a "transfer" function with a payload.
     * https://github.com/ethereum/EIPs/issues/223
     * function transfer(address to_, uint256 value_, bytes memory data_) public returns (bool success);
     */
    /// @notice Send `value_` tokens to `to_` from `msg.sender` and trigger
    /// tokenFallback if sender is a contract.
    /// @dev Function that is called when a user or another contract wants to transfer funds.
    /// @param to_ Address of token receiver.
    /// @param amount_ Number of tokens to transfer.
    /// @param data_ Data to be sent to tokenFallback
    /// @return Returns success of function call.
    function transfer(
        address to_,
        uint256 amount_,
        bytes memory data_
    ) public returns (bool success) {
        return transferFrom(msg.sender, to_, amount_, data_);
    }

    /// @notice `msg.sender` approves `spender_` to spend `amount_` tokens on
    ///  its behalf. This is a modified version of the ERC20 approve function
    ///  to be a little bit safer
    /// @param spender_ The address of the account able to transfer the tokens
    /// @param amount_ The amount of tokens to be approved for transfer
    /// @return True if the approval was successful
    function approve(address spender_, uint256 amount_)
        public
        returns (bool success)
    {
        // Alerts the token _controller of the approve function call
        if (isContract(_controller)) {
            if (
                !ITokenController(_controller).onApprove(
                    msg.sender,
                    spender_,
                    amount_
                )
            ) revert();
        }

        return super.approve(spender_, amount_);
    }

    function mint(address guy_, uint256 wad_) public auth stoppable {
        require(totalSupply().add(wad_) <= _cap, "GFS-insufficient-cap");

        super.mint(guy_, wad_);

        emit Transfer(address(0), guy_, wad_);
    }

    function burn(address guy_, uint256 wad_) public auth stoppable {
        super.burn(guy_, wad_);

        emit Transfer(guy_, address(0), wad_);
    }

    /// @notice `msg.sender` approves `spender_` to send `amount_` tokens on
    ///  its behalf, and then a function is triggered in the contract that is
    ///  being approved, `spender_`. This allows users to use their tokens to
    ///  interact with contracts in one function call instead of two
    /// @param spender_ The address of the contract able to transfer the tokens
    /// @param amount_ The amount of tokens to be approved for transfer
    /// @return True if the function call was successful
    function approveAndCall(
        address spender_,
        uint256 amount_,
        bytes memory extraData_
    ) public returns (bool success) {
        if (!approve(spender_, amount_)) revert();

        IApproveAndCallFallBack(spender_).receiveApproval(
            msg.sender,
            amount_,
            address(this),
            extraData_
        );

        return true;
    }

    /// @dev Internal function to determine if an address is a contract
    /// @param addr_ The address being queried
    /// @return True if `addr_` is a contract
    function isContract(address addr_) internal view returns (bool) {
        uint256 size;
        if (addr_ == address(0)) return false;
        assembly {
            size := extcodesize(addr_)
        }
        return size > 0;
    }

    /// @notice The fallback function: If the contract's _controller has not been
    ///  set to 0, then the `proxyPayment` method is called which relays the
    ///  ether and creates tokens as described in the token _controller contract
    function() external payable {
        if (isContract(_controller)) {
            if (
                !ITokenController(_controller).proxyPayment.value(msg.value)(
                    msg.sender,
                    msg.sig,
                    msg.data
                )
            ) revert();
        } else {
            revert();
        }
    }

    //////////
    // Safety Methods
    //////////

    /// @notice This method can be used by the owner to extract mistakenly
    ///  sent tokens to this contract.
    /// @param token_ The address of the token contract that you want to recover
    ///  set to 0 in case you want to extract ether.
    function claimTokens(address token_) public auth {
        if (token_ == address(0)) {
            address(msg.sender).transfer(address(this).balance);
            return;
        }

        IERC20 token = IERC20(token_);
        uint256 balance = token.balanceOf(address(this));
        token.transfer(address(msg.sender), balance);

        emit ClaimedTokens(token_, address(msg.sender), balance);
    }

    function withdrawTokens(
        IERC20 token_,
        address to_,
        uint256 amount_
    ) public auth {
        assert(token_.transfer(to_, amount_));
    }

    ////////////////
    // Events
    ////////////////

    event ClaimedTokens(
        address indexed token_,
        address indexed controller_,
        uint256 amount_
    );
}

pragma solidity ^0.5.0;

import "@openzeppelin/contracts/token/ERC20/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./token/IMintableToken.sol";
import "./aliana/GFAccessControl.sol";

// GFSBonus is the master of Mintlone tokens. He can make Mint and he is a fair guy.
//
// Note that it's ownable and the owner wields tremendous power. The ownership
// will be transferred to a governance smart contract once Mint is sufficiently
// distributed and the community can show to govern itself.
//
// Have fun reading it. Hopefully it's bug-free. God bless.
contract GFSBonus is GFAccessControl {
    using SafeMath for uint256;
    using SafeERC20 for IERC20;

    // Info of each user.
    struct UserInfo {
        uint256 amount; // How many LP tokens the user has provided.
        uint256 rewardDebt; // Reward debt. See explanation below.
        //
        // We do some fancy math here. Basically, any point in time, the amount of Mints
        // entitled to a user but is pending to be distributed is:
        //
        //   pending reward = (user.amount * accMintPerShare) - user.rewardDebt
        //
        // Whenever a user deposits or withdraws LP tokens to a pool. Here's what happens:
        //   1. Update accMintPerShare and lastRewardBlock
        //   2. User receives the pending reward sent to his/her address.
        //   3. User's `amount` gets updated.
        //   4. User's `rewardDebt` gets updated.
    }

    // Address of LP token contract.
    IERC20 public gfsToken;
    // Accumulated Mints per share, times 1e12. See below.
    uint256 public accMintPerShare;
    // Last block reward block height
    uint256 public lastRewardBlock;
    // Reward per block
    uint256 public rewardPerBlock;
    // Reward number
    uint256 public totalRewardNum;
    // already take reward number
    uint256 public takeRewardNum;
    // total Reward debt
    uint256 public totalRewardDebt;
    // total amount
    uint256 public totalAmount;

    // The Mintlone TOKEN
    IERC20 public mintToken;

    // Info of each user that stakes LP tokens.
    mapping(address => UserInfo) public userInfo;

    event RewardAdded(uint256 amount);
    event TakeReward(address indexed user, uint256 amount);
    event Deposit(address indexed user, uint256 amount);
    event Withdraw(address indexed user, uint256 amount);
    event EmergencyWithdraw(address indexed user, uint256 amount);

    constructor(IMintableToken _mintToken, IERC20 _gfsToken) public {
        mintToken = _mintToken;
        lastRewardBlock = block.number;
        gfsToken = _gfsToken;
        // times 1e10. See below.
        uint256 defaultPerDayIn5SecBlock = 100;
        setRewardPerBlock(
            defaultPerDayIn5SecBlock.mul(1e18).div((24 * 60 * 60) / 5)
        );
    }

    function setRewardPerBlock(uint256 _rewardPerBlock) public onlyCEO {
        updateBlockReward();
        rewardPerBlock = _rewardPerBlock;
    }

    // View function to see pending reward on frontend.
    function pendingReward(address _user) external view returns (uint256) {
        UserInfo storage user = userInfo[_user];
        if (rewardPerBlock == 0) {
            return 0;
        }
        if (block.number <= lastRewardBlock || totalAmount == 0) {
            return 0;
        }
        uint256 reward = getReward();
        return
            user
                .amount
                .mul(accMintPerShare.add(reward.mul(1e12).div(totalAmount)))
                .div(1e12)
                .sub(user.rewardDebt);
    }

    // Get reward variables to be up-to-date.
    function getReward() public view returns (uint256) {
        uint256 untakeReward = totalAmount.mul(accMintPerShare).div(1e12).sub(
            totalRewardDebt
        );
        uint256 reward = block.number.sub(lastRewardBlock).mul(rewardPerBlock);
        uint256 mintTokenLeft = mintToken.balanceOf(address(this));
        if (mintTokenLeft < untakeReward) {
            mintTokenLeft = 0;
        } else {
            mintTokenLeft = mintTokenLeft.sub(untakeReward);
        }
        if (mintTokenLeft < reward) {
            reward = mintTokenLeft;
        }
        uint256 leftReward = totalRewardNum.sub(takeRewardNum);
        if (leftReward < untakeReward) {
            leftReward = 0;
        } else {
            leftReward = leftReward.sub(untakeReward);
        }
        if (leftReward < reward) {
            reward = leftReward;
        }
        return reward;
    }

    // Add reward variables to be up-to-date.
    function addReward(uint256 _amount) public onlyCLevelOrWhitelisted {
        updateBlockReward();
        totalRewardNum = totalRewardNum.add(_amount);
        updateBlockReward();
        emit RewardAdded(_amount);
    }

    // Update reward variables to be up-to-date.
    function updateBlockReward() public {
        if (block.number <= lastRewardBlock || rewardPerBlock == 0) {
            return;
        }
        if (totalAmount == 0) {
            lastRewardBlock = block.number;
            return;
        }
        uint256 reward = getReward();
        lastRewardBlock = block.number;
        accMintPerShare = accMintPerShare.add(
            reward.mul(1e12).div(totalAmount)
        );
    }

    // Deposit LP tokens to GFSBonus for Mint allocation.
    function deposit(uint256 _amount) public {
        _depositFrom(msg.sender, _amount);
    }

    // Deposit LP tokens to GFSBonus for Mint allocation.
    function _depositFrom(address _from, uint256 _amount)
        internal
        whenNotPaused
    {
        updateBlockReward();
        UserInfo storage user = userInfo[_from];
        uint256 oldRewardDebt = user.rewardDebt;
        uint256 oldAmount = user.amount;
        if (user.amount > 0) {
            uint256 pending = user.amount.mul(accMintPerShare).div(1e12).sub(
                user.rewardDebt
            );
            if (pending > 0) {
                sendWithdraw(_from, pending);
            }
        }
        if (_amount > 0) {
            gfsToken.safeTransferFrom(address(_from), address(this), _amount);
            user.amount = user.amount.add(_amount);
        }
        user.rewardDebt = user.amount.mul(accMintPerShare).div(1e12);
        totalRewardDebt = totalRewardDebt.sub(oldRewardDebt).add(
            user.rewardDebt
        );
        totalAmount = totalAmount.sub(oldAmount).add(user.amount);
        emit Deposit(_from, _amount);
    }

    // Withdraw LP tokens from GFSBonus.
    function withdraw(uint256 _amount) public whenNotPaused {
        UserInfo storage user = userInfo[msg.sender];
        require(user.amount >= _amount, "withdraw: not good");
        uint256 oldRewardDebt = user.rewardDebt;
        uint256 oldAmount = user.amount;
        updateBlockReward();
        uint256 pending = user.amount.mul(accMintPerShare).div(1e12).sub(
            user.rewardDebt
        );
        if (pending > 0) {
            sendWithdraw(msg.sender, pending);
        }
        if (_amount > 0) {
            user.amount = user.amount.sub(_amount);
            gfsToken.safeTransfer(address(msg.sender), _amount);
        }
        user.rewardDebt = user.amount.mul(accMintPerShare).div(1e12);
        totalRewardDebt = totalRewardDebt.sub(oldRewardDebt).add(
            user.rewardDebt
        );
        totalAmount = totalAmount.sub(oldAmount).add(user.amount);
        emit Withdraw(msg.sender, _amount);
    }

    // Withdraw without caring about rewards. EMERGENCY ONLY.
    function emergencyWithdraw() public {
        UserInfo storage user = userInfo[msg.sender];
        uint256 oldRewardDebt = user.rewardDebt;
        uint256 oldAmount = user.amount;
        uint256 amount = user.amount;
        user.amount = 0;
        user.rewardDebt = 0;
        gfsToken.safeTransfer(address(msg.sender), amount);
        totalRewardDebt = totalRewardDebt.sub(oldRewardDebt).add(
            user.rewardDebt
        );
        totalAmount = totalAmount.sub(oldAmount).add(user.amount);
        emit EmergencyWithdraw(msg.sender, amount);
    }

    // Safe Mint transfer function, just in case if rounding error causes pool to not have enough Mints.
    function sendWithdraw(address _to, uint256 _amount) internal {
        require(
            mintToken.transfer(_to, _amount),
            "failed to transfer Mint token"
        );
        takeRewardNum = takeRewardNum.add(_amount);
        emit TakeReward(_to, _amount);
    }

    event ReceiveApproval(
        address _sender,
        uint256 _value,
        address _tokenContract,
        bytes _extraData,
        uint256 action
    );

    function receiveApproval(
        address _sender,
        uint256 _value,
        address _tokenContract,
        bytes memory _extraData
    ) public {
        require(_value > 0, "approval zero");
        uint256 action;
        assembly {
            action := mload(add(_extraData, 0x20))
        }
        emit ReceiveApproval(
            _sender,
            _value,
            _tokenContract,
            _extraData,
            action
        );
        require(action == 3, "unknow action");
        if (action == 3) {
            // deposit
            require(
                _tokenContract == address(gfsToken),
                "approval and want deposit, but used token isn't GFT"
            );
            uint256 amount;
            assembly {
                amount := mload(add(_extraData, 0x40))
            }
            _depositFrom(_sender, amount);
        }
    }
}

