interface IWUSDMaster {
    function withdrawWex(uint256 amount) external;
}

contract WexWithdrawer is Ownable {
    using SafeERC20 for IERC20;

    IERC20 public immutable wex;
    IWUSDMaster public wusdMaster;

    bool public isMasterChangeInitiated = false;
    uint256 public masterChangeTimestamp;
    IWUSDMaster public newWusdMaster;

    event Withdraw(uint256 amount);
    event Deposit(uint256 amount);
    event InitiateMasterChange(uint256 timestamp, address master);
    event CancelMasterChange();
    event MasterChanged(address master);

    constructor(IERC20 _wex, IWUSDMaster _wusdMaster) {
        require(
            address(_wex) != address(0) &&
            address(_wusdMaster) != address(0),
            "zero address in constructor"
        );
        wex = _wex;
        wusdMaster = _wusdMaster;
    }

    function withdraw(uint256 amount) external onlyOwner {
        wusdMaster.withdrawWex(amount);

        emit Withdraw(amount);
    }

    function deposit(uint256 amount) external onlyOwner {
        wex.safeTransfer(address(wusdMaster), amount);

        emit Deposit(amount);
    }

    function initiateMasterChange(uint256 timestamp, IWUSDMaster _wusdMaster) external onlyOwner {
        require(!isMasterChangeInitiated, 'change already initiated');
        require(timestamp >= block.timestamp + 48 hours, 'timestamp not valid!');
        require(address(_wusdMaster) != address(0),"zero address");

        isMasterChangeInitiated = true;
        masterChangeTimestamp = timestamp;
        newWusdMaster = _wusdMaster;

        emit InitiateMasterChange(timestamp, address(_wusdMaster));
    }

    function cancelMasterChange() external onlyOwner {
        require(isMasterChangeInitiated, 'change not initiated');

        isMasterChangeInitiated = false;
        masterChangeTimestamp = 0;
        newWusdMaster = IWUSDMaster(address(0));

        emit CancelMasterChange();
    }

    function changeMaster() external onlyOwner {
        require(isMasterChangeInitiated, 'change not initiated');
        require(block.timestamp >= masterChangeTimestamp, 'not yet possible');

        wusdMaster = newWusdMaster;

        isMasterChangeInitiated = false;
        masterChangeTimestamp = 0;
        newWusdMaster = IWUSDMaster(address(0));

        emit MasterChanged(address(wusdMaster));
    }
}

