contract TwoKeyUpgradableExchange is Crowdsale, Ownable {

	address filler;

	event TokenSell(address indexed purchaser, address indexed beneficiary, uint256 value, uint256 amount);

	modifier onlyAlive() {
		require(filler == address(0));
		_;
	}

	constructor(uint256 _rate, address _wallet, ERC20 _token)
		Crowdsale(_rate, _wallet, _token) Ownable() public {
	}

	function sellTokens(uint256 _tokenAmount) public onlyAlive payable {
		require(token.allowance(this, msg.sender) >= _tokenAmount);
		require(token.transferFrom(msg.sender, this, _tokenAmount));

		uint256 weiAmount = _getWeiAmount(_tokenAmount);
		require(weiAmount >= address(this).balance);
	    weiRaised = weiRaised.sub(weiAmount);
	    msg.sender.transfer(weiAmount);

	    emit TokenSell(msg.sender, wallet, weiAmount, _tokenAmount);
	}

	function _getWeiAmount(uint256 _tokenAmount) internal view returns (uint256) {
	    return _tokenAmount.div(rate);
	}

	function upgrade(address _to) public onlyAlive onlyOwner {
		filler = _to;
	}

	function() external payable {
		if (filler != address(0))
			filler.transfer(msg.value);
	}

	function buyTokens(address _beneficiary) public onlyAlive payable {
		super.buyTokens(_beneficiary);
	}

}

pragma solidity ^0.4.24;

import '../../contracts/openzeppelin-solidity/contracts/token/ERC20/StandardToken.sol';

import '../../contracts/openzeppelin-solidity/contracts/token/ERC20/ERC20.sol';
import '../../contracts/openzeppelin-solidity/contracts/ownership/Ownable.sol';
import '../../contracts/openzeppelin-solidity/contracts/math/SafeMath.sol';

import './TwoKeyReg.sol';
import "../../contracts/2key/libraries/GetCode.sol";

contract TwoKeyVoteToken is StandardToken, Ownable {
  using SafeMath for uint256;

  string public name = 'TwoKeyVote';
  string public symbol = '2KV';
  uint8 public decimals = 18;

  constructor() Ownable() public {
//    totalSupply_ = 1000000000000000000000000000;
//    balances[msg.sender] = totalSupply_;
  }

  TwoKeyReg public registry;
  mapping(address => bool) private visited;
  ///Mapping contract bytecode to boolean if is allowed to transfer tokens
  mapping(bytes32 => bool) private canEmit;


  function setRegistry(address _registry) public onlyOwner {
    registry = TwoKeyReg(_registry);
  }

  /// @notice function where admin or any authorized person (will be added if needed) can add more contracts to allow them call methods
  /// @param _contractAddress is actually the address of contract we'd like to allow
  /// @dev We first fetch bytes32 contract code and then update our mapping
  /// @dev only admin can call this or an authorized person
  function addContract(address _contractAddress) public onlyOwner {
    require(_contractAddress != address(0), 'addContract zero');
    bytes memory _contractCode = GetCode.at(_contractAddress);
    bytes32 cc = keccak256(abi.encodePacked(_contractCode));
    canEmit[cc] = true;
  }
  ///@notice Modifier which will only allow allowed contracts to transfer tokens
  function allowedContract() private view returns (bool) {
    //just to use contract code instead of msg.sender address
    bytes memory code = GetCode.at(msg.sender);
    bytes32 cc = keccak256(abi.encodePacked(code));
    return canEmit[cc];
    return true;
  }
  modifier onlyAllowedContracts {
    require(allowedContract(), 'onlyAllowedContracts');
    _;
  }

  /**
  * @dev Gets or Create the balance of the specified address.
  * @param _owner The address to query the the balance of.
  * @return An uint256 representing the amount owned by the passed address.
  */

  function checkBalance(address _owner) internal returns (uint256) {
    if (visited[_owner] || balances[_owner] > 0) {  // A user can have a balance if it was transfered to it
      return balances[_owner];
    }

    visited[_owner] = true;
    bytes memory _name = bytes(registry.owner2name(_owner));
    if (_name.length != 0) {
      balances[_owner] = 1000000000000000000;
    }
    return balances[_owner];
  }

  /**
  * @dev Gets the balance of the specified address.
  * @param _owner The address to query the the balance of.
  * @return An uint256 representing the amount owned by the passed address.
  */
  function balanceOf(address _owner) public view returns (uint256) {
    if (visited[_owner] || balances[_owner] > 0) {
      return balances[_owner];
    } else {
      bytes memory _name = bytes(registry.owner2name(_owner));
      if (_name.length != 0) {
        return 1000000000000000000;
      } else {
        return 0;
      }
    }
  }

  /**
   * @dev Transfer tokens from one address to another
   * @param _from address The address which you want to send tokens from
   * @param _to address The address which you want to transfer to
   * @param _value uint256 the amount of tokens to be transferred
   */
  function transferFrom(
    address _from,
    address _to,
    uint256 _value
  )
  public
  onlyAllowedContracts
  returns (bool)
  {
    uint balance = checkBalance(_from);
    require(_value <= balance, 'transferFrom balance');
    require(_to != address(0), 'transferFrom zero');

    // TODO make sure _to is registered OR it is a campaign contract

    balances[_from] = balances[_from].sub(_value);
    balances[_to] = balances[_to].add(_value);
    emit Transfer(_from, _to, _value);
    return true;
  }

  /**
   * @dev Function to check the amount of tokens that an owner allowed to a spender.
   * @param _owner address The address which owns the funds.
   * @return A uint256 specifying the amount of tokens still available for the spender.
   */
  function allowance(
    address _owner,
    address _spender
  )
  public
  view
  returns (uint256)
  {
    return balanceOf(_owner);  // TODO this is true only if the _spender is a valid contract
  }

  /**
  * @dev Total number of tokens in existence
  */
  function totalSupply() public view returns (uint256) {
    revert("totalSupply - not supported");
    return 0;
  }

  /**
  * @dev Transfer token for a specified address
  */
  function transfer(address, uint256) public returns (bool) {
    revert("transfer - not supported");
    return false;
  }

  function approve(address, uint256) public returns (bool) {
    revert("approve - not supported");
    return false;
  }
}

// Voting.sol
// Enigma, 2018
// Implement secret voting.

pragma solidity ^0.4.24;

import "./Enigma.sol"; // ../../../enigmampc/secret-contracts/contracts/

contract TwoKeyVotingContract {
  using SafeMath for uint;

  /* EVENTS */
  event voteCasted(address voter, bytes vote);
  event pollCreated(address creator, uint quorumPercentage, string description, uint votingLength);
  event pollStatusUpdate(bool status);

  /* Determine the current state of a poll */
  enum PollStatus { IN_PROGRESS, TALLY, PASSED, REJECTED }

  /* POLL */
  struct Poll {
    address creator;
    PollStatus status;
    uint quorumPercentage;
    uint yeaVotes;
    uint nayVotes;
    string description;
    address[] voters;
    uint expirationTime;
    mapping(address => Voter) voterInfo;
  }

  /* VOTER */
  struct Voter {
    bool hasVoted;
    bytes vote;
  }

  /* STATE VARIABLES */
  Poll public polls;
  Enigma public enigma;

  /* CONSTRUCTOR */
  constructor(address _token, address _enigma) public {
//    require(_token != 0 && address(token) == 0);
    require(_enigma != 0 && address(enigma) == 0);
    enigma = Enigma(_enigma);
  }

  /* POLL OPERATIONS */

  /*
   * Creates a new poll with a specified quorum percentage.
   */
  function createPoll(uint _quorumPct, string _description, uint _voteLength) public {
    require(_quorumPct <= 100, "Quorum Percentage must be less than or equal to 100%");
    require(_voteLength > 0, "The voting period cannot be 0.");

    polls.creator = msg.sender;
    polls.status = PollStatus.IN_PROGRESS;
    polls.quorumPercentage = _quorumPct;
    polls.expirationTime = now + _voteLength * 1 seconds;
    polls.description = _description;

    emit pollCreated(msg.sender, _quorumPct, _description, _voteLength);
  }

  /*
   * Ends a poll. Only the creator of a given poll can end that poll.
   */
  function endPoll() external  {
    require(msg.sender == polls.creator, "User is not the creator of the poll.");
    require(polls.status == PollStatus.IN_PROGRESS, "Vote is not in progress.");
    require(now >= getPollExpirationTime(), "Voting period has not expired");
    polls.status = PollStatus.TALLY;
  }

  /*
   * The callback function. Checks if a poll was passed given the quorum percentage and vote distribution.
   * NOTE: Only the Enigma contract can call this function.
   */
  function updatePollStatus(uint _yeaVotes, uint _nayVotes) public onlyEnigma() {
    require(getPollStatus() == PollStatus.TALLY, "Poll has not expired yet.");
    polls.yeaVotes = _yeaVotes;
    polls.nayVotes = _nayVotes;

    bool pollStatus = (polls.yeaVotes.mul(100)) > polls.quorumPercentage.mul(polls.yeaVotes.add(polls.nayVotes));
    if (pollStatus) {
      polls.status = PollStatus.PASSED;
    }
    else {
      polls.status = PollStatus.REJECTED;
    }

    emit pollStatusUpdate(pollStatus);
  }

  /*
   * Gets the status of a poll.
   */
  function getPollStatus() public view returns (PollStatus) {
    return polls.status;
  }

  /*
   * Gets the expiration date of a poll.
   */
  function getPollExpirationTime() public view returns (uint) {
    return polls.expirationTime;
  }

  /*
   * Gets a voter's encrypted vote for a given expired poll.
   */
  function getPollInfoForVoter(address _voter) public view returns (bytes) {
    require(getPollStatus() != PollStatus.IN_PROGRESS);
    require(userHasVoted(_voter));
    return polls.voterInfo[_voter].vote;
  }

  /*
   * Gets all the voters of a poll.
   */
  function getVotersForPoll() public view returns (address[]) {
    require(getPollStatus() != PollStatus.IN_PROGRESS);
    return polls.voters;
  }

  /*
   * Modifier that checks that the contract caller is the Enigma contract.
   */
  modifier onlyEnigma() {
    require(msg.sender == address(enigma));
    _;
  }

  /* VOTE OPERATIONS */

  /*
   * Casts a vote for a given poll.
   */
  function castVote(bytes _encryptedVote) external {
    require(getPollStatus() == PollStatus.IN_PROGRESS, "Poll has expired.");
    require(!userHasVoted(msg.sender), "User has already voted.");
    require(getPollExpirationTime() > now);

    polls.voterInfo[msg.sender] = Voter({
      hasVoted: true,
      vote: _encryptedVote
      });

    polls.voters.push(msg.sender);

    emit voteCasted(msg.sender, _encryptedVote);
  }

  /*
   * The callable function that is computed by the SGX node. Tallies votes.
   */
  function countVotes(uint[] _votes, uint weight) public pure returns (uint, uint) {
    uint yeaVotes;
    uint nayVotes;
    for (uint i = 0; i < _votes.length; i++) {
      if (_votes[i] == 0) nayVotes += weight;
      else if (_votes[i] == 1) yeaVotes += weight;
    }
    return (yeaVotes, nayVotes);
  }

  /*
   * Checks if a user has voted for a specific poll.
   */
  function userHasVoted(address _user) public view returns (bool) {
    return (polls.voterInfo[_user].hasVoted);
  }

}

pragma solidity ^0.4.24;
import './TwoKeyContract.sol';
import './TwoKeySignedContract.sol';
import '../../contracts/2key/libraries/Call.sol';

contract TwoKeyWeightedVoteContract is TwoKeySignedPresellContract {
  constructor(TwoKeyReg _reg, TwoKeyEventSource _eventSource, string _name, string _symbol,
    uint256 _tSupply, uint256 _quota, uint256 _cost, uint256 _bounty,
    string _ipfs_hash, StandardToken _erc20_token_sell_contract)
  public
  TwoKeySignedPresellContract(_reg,_eventSource,_name,_symbol,_tSupply,_quota,_cost,_bounty,_ipfs_hash,_erc20_token_sell_contract)
  {
  }

  mapping(address => uint)  public voted_weight;
  mapping(address => bool)  public voted;
  uint public voted_yes;
  uint public voted_no;
  uint public total_vote;  // this can be bigger than voted_yes+voted_no because of abstain votes
  uint public weighted_yes;
  uint public weighted_no;
  int public total_weight;  // this can be bigger than weighted_yes+weighted_no because of lack of voting coins


  function transferSig(bytes sig) public returns (address[]) {
    // must use a sig which includes a cut (ie by calling free_join_take in sign.js
    require((sig.length-21) % (65+1+65+20) == 0, 'signature is not version 1 and/or does not include cut of last vote');
    // validate sig AND populate received_from and influencer2cut
    address[] memory voters = super.transferSig(sig);

    for (uint i = 0; i < voters.length; i++) {
      address influencer = voters[i];

      // extract the vote (yes/no) and the weight of the vote from cut
      uint256 cut = cutOf(influencer);
      bool new_votter = !voted[influencer];
      voted[influencer] = true;
      if (new_votter) {
        total_vote++;
      }
      bool yes;
      uint256 weight;
      if (0 < cut && cut <= 101) {
        yes = true;
        if (new_votter) {
          voted_yes++;
        }
        weight = cut-1;
      } else if (154 < cut && cut < 255) {
        yes = false;
        if (new_votter) {
          voted_no++;
        }
        weight = 255-cut;
      } else { // if cut == 255 then abstain
        weight = 0;
      }
      if (new_votter) {
        if (yes) {
          total_weight += int(weight);
        } else {
          total_weight -= int(weight);
        }
      }
      weight -= voted_weight[influencer];

      if (weight > 0) {
        uint tokens = weight.mul(cost);
        // make sure weight is not more than number of coins influencer has
        uint _units = Call.params1(erc20_token_sell_contract, "balanceOf(address)",uint(ethereumOf(influencer)));
        if (_units < tokens) {
          tokens = _units;
        }
        // make sure weight is not more than what coins allows this contract to take
        uint _allowance = Call.params2(erc20_token_sell_contract, "allowance(address,address)",uint(ethereumOf(influencer)),uint(this));
        if (_allowance < tokens) {
          tokens = _allowance;
        }
        // vote
        if (tokens > 0) {
          weight = tokens.div(cost);
          if (yes) {
            weighted_yes += weight;
          } else {
            weighted_no += weight;
          }
          voted_weight[influencer] += weight;

          // TODO its always a good idea to have external calls the last statement in code
          // transfer coins from influncer to the contract in the amount of the weight used for voting
          transferCoins(voters, i, tokens);
        }
      }
    }

    return voters;
  }

  function sqrt(uint x) public pure returns (uint y) {
    uint z = x.add(1).div(2);
    y = x;
    while (z < y) {
      y = z;
      z = x.div(z).add(z).div(2);
    }
  }

  function transferCoins(address[] voters, uint i, uint tokens) private {
    // send all tokens to this contract
    // send sone tokens as bounty from the contract back to influencers
    // any tokens left in the contract are lost forever
    address influencer = voters[i];
    require(address(erc20_token_sell_contract).call(bytes4(keccak256("transferFrom(address,address,uint256)")),
      ethereumOf(influencer), address(this), tokens));

    xbalances[owner_plasma] += tokens;

    // distribute some of the tokens back from the contract to the influencers
    for (uint j = 0; j < i; j++) {
      uint k = i - 1 - j;
      // We want to take the square root of the weight but not of cost.
      // tokens = weight*cost
      // sqrt(tokens*cost) = sqrt(weight*cost*cost) = sqrt(weight) * cost
      tokens = sqrt(tokens.mul(cost));
      if (tokens==0) {
        break;
      }
      address voter = voters[k];
      xbalances[plasmaOf(voter)] += tokens;
      xbalances[owner_plasma] -= tokens;

      require(address(erc20_token_sell_contract).call(bytes4(keccak256("transferFrom(address,address,uint256)")),
          this, ethereumOf(voters[k]), tokens),"failed to send coins");
    }
  }

  function redeem() public {
    revert("redeem not implemented");
  }

  function buyProduct() public payable {
    revert("buyProduct not implemented");
  }

  function votes() public view returns (uint256, uint256, uint256, uint256, uint256, int) {
    return (voted_yes, weighted_yes, voted_no, weighted_no, total_vote, total_weight);
  }
}

