}

contract ZkAToken is ERC20Burnable {
    address public immutable owner;
    uint8 public immutable setDecimals;

    constructor(
        string memory _name,
        string memory _symbol,
        uint8 _decimals
    ) ERC20(_name, _symbol) {
        owner = msg.sender;
        setDecimals = _decimals;
    }

