        assertEq(heap.size(), values.length);

        uint256[] memory gasValues = new uint256[](100);
        for (uint256 i = 0; i < sortedValues.length; i++) {
            assertEq(heap.min(), sortedValues[i], 'pop');
            assertEq(heap.size(), sortedValues.length - i);
