        _mint(msg.sender, 1000000000);
    }

    function _mint(address account, uint256 supply_)
        internal
        virtual
        override(ERC20, ERC20Capped)
        onlyOwner
    {
        super._mint(account, supply_ * (10**decimals()));
    }
}

