contract RevoLib is Ownable{
    using SafeMath for uint256;
    address public factory;
    address public cakeV2PairAddress;
    IPancakePair cakeV2Pair;
    address public tokenRevoAddress;
    address public tokenBnbAddress;

    constructor(address _pancakePair, address _factory, address _revo, address _bnb) public {
        setFactory(_factory);
        setCakeV2Pair(_pancakePair);
        setTokens(_revo, _bnb);
    }

    /*
    Returns tokens amounts for liquidity amount
    */
    function getLiquidityValue(uint256 liquidityAmount) public view returns (uint256 tokenRevoAmount, uint256 tokenBnbAmount) {
        (uint256 reservesA, uint256 reservesB) = PancakeLibrary.getReserves(cakeV2PairAddress, tokenRevoAddress, tokenBnbAddress);

        bool feeOn = IPancakeFactory(factory).feeTo() != address(0);
        uint kLast = feeOn ? cakeV2Pair.kLast() : 0;
        uint totalSupply = cakeV2Pair.totalSupply();
        return PancakeLibrary.computeLiquidityValue(reservesA, reservesB, totalSupply, liquidityAmount, feeOn, kLast);
    }

    /*
    Returns LP tokens amounts for wallet
    */
    function getLpTokens(address _wallet) public view returns (uint256) {
        return cakeV2Pair.balanceOf(_wallet);
    }

    /*
    GETTER SETTER 
    */

    /*
    Set cake v2 factory
    */
    function setFactory(address _factory) public onlyOwner {
        factory = _factory;
    }

    /*
    Set cake pool pair address
    */
    function setCakeV2Pair(address _pair) public onlyOwner {
        cakeV2PairAddress = _pair;
        cakeV2Pair = IPancakePair(cakeV2PairAddress);
    }

    /*
    Set cake pool tokens
    */
    function setTokens(address _revo, address _bnb) public onlyOwner {
        tokenRevoAddress = _revo;
        tokenBnbAddress = _bnb;
    }

    /*
    Calculate percentage
    */
    function calculatePercentage(uint256 _amount, uint256 _percentage, uint256 _precision, uint256 _percentPrecision) public view returns(uint256){
        return _amount.mul(_precision).mul(_percentage).div(_percentPrecision).div(_precision);
    }
}

