    }

    /// @dev Return the current Zrx Vault
    /// @return Zrx Vault
    function getZrxVault()
        public
        view
        returns (address)
    {
        return address(zrxVault);
    }

    /// @dev Deposits Zrx Tokens from the `owner` into the vault.
    /// @param owner of Zrx Tokens
