            hasIndefiniteWhitelisterRoleOrIsAirnode(airnode, msg.sender),
            "Cannot set indefinite status"
        );
        _setIndefiniteWhitelistStatusAndEmit(
            airnode,
            endpointId,
            requester,
            status
        );
