    uint private constant NOTE_TYPE = 1;


    function encodeProofOutputsOne(
        uint noteInfo,
        uint publicOwner,
        uint publicValue
    ) public pure returns (bytes memory) {
        assembly {
            mstore(0x160, 0x20)
            // 0x180 = size of proofOutputs in bytes
            mstore(0x1a0, 0x01) // number of proof outputs
            mstore(0x1c0, 0x60) // relative offset to start of proofOutputs
        }
        uint size = 0x80 + encodeProofOutput(
            0x1e0,
            (noteInfo & 0xff),
            (noteInfo >> 8) & 0xff,
            (noteInfo >> 16) & 0xffff,
            (noteInfo >> 32) & 0xffff,
            (noteInfo >> 48) & 0xffff,
            publicOwner,
            publicValue
        );
        assembly {
            mstore(0x180, sub(size, 0x40))
            return(0x160, size)
        }
    }

    function encodeProofOutput(
        uint freePtr,
        uint numNotes,
        uint numInputNotes,
        uint offsetToNotes,
        uint ownerPtr,
        uint metadataPtr,
        uint publicOwner,
        uint publicValue
