import "../../proxies/smart-wallet/UpgradeBeaconProxyV1.sol";
import "../../../interfaces/DharmaSmartWalletFactoryV1Interface.sol";
import "../../../interfaces/DharmaSmartWalletInitializer.sol";


/**
 * @title DharmaSmartWalletFactoryV1
 * @author 0age
 * @notice This contract deploys new Dharma Smart Wallet instances as "Upgrade
 * Beacon" proxies that reference a shared implementation contract specified by
 * the Dharma Upgrade Beacon contract.
 */
contract DharmaSmartWalletFactoryV1 is DharmaSmartWalletFactoryV1Interface {
  // Use Dharma Smart Wallet initializer to construct initialization calldata.
  DharmaSmartWalletInitializer private _INITIALIZER;

  /**
   * @notice Deploy a new smart wallet address using the provided user signing
   * key.
   * @param userSigningKey address The user signing key, supplied as a
   * constructor argument.
   * @return The address of the new smart wallet.
   */
  function newSmartWallet(
    address userSigningKey
  ) external returns (address wallet) {
    // Get initialization calldata from initialize selector & user signing key.
    bytes memory initializationCalldata = abi.encodeWithSelector(
      _INITIALIZER.initialize.selector,
      userSigningKey
    );

    // Initialize and deploy new user smart wallet as an Upgrade Beacon proxy.
    wallet = _deployUpgradeBeaconProxyInstance(initializationCalldata);

    // Emit an event to signal the creation of the new smart wallet.
    emit SmartWalletDeployed(wallet, userSigningKey);
  }

  /**
   * @notice View function to find the address of the next smart wallet address
   * that will be deployed for a given user signing key. Note that a new value
   * will be returned if a particular user signing key has been used before.
   * @param userSigningKey address The user signing key, supplied as a
   * constructor argument.
   * @return The future address of the next smart wallet.
   */
  function getNextSmartWallet(
    address userSigningKey
  ) external view returns (address wallet) {
    // Get initialization calldata from initialize selector & user signing key.
    bytes memory initializationCalldata = abi.encodeWithSelector(
      _INITIALIZER.initialize.selector,
      userSigningKey
    );

    // Determine the user's smart wallet address based on the user signing key.
    wallet = _computeNextAddress(initializationCalldata);
  }

  /**
   * @notice Private function to deploy an upgrade beacon proxy via `CREATE2`.
   * @param initializationCalldata bytes The calldata that will be supplied to
   * the `DELEGATECALL` from the deployed contract to the implementation set on
   * the upgrade beacon during contract creation.
   * @return The address of the newly-deployed upgrade beacon proxy.
   */
  function _deployUpgradeBeaconProxyInstance(
    bytes memory initializationCalldata
  ) private returns (address upgradeBeaconProxyInstance) {
    // Place creation code and constructor args of new proxy instance in memory.
    bytes memory initCode = abi.encodePacked(
      type(UpgradeBeaconProxyV1).creationCode,
      abi.encode(initializationCalldata)
    );

    // Get salt to use during deployment using the supplied initialization code.
    (uint256 salt, ) = _getSaltAndTarget(initCode);

    // Deploy the new upgrade beacon proxy contract using `CREATE2`.
    assembly {
      let encoded_data := add(0x20, initCode) // load initialization code.
      let encoded_size := mload(initCode)     // load the init code's length.
      upgradeBeaconProxyInstance := create2(  // call `CREATE2` w/ 4 arguments.
        callvalue,                            // forward any supplied endowment.
        encoded_data,                         // pass in initialization code.
        encoded_size,                         // pass in init code's length.
        salt                                  // pass in the salt value.
      )

      // Pass along failure message and revert if contract deployment fails.
      if iszero(upgradeBeaconProxyInstance) {
        returndatacopy(0, 0, returndatasize)
        revert(0, returndatasize)
      }
    }
  }

  /**
   * @notice Private view function for finding the address of the next upgrade
   * beacon proxy that will be deployed, given a particular initialization
   * calldata payload.
   * @param initializationCalldata bytes The calldata that will be supplied to
   * the `DELEGATECALL` from the deployed contract to the implementation set on
   * the upgrade beacon during contract creation.
   * @return The address of the next upgrade beacon proxy contract with the
   * given initialization calldata.
   */
  function _computeNextAddress(
    bytes memory initializationCalldata
  ) private view returns (address target) {
    // Place creation code and constructor args of the proxy instance in memory.
    bytes memory initCode = abi.encodePacked(
      type(UpgradeBeaconProxyV1).creationCode,
      abi.encode(initializationCalldata)
    );

    // Get target address using the constructed initialization code.
    (, target) = _getSaltAndTarget(initCode);
  }

  /**
   * @notice Private function for determining the salt and the target deployment
   * address for the next deployed contract (using `CREATE2`) based on the
   * contract creation code.
   */
  //  SWC-128-DoS With Block Gas Limit: L130 - L170
  function _getSaltAndTarget(
    bytes memory initCode
  ) private view returns (uint256 nonce, address target) {
    // Get the keccak256 hash of the init code for address derivation.
    bytes32 initCodeHash = keccak256(initCode);

    // Set the initial nonce to be provided when constructing the salt.
    nonce = 0;

    // Declare variable for code size of derived address.
    uint256 codeSize;

    // Loop until an contract deployment address with no code has been found.
    while (true) {
      target = address(            // derive the target deployment address.
        uint160(                   // downcast to match the address type.
          uint256(                 // cast to uint to truncate upper digits.
            keccak256(             // compute CREATE2 hash using 4 inputs.
              abi.encodePacked(    // pack all inputs to the hash together.
                bytes1(0xff),      // pass in the control character.
                address(this),     // pass in the address of this contract.
                nonce,              // pass in the salt from above.
                initCodeHash       // pass in hash of contract creation code.
              )
            )
          )
        )
      );

      // Determine if a contract is already deployed to the target address.
      assembly { codeSize := extcodesize(target) }

      // Exit the loop if no contract is deployed to the target address.
      if (codeSize == 0) {
        break;
      }

      // Otherwise, increment the nonce and derive a new salt.
      nonce++;
    }
  }
}

pragma solidity 0.5.11;


/**
 * @title CodeHashCache
 * @author 0age
 * @notice This contract allows callers to register the runtime code hash of any
 * contract that is currently deployed with runtime code. It then allows callers
 * to determine whether or not the runtime code hash of any registered contract
 * has been altered since it was initially registered. A critical consideration
 * to bear in mind is that registered contracts can still be destroyed and later
 * redeployed with the same runtime code - their runtime code hash will be the
 * same, but their creation code may differ, and their contract storage will be
 * completely wiped upon destruction.
 */
contract CodeHashCache {
  // Maintain a mapping of runtime code hashes of deployed contracts.
  mapping (address => bytes32) private _cachedHashes;

  /**
   * @notice Register a target contract's current runtime code hash. This call
   * will revert if the supplied target contract has already been registered or
   * does not currently have any runtime code.
   * @param target address The contract to retrieve and store the runtime code
   * hash for.
   */
  function registerCodeHash(address target) external {
    // Ensure that the target contract has not already had a hash registered.
    require(_cachedHashes[target] == bytes32(0), "Target already registered.");    

    // Ensure that the target contract currently has runtime code.
    uint256 currentCodeSize;
    assembly { currentCodeSize := extcodesize(target) }
    require(currentCodeSize > 0, "Target currently has no runtime code.");

    // Retrieve the current runtime code hash of the target contract.
    bytes32 currentCodeHash;
    assembly { currentCodeHash := extcodehash(target) }

    // Register the runtime code hash for the target contract.
    _cachedHashes[target] = currentCodeHash;
  }

  /**
   * @notice View function to determine if the current runtime code hash of a
   * target contract matches the registered runtime code hash for the target
   * contract. Reverts if no runtime code hash has been registered yet for the
   * target contract.
   * @param target address The contract to retrieve the runtime code hash for,
   * which will be compared against the runtime code hash that was initially
   * registered for that contract.
   * @return A boolean signifying that the target contract's runtime code has
   * not been altered since it was initially registered.
   */
  function matchesRegisteredCodeHash(
    address target
  ) external view returns (bool codeHashMatchesRegisteredCodeHash) {
    // Get the runtime code hash that is currently registered for the target.
    bytes32 cachedCodeHash = _cachedHashes[target];

    // Ensure that the target contract has already had a code hash registered.
    require(cachedCodeHash != bytes32(0), "Target not yet registered.");

    // Retrieve the current runtime code hash of the target contract.
    bytes32 currentCodeHash;
    assembly { currentCodeHash := extcodehash(target) }

    // Compare current runtime code hash to registered runtime code hash.
    codeHashMatchesRegisteredCodeHash = currentCodeHash == cachedCodeHash;
  }

  /**
   * @notice View function to retrieve the runtime code hash registered for the
   * target contract. Returns bytes32(0) if there is no runtime code hash
   * registered for the target.
   * @param target address The contract to retrieve the registered runtime code
   * hash for.
   * @return The runtime code hash registered for the target contract. Returns
   * bytes32(0) if there runtime code hash has been registered for the target.
   */
  function getRegisteredCodeHash(
    address target
  ) external view returns (bytes32 registeredCodeHash) {
    // Get the runtime code hash that is currently registered for the target.
    registeredCodeHash = _cachedHashes[target];
  }
}

