import "@openzeppelin/contracts/cryptography/ECDSA.sol";
import "../../interfaces/DharmaKeyRegistryInterface.sol";
import "../../interfaces/ERC1271.sol";


/**
 * @title DharmaKeyRegistryV1Mimic
 * @author 0age
 * @notice This contract will require that the provided signature resolves to
 * the key set for a smart wallet on the Dharma Key Registry when it is set as
 * the address of a user's signing key.
 */
contract DharmaKeyRegistryV1Mimic is ERC1271 {
  using ECDSA for bytes32;

  // The Dharma Key Registry holds a public key for verifying meta-transactions.
  DharmaKeyRegistryInterface internal constant _DHARMA_KEY_REGISTRY = (
    DharmaKeyRegistryInterface(0x000000005D7065eB9716a410070Ee62d51092C98)
  );

  // ERC-1271 must return this magic value when `isValidSignature` is called.
  bytes4 internal constant _ERC_1271_MAGIC_VALUE = bytes4(0x20c13b0b);

  function isValidSignature(
    bytes calldata data, bytes calldata signature
  ) external view returns (bytes4 magicValue) {
    (bytes32 hash, , ) = abi.decode(data, (bytes32, uint8, bytes));

    require(
      hash.recover(signature) == _DHARMA_KEY_REGISTRY.getKeyForUser(msg.sender),
      "Supplied signature does not resolve to the required signer."
    );

    magicValue = _ERC_1271_MAGIC_VALUE;
  }
}

pragma solidity 0.5.11;


library ECDSAGroup {
  /**
   * @dev Returns each address that signed a hashed message (`hash`) from a
   * collection of `signatures`.
   *
   * The `ecrecover` EVM opcode allows for malleable (non-unique) signatures:
   * this function rejects them by requiring the `s` value to be in the lower
   * half order, and the `v` value to be either 27 or 28.
   *
   * NOTE: This call _does not revert_ if a signature is invalid, or if the
   * signer is otherwise unable to be retrieved. In those scenarios, the zero
   * address is returned for that signature.
   *
   * IMPORTANT: `hash` _must_ be the result of a hash operation for the
   * verification to be secure: it is possible to craft signatures that recover
   * to arbitrary addresses for non-hashed data.
   */
  function recoverGroup(
    bytes32 hash,
    bytes memory signatures
  ) internal pure returns (uint160[] memory signers) {
    // Ensure that the signatures length is a multiple of 65.
    if (signatures.length % 65 != 0) {
      return new uint160[](0);
    }

    // Create an appropriately-sized array of addresses for each signer.
    signers = new uint160[](signatures.length / 65);

    // Get each signature location and divide into r, s and v variables.
    bytes32 signatureLocation;
    bytes32 r;
    bytes32 s;
    uint8 v;

    for (uint256 i = 0; i < signers.length; i++) {
      assembly {
        signatureLocation := add(signatures, mul(i, 65))
        r := mload(add(signatureLocation, 0x20))
        s := mload(add(signatureLocation, 0x40))
        v := byte(0, mload(add(signatureLocation, 0x60)))
      }

      // EIP-2 still allows signature malleability for ecrecover(). Remove
      // this possibility and make the signature unique. 
      if (uint256(s) > 0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0) {
        continue;
      }

      if (v != 27 && v != 28) {
        continue;
      }

      // If signature is valid & not malleable, add signer address as uint160.
      signers[i] = uint160(ecrecover(hash, v, r, s));
    }
  }
}

pragma solidity 0.5.11;


/**
 * @title Immutable Create2 Contract Factory
 * @author 0age
 * @notice This contract provides a safeCreate2 function that takes a salt value
 * and a block of initialization code as arguments and passes them into inline
 * assembly. The contract prevents redeploys by maintaining a mapping of all
 * contracts that have already been deployed, and prevents frontrunning or other
 * collisions by requiring that the first 20 bytes of the salt are equal to the
 * address of the caller (this can be bypassed by setting the first 20 bytes to
 * the null address). There is also a view function that computes the address of
 * the contract that will be created when submitting a given salt or nonce along
 * with a given block of initialization code.
 * @dev This contract has not yet been fully tested or audited - proceed with
 * caution and please share any exploits or optimizations you discover.
 */
contract ImmutableCreate2Factory {
  // mapping to track which addresses have already been deployed.
  mapping(address => bool) private _deployed;

  /**
   * @dev Create a contract using CREATE2 by submitting a given salt or nonce
   * along with the initialization code for the contract. Note that the first 20
   * bytes of the salt must match those of the calling address, which prevents
   * contract creation events from being submitted by unintended parties.
   * @param salt bytes32 The nonce that will be passed into the CREATE2 call.
   * @param initializationCode bytes The initialization code that will be passed
   * into the CREATE2 call.
   * @return Address of the contract that will be created, or the null address
   * if a contract already exists at that address.
   */
  function safeCreate2(
    bytes32 salt,
    bytes calldata initializationCode
  ) external payable containsCaller(salt) returns (address deploymentAddress) {
    // move the initialization code from calldata to memory.
    bytes memory initCode = initializationCode;

    // determine the target address for contract deployment.
    address targetDeploymentAddress = address(
      uint160(                    // downcast to match the address type.
        uint256(                  // convert to uint to truncate upper digits.
          keccak256(              // compute the CREATE2 hash using 4 inputs.
            abi.encodePacked(     // pack all inputs to the hash together.
              hex"ff",            // start with 0xff to distinguish from RLP.
              address(this),      // this contract will be the caller.
              salt,               // pass in the supplied salt value.
              keccak256(          // pass in the hash of initialization code.
                abi.encodePacked(
                  initCode
                )
              )
            )
          )
        )
      )
    );

    // ensure that a contract hasn't been previously deployed to target address.
    require(
      !_deployed[targetDeploymentAddress],
      "Invalid contract creation - contract has already been deployed."
    );

    // using inline assembly: load data and length of data, then call CREATE2.
    assembly {                                // solhint-disable-line
      let encoded_data := add(0x20, initCode) // load initialization code.
      let encoded_size := mload(initCode)     // load the init code's length.
      deploymentAddress := create2(           // call CREATE2 with 4 arguments.
        callvalue,                            // forward any attached value.
        encoded_data,                         // pass in initialization code.
        encoded_size,                         // pass in init code's length.
        salt                                  // pass in the salt value.
      )
    }

    // check address against target to ensure that deployment was successful.
    require(
      deploymentAddress == targetDeploymentAddress,
      "Failed to deploy contract using provided salt and initialization code."
    );

    // record the deployment of the contract to prevent redeploys.
    _deployed[deploymentAddress] = true;
  }

  /**
   * @dev Compute the address of the contract that will be created when
   * submitting a given salt or nonce to the contract along with the contract's
   * initialization code. The CREATE2 address is computed in accordance with
   * EIP-1014, and adheres to the formula therein of
   * `keccak256( 0xff ++ address ++ salt ++ keccak256(init_code)))[12:]` when
   * performing the computation. The computed address is then checked for any
   * existing contract code - if so, the null address will be returned instead.
   * @param salt bytes32 The nonce passed into the CREATE2 address calculation.
   * @param initCode bytes The contract initialization code to be used.
   * that will be passed into the CREATE2 address calculation.
   * @return Address of the contract that will be created, or the null address
   * if a contract has already been deployed to that address.
   */
  function findCreate2Address(
    bytes32 salt,
    bytes calldata initCode
  ) external view returns (address deploymentAddress) {
    // determine the address where the contract will be deployed.
    deploymentAddress = address(
      uint160(                      // downcast to match the address type.
        uint256(                    // convert to uint to truncate upper digits.
          keccak256(                // compute the CREATE2 hash using 4 inputs.
            abi.encodePacked(       // pack all inputs to the hash together.
              hex"ff",              // start with 0xff to distinguish from RLP.
              address(this),        // this contract will be the caller.
              salt,                 // pass in the supplied salt value.
              keccak256(            // pass in the hash of initialization code.
                abi.encodePacked(
                  initCode
                )
              )
            )
          )
        )
      )
    );

    // return null address to signify failure if contract has been deployed.
    if (_deployed[deploymentAddress]) {
      return address(0);
    }
  }

  /**
   * @dev Compute the address of the contract that will be created when
   * submitting a given salt or nonce to the contract along with the keccak256
   * hash of the contract's initialization code. The CREATE2 address is computed
   * in accordance with EIP-1014, and adheres to the formula therein of
   * `keccak256( 0xff ++ address ++ salt ++ keccak256(init_code)))[12:]` when
   * performing the computation. The computed address is then checked for any
   * existing contract code - if so, the null address will be returned instead.
   * @param salt bytes32 The nonce passed into the CREATE2 address calculation.
   * @param initCodeHash bytes32 The keccak256 hash of the initialization code
   * that will be passed into the CREATE2 address calculation.
   * @return Address of the contract that will be created, or the null address
   * if a contract has already been deployed to that address.
   */
  function findCreate2AddressViaHash(
    bytes32 salt,
    bytes32 initCodeHash
  ) external view returns (address deploymentAddress) {
    // determine the address where the contract will be deployed.
    deploymentAddress = address(
      uint160(                      // downcast to match the address type.
        uint256(                    // convert to uint to truncate upper digits.
          keccak256(                // compute the CREATE2 hash using 4 inputs.
            abi.encodePacked(       // pack all inputs to the hash together.
              hex"ff",              // start with 0xff to distinguish from RLP.
              address(this),        // this contract will be the caller.
              salt,                 // pass in the supplied salt value.
              initCodeHash          // pass in the hash of initialization code.
            )
          )
        )
      )
    );

    // return null address to signify failure if contract has been deployed.
    if (_deployed[deploymentAddress]) {
      return address(0);
    }
  }

  /**
   * @dev Determine if a contract has already been deployed by the factory to a
   * given address.
   * @param deploymentAddress address The contract address to check.
   * @return True if the contract has been deployed, false otherwise.
   */
  function hasBeenDeployed(
    address deploymentAddress
  ) external view returns (bool) {
    // determine if a contract has been deployed to the provided address.
    return _deployed[deploymentAddress];
  }

  /**
   * @dev Modifier to ensure that the first 20 bytes of a submitted salt match
   * those of the calling account. This provides protection against the salt
   * being stolen by frontrunners or other attackers. The protection can also be
   * bypassed if desired by setting each of the first 20 bytes to zero.
   * @param salt bytes32 The salt value to check against the calling address.
   */
  modifier containsCaller(bytes32 salt) {
    // prevent contract submissions from being stolen from tx.pool by requiring
    // that the first 20 bytes of the submitted salt match msg.sender.
    require(
      (address(bytes20(salt)) == msg.sender) ||
      (bytes20(salt) == bytes20(0)),
      "Invalid salt - first 20 bytes of the salt must match calling address."
    );
    _;
  }
}

pragma solidity 0.5.11;


/**
 * @title IndestructibleRegistry
 * @author 0age + flex
 * @notice This contract determines if other contracts are incapable of being
 * destroyed by confirming that they do not contain any SELFDESTRUCT, CALLCODE,
 * or DELEGATECALL opcodes. Just because a contract is determined to potentially
 * be destructible does not necessarily mean that it IS destructible - in other
 * words, the check performed by this contract is contract is quite strict.
 * To register a contract as indestructible in the registry, provide the target
 * contract address to the `registerAsIndestructible` function - it will throw
 * if the contract is potentially destructible. Then, anyone can call the
 * `isRegisteredAsIndestructible` view function to confirm that the contract has
 * been successfully registered as an indestructible contract. You can also call
 * the `isPotentiallyDestructible` view function to perform the destructibility
 * check without actually registering the contract. Note that this registry will
 * likely still apply through the Istanbul hardfork, but future forks may
 * introduce new opcodes or other methods by which contracts can be destroyed;
 * in that case, this registry can no longer be relied on as a safeguard against
 * destructibility.
 */
contract IndestructibleRegistry {
  // Maintain mapping of contracts that have been registered as indestructible.
  mapping (address => bool) private _definitelyIndestructible;

  /**
   * @notice Register a target contract as indestructible. The attempt will
   * revert if no code exists at the supplied target or if the target contract
   * is potentially destructible (i.e. the code has reachable opcodes that could
   * result in the contract being destroyed).
   * @param target address The contract to check and register as indestructible.
   */
  function registerAsIndestructible(address target) external {
    // Ensure that the target contract is not potentially destructible.
    require(
      !_isPotentiallyDestructible(target),
      "Supplied target is potentially destructible."
    );

    // Register the target as definitely indestructible (barring new opcodes).
    _definitelyIndestructible[target] = true;
  }

  /**
   * @notice View function to determine if a target contract has been registered
   * as indestructible.
   * @param target address The contract to check for potential registration as
   * an indestructible contract.
   * @return A boolean signifying successful registration as an indestructable
   * contract.
   */
  function isRegisteredAsIndestructible(
    address target
  ) external view returns (bool registeredAsIndestructible) {
    registeredAsIndestructible = _definitelyIndestructible[target];
  }

  /**
   * @notice View function to perform a scan of a target contract and determine
   * whether it is potentially destructible or not. The call will revert if no
   * code exists at the supplied target.
   * @param target address The contract to check for potential destructibility.
   * @return A boolean signifying whether or not the target contract is
   * potentially destructible.
   */
  function isPotentiallyDestructible(
    address target
  ) external view returns (bool potentiallyDestructible) {
    potentiallyDestructible = _isPotentiallyDestructible(target);
  }

  /**
   * @notice Internal function that performs a scan of a target contract and
   * determines whether it is potentially destructible or not. It first
   * retrieves the runtime code size of the target contract and ensures that it
   * is greater than zero. Then, it retrieves the actual runtime code from the
   * target contract and places it into memory. Next, it iterates over the code,
   * skipping over unreachable code and push data, and ensures no SELFDESTRUCT,
   * DELEGATECALL, or CALLCODE opcodes are present in the code.
   * @param target address The contract to check for potential destructibility.
   * @return A boolean signifying whether or not the target contract is
   * potentially destructible.
   */
  function _isPotentiallyDestructible(
    address target
  ) internal view returns (bool potentiallyDestructible) {
    // Get the size of the target.
    uint256 size;
    assembly { size := extcodesize(target) }
    require(size > 0, "No code at target.");

    // Get code at the target and the location data starts and ends in memory.
    uint256 dataStart;
    bytes memory extcode = new bytes(size);
    assembly {
      dataStart := add(extcode, 0x20)
      extcodecopy(target, dataStart, 0, size)
    }
    uint256 dataEnd = dataStart + size;
    require (dataEnd > dataStart, "SafeMath: addition overflow.");

    // Look for any reachable, impermissible opcodes.
    bool reachable = true;
    uint256 op;
    for (uint256 i = dataStart; i < dataEnd; i++) {
      // Get the opcode in question.
      assembly { op := shr(0xf8, mload(i)) }

      // Check the opcode if it is reachable (i.e. not a constant or metadata).
      if (reachable) {
        // If execution is halted, mark opcodes that follow as unreachable.
        if (
          op == 254 || // invalid
          op == 243 || // return
          op == 253 || // revert
          op == 86  || // jump
          op == 0      // stop
        ) {
          reachable = false;
          continue;
        }

        // If the opcode is a PUSH, skip over the push data.
        if (op > 95 && op < 128) { // pushN
          i += (op - 95);
          continue;
        }

        // If opcode is impermissible, return true - potential destructibility!
        if (
          op == 242 || // callcode
          op == 244 || // delegatecall
          op == 255    // selfdestruct
        ) {
          return true; // potentially destructible!
        }
      } else if (op == 91) { // jumpdest
        // Whenever a JUMPDEST is found, mark opcodes that follow as reachable. 
        reachable = true;
      }
    }
  }
}

pragma solidity 0.5.11;
pragma experimental ABIEncoderV2;

import "@openzeppelin/contracts/ownership/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "../../interfaces/DharmaSmartWalletFactoryV1Interface.sol";
import "../../interfaces/RelayContractInterface.sol";


/**
 * @title RelayMigrator
 * @author 0age
 * @notice This contract will migrate cDAI and cUSDC balances from existing user
 * relay contracts to new smart wallet contracts. It has four distinct phases:
 *  - Phase one: Registration. All existing relay contracts, and a user signing
 *    key that will be used to provision a new smart wallet for each, are
 *    provided as arguments to the `register` function. Once all relay contracts
 *    have been registered, the `endRegistration` function is called and the
 *    final group of registered relay contracts is verified by calling
 *    `getTotalRegisteredRelayContracts` and `getRegisteredRelayContract`.
 *  - Phase two: Deployment. This contract will call the Dharma Smart Wallet
 *    factory, supplying the registered user signing key. The resultant smart
 *    wallet address will be recorded for each relay contract. Once a smart
 *    wallet has been deployed for each relay contract, the deployment phase
 *    will be marked as ended, and the final group of deployed smart wallets
 *    should be verified by calling `getTotalDeployedSmartWallets` and 
 *    `getRegisteredRelayContract`, making sure that each relay contract has a
 *    corresponding smart wallet, and updating that information for each user.
 *  - Phase three: Approval Assignment. Each relay contract will need to call
 *    `executeTransactions` and assign this contract full allowance to transfer
 *    both cDAI and cUSDC ERC20 tokens on it's behalf. This can be done safely,
 *    as there is only one valid recipient for each `transferFrom` sent from the
 *    relay contract: the associated smart wallet. Once this phase is complete,
 *    approvals should be verified by calling `getRegisteredRelayContract` for
 *    each relay contract, making sure that `readyToMigrate` is true for each.
 *    Then, call the `beginMigration` function to start the actual migration.
 *  - Phase four: Migration. The migrator will iterate over each relay contract,
 *    detect the current cDAI and cUSDC token balance on the relay contract, and
 *    transfer it from the relay contract to the smart wallet. If a transfer
 *    does not succeed (for instance, if approvals were not appropriately set),
 *    an event indicating the problematic relay contract will be emitted. Once
 *    all relay contract transfers have been processed, the migrator will begin
 *    again from the start - this enables any missed approvals to be addressed
 *    and any balance changes between the start and the end of the migration to
 *    be brought over as well. Once all users have been successfully migrated
 *    `endMigration` may be called to completely decommission the migrator.
 *
 * After migration is complete, it is imperative that users set a user-supplied
 * signing key by calling `setUserSigningKey` on their smart wallet. Until then,
 * the initial user signature will be supplied by Dharma to perform smart wallet
 * actions (including for the initial request to set the user's signing key).
 */
contract RelayMigrator is Ownable {
  event MigrationError(
    address cToken,
    address relayContract,
    address smartWallet,
    uint256 balance,
    uint256 allowance
  );

  struct RelayCall {
    address relayContract;
    RelayContractInterface.transactionParameters[] executeTransactionsArgument;
  }

  address[] private _relayContracts;

  address[] private _initialUserSigningKeys;

  address[] private _smartWallets;

  mapping(address => bool) private _relayContractRegistered;

  mapping(address => bool) private _initialUserSigningKeyRegistered;

  uint256 private _iterationIndex;

  bool public registrationCompleted;

  bool public deploymentCompleted;

  bool public migrationStarted;

  bool public migrationFirstPassCompleted;

  bool public migrationCompleted;

  // The Dharma Smart Wallet Factory will deploy each new smart wallet.
  DharmaSmartWalletFactoryV1Interface internal constant _DHARMA_SMART_WALLET_FACTORY = (
    DharmaSmartWalletFactoryV1Interface(0xfc00C80b0000007F73004edB00094caD80626d8D)
  );

  // This contract interfaces with cDai and cUSDC CompoundV2 contracts.
  IERC20 internal constant _CDAI = IERC20(
    0xF5DCe57282A584D2746FaF1593d3121Fcac444dC // mainnet
  );

  IERC20 internal constant _CUSDC = IERC20(
    0x39AA39c021dfbaE8faC545936693aC917d5E7563 // mainnet
  );

  bytes32 internal constant _RELAY_CODE_HASH_ONE = bytes32(
    0x2a85d02ccfbef70d3ca840c2a0e46ed31085a34079a601e5ded05f97fae15089
  );

  bytes32 internal constant _RELAY_CODE_HASH_TWO = bytes32(
    0xc1f8a51c720d3d6a8361c8fe6cf7948e0012882ad31966c6be4cac186ed4ddb9
  );

  bytes32 internal constant _RELAY_CODE_HASH_THREE = bytes32(
    0x7995a9071b13688c3ef87630b91b83b0e6983c587999f586dabad1bca6d4f01b
  );

  /**
   * @notice In constructor, set the transaction submitter as the owner, set all
   * initial phase flags to false, and set the initial migration index to 0.
   */
  constructor() public {
    _transferOwnership(tx.origin);

    registrationCompleted = false;
    deploymentCompleted = false;
    migrationStarted = false;
    migrationFirstPassCompleted = false;
    migrationCompleted = false;

    _iterationIndex = 0;
  }

  /**
   * @notice Register a group of relay contracts. This function will revert if a
   * supplied relay contract or user signing key has already been registered.
   * Only the owner may call this function.
   * @param relayContracts address[] An array of relay contract addresses to
   * register.
   * @param initialUserSigningKeys address[] An array of addresses to register
   * for each relay contract that will be used to set the initial user signing
   * key when creating the new smart wallet for the user.
   */
  function register(
    address[] calldata relayContracts,
    address[] calldata initialUserSigningKeys
  ) external onlyOwner {
    require(
      !registrationCompleted,
      "Cannot register new relay contracts once registration is completed."
    );

    require(
      relayContracts.length == initialUserSigningKeys.length,
      "Length of relay contracts array and user signing keys array must match."
    );

    bytes32 codeHash;
    for (uint256 i; i < relayContracts.length; i++) {
      address relayContract = relayContracts[i];
      address initialUserSigningKey = initialUserSigningKeys[i];

      require(
        initialUserSigningKey != address(0),
        "Must supply an initial user signing key."
      );

      require(
        !_initialUserSigningKeyRegistered[initialUserSigningKey],
        "Initial user signing key already registered."
      );

      assembly { codeHash := extcodehash(relayContract) }

      require(
        codeHash == _RELAY_CODE_HASH_ONE ||
        codeHash == _RELAY_CODE_HASH_TWO ||
        codeHash == _RELAY_CODE_HASH_THREE,
        "Must supply a valid relay contract address."
      );

      require(
        !_relayContractRegistered[relayContract],
        "Relay contract already registered."
      );

      _relayContractRegistered[relayContract] = true;
      _initialUserSigningKeyRegistered[initialUserSigningKey] = true;
      _relayContracts.push(relayContract);
      _initialUserSigningKeys.push(initialUserSigningKey);
    }
  }

  /**
   * @notice End relay contract registration. Only the owner may call this
   * function.
   */
  function endRegistration() external onlyOwner {
    require(!registrationCompleted, "Registration is already completed.");

    registrationCompleted = true;
  }

  /**
   * @notice Deploy smart wallets for each relay, using the initial user signing
   * key registered to each relay contract as an initialization argument. Anyone
   * may call this method once registration is completed until deployments are
   * completed.
   */
  function deploySmartWallets() external {
    require(
      registrationCompleted,
      "Cannot begin smart wallet deployment until registration is completed."
    );

    require(
      !deploymentCompleted,
      "Cannot deploy new smart wallets after deployment is completed."
    );

    address newSmartWallet;

    uint256 totalInitialUserSigningKeys = _initialUserSigningKeys.length;

    for (uint256 i = _iterationIndex; i < totalInitialUserSigningKeys; i++) {
      if (gasleft() < 200000) {
        _iterationIndex = i;
        return;
      }

      newSmartWallet = _DHARMA_SMART_WALLET_FACTORY.newSmartWallet(
        _initialUserSigningKeys[i]
      );

      _smartWallets.push(newSmartWallet);
    }

    deploymentCompleted = true;
    _iterationIndex = 0;
  }

  /**
   * @notice Begin relay contract migration. Only the owner may call this
   * function, and smart wallet deployment must first be completed.
   */
  function startMigration() external onlyOwner {
    require(
      deploymentCompleted,
      "Cannot start migration until new smart wallet deployment is completed."
    );

    require(!migrationStarted, "Migration has already started.");

    migrationStarted = true;
  }

  /**
   * @notice Migrate cDAI and cUSDC token balances from each relay contract to
   * the corresponding smart wallet. Anyone may call this method once migration
   * has started until deployments are completed.
   */
  function migrateRelayContractsToSmartWallets() external {
    require(
      migrationStarted,
      "Cannot begin relay contract migration until migration has started."
    );

    require(!migrationCompleted, "Migration is fully completed.");

    uint256 totalRelayContracts = _relayContracts.length;

    address relayContract;
    address smartWallet;
    uint256 balance;
    uint256 allowance;
    bool ok;

    for (uint256 i = _iterationIndex; i < totalRelayContracts; i++) {
      if (gasleft() < 200000) {
        _iterationIndex = i;
        return;
      }

      relayContract = _relayContracts[i];
      smartWallet = _smartWallets[i];

      balance = _CDAI.balanceOf(relayContract);

      if (balance > 0) {
        (ok, ) = address(_CDAI).call(abi.encodeWithSelector(
          _CDAI.transferFrom.selector, relayContract, smartWallet, balance
        ));

        // Emit a corresponding event if the transfer failed.
        if (!ok) {
          allowance = _CDAI.allowance(relayContract, address(this));
          emit MigrationError(
            address(_CDAI), relayContract, smartWallet, balance, allowance
          );
        }
      }

      balance = _CUSDC.balanceOf(relayContract);

      if (balance > 0) {
        (ok, ) = address(_CUSDC).call(abi.encodeWithSelector(
          _CUSDC.transferFrom.selector, relayContract, smartWallet, balance
        ));

        // Emit a corresponding event if the transfer failed.
        if (!ok) {
          allowance = _CUSDC.allowance(relayContract, address(this));
          emit MigrationError(
            address(_CUSDC), relayContract, smartWallet, balance, allowance
          );
        }
      }
    }

    migrationFirstPassCompleted = true;
    _iterationIndex = 0;
  }

  /**
   * @notice End the migration and decommission the migrator. Only the owner may
   * call this function, and a full first pass must first be completed.
   */
  function endMigration() external onlyOwner {
    require(
      migrationFirstPassCompleted,
      "Cannot end migration until at least one full pass is completed."
    );

    require(!migrationCompleted, "Migration has already completed.");

    migrationCompleted = true;
  }

  function getTotalRegisteredRelayContracts() external view returns (uint256) {
    return _relayContracts.length;
  }

  function getTotalDeployedSmartWallets() external view returns (uint256) {
    return _smartWallets.length;
  }

  function getRegisteredRelayContract(
    uint256 index
  ) external view returns (
    address relayContract,
    address initialUserSigningKey,
    address smartWallet,
    bool readyToMigrate
  ) {
    relayContract = _relayContracts[index];
    initialUserSigningKey = _initialUserSigningKeys[index];
    smartWallet = _smartWallets[index];
    readyToMigrate = _isReadyToMigrate(relayContract);
  }

  /**
   * @notice Set approvals to transfer cDAI and cUSDC on a group of relay
   * contracts in batches. Anyone may call this function as long as valid relay
   * contracts, transaction parameters, and signatures are provided - the call
   * will revert if any portion of the call reverts.
   * @param relayCalls RelayCall[] An array of RelayCall structs, which contain
   * relay contract addresses to call and an array of transactionParameters
   * structs are provided as an argument when calling `executeTransactions` on
   * the relay contract.
   */
  function batchExecuteTransactions(RelayCall[] memory relayCalls) public {
    for (uint256 i = 0; i < relayCalls.length; i++) {
      RelayCall memory relayCall = relayCalls[i];
      RelayContractInterface.transactionParameters[] memory txs = (
        relayCall.executeTransactionsArgument
      );
      RelayContractInterface(relayCall.relayContract).executeTransactions(txs);
    }
  }

  /**
   * @notice Internal function to check whether appropriate allowances have been
   * set on a given relay contract so that this contract can transfer cTokens on
   * its behalf. Note that an increase in a cToken balance between this function
   * being called and the migration may cause a given migration to fail.
   * @param relayContract address A relay contract address to check for cDAI and
   * cUSDC allowances.
   */
  function _isReadyToMigrate(
    address relayContract
  ) internal view returns (bool ready) {
    ready = (
      _CDAI.allowance(relayContract, address(this)) >= _CDAI.balanceOf(relayContract) &&
      _CUSDC.allowance(relayContract, address(this)) >= _CUSDC.balanceOf(relayContract)
    );
  }
}

pragma solidity 0.5.11;

import "@openzeppelin/contracts/math/SafeMath.sol";


/**
 * @title Timelocker
 * @author 0age
 * @notice This contract allows contracts that inherit it to implement timelocks
 * on functions, where the `setTimelock` function must first be called, with the
 * same arguments that the function will be supplied with. Then, a given time
 * interval must first fully transpire before the timelock functions can be
 * successfully called. It also includes a `modifyTimelockInterval` function
 * that is itself able to be timelocked, and that is given a function selector
 * and a new timelock interval for the function as arguments. To make a function
 * timelocked, use the `_enforceTimelock` internal function. To set initial
 * minimum timelock intervals, use the `_setInitialTimelockInterval` internal
 * function - it can only be used from within a constructor. Finally, there are
 * two public getters: `getTimelock` and `getTimelockInterval`.
 */
contract Timelocker {
  using SafeMath for uint256;

  // Fire an event any time a timelock is initiated.
  event TimelockInitiated(
    bytes4 functionSelector, // selector of the function 
    uint256 timeComplete,    // timestamp at which the function can be called
    bytes arguments          // abi-encoded function arguments to call with
  );

  // Fire an event any time a minimum timelock interval is modified.
  event TimelockIntervalModified(
    bytes4 functionSelector, // selector of the function 
    uint256 oldInterval,     // new minimum timelock interval for the function
    uint256 newInterval      // new minimum timelock interval for the function
  );

  // Implement a timelock for each function and set of arguments.
  mapping(bytes4 => mapping(bytes32 => uint256)) private _timelocks;

  // Implement a timelock interval for each timelocked function.
  mapping(bytes4 => uint256) private _timelockIntervals;

  /**
   * @notice Public function for setting a new timelock interval for a given 
   * function selector. The default for this function may also be modified, but
   * excessive values will cause the `modifyTimelockInterval` function to become
   * unusable.
   * @param functionSelector the selector of the function to set the timelock
   * interval for.
   * @param newTimelockInterval the new minimum timelock interval to set for the
   * given function.
   */
  function modifyTimelockInterval(
    bytes4 functionSelector,
    uint256 newTimelockInterval
  ) public {
    // Ensure that the timelock has been set and is completed.
    _enforceTimelock(
      this.modifyTimelockInterval.selector, abi.encode(newTimelockInterval)
    );

    // Set new timelock interval and emit a `TimelockIntervalModified` event.
    _setTimelockInterval(functionSelector, newTimelockInterval);
  }

  /**
   * @notice View function to check if a timelock for the specified function and
   * arguments has completed.
   * @param functionSelector function to be called.
   * @param arguments The abi-encoded arguments of the function to be called.
   * @return A boolean indicating if the timelock exists or not and the time at
   * which the timelock completes if it does exist.
   */
  function getTimelock(
    bytes4 functionSelector,
    bytes memory arguments
  ) public view returns (bool exists, uint256 completionTime) {
    // Get timelock ID using the supplied function arguments.
    bytes32 timelockID = keccak256(abi.encodePacked(arguments));

    // Get the current timelock, if any.
    completionTime = _timelocks[functionSelector][timelockID];
    exists = completionTime != 0;
  }

  /**
   * @notice View function to check the current minimum timelock interval on a
   * given function.
   * @param functionSelector function to retrieve the timelock interval for.
   * @return The current minimum timelock interval for the given function.
   */
  function getTimelockInterval(
    bytes4 functionSelector
  ) public view returns (uint256 timelockInterval) {
    timelockInterval = _timelockIntervals[functionSelector];
  }

  /**
   * @notice Internal function that sets a timelock so that the specified
   * function can be called with the specified arguments. Note that existing
   * timelocks may be extended, but not shortened - this can also be used as a
   * method for "cancelling" a function call by extending the timelock to an
   * arbitrarily long duration. Keep in mind that new timelocks may be created
   * with a shorter duration on functions that already have other timelocks on
   * them, but only if they have different arguments.
   * @param functionSelector selector of the function to be called.   
   * @param arguments The abi-encoded arguments of the function to be called.
   * @param extraTime Additional time in seconds to add to the minimum timelock
   * interval for the given function.
   */
  function _setTimelock(
    bytes4 functionSelector,
    bytes memory arguments,
    uint256 extraTime
  ) internal {
    // Get timelock using current time, inverval for timelock ID, & extra time.
    uint256 timelock = _timelockIntervals[functionSelector].add(now).add(
      extraTime
    );

    // Get timelock ID using the supplied function arguments.
    bytes32 timelockID = keccak256(abi.encodePacked(arguments));

    // Get the current timelock, if any.
    uint256 currentTimelock = _timelocks[functionSelector][timelockID];

    // Ensure that the timelock duration does not decrease. Note that a new,
    // shorter timelock may still be set up on the same function in the event
    // that it is provided with different arguments.
    require(
      currentTimelock == 0 || timelock > currentTimelock,
      "Existing timelocks may only be extended."
    );

    // Set time that timelock will be complete using timelock ID and extra time.
    _timelocks[functionSelector][timelockID] = timelock;

    // Emit an event with all of the relevant information.
    emit TimelockInitiated(functionSelector, timelock, arguments);
  }

  /**
   * @notice Internal function to set an initial timelock interval for a given
   * function selector. Only callable during contract creation.
   * @param functionSelector the selector of the function to set the timelock
   * interval for.
   * @param newTimelockInterval the new minimum timelock interval to set for the
   * given function.
   */
  function _setInitialTimelockInterval(
    bytes4 functionSelector,
    uint256 newTimelockInterval
  ) internal {
    // Ensure that this function is only callable during contract construction.
    assembly { if extcodesize(address) { revert(0, 0) } }

    // Set the timelock interval and emit a `TimelockIntervalModified` event.
    _setTimelockInterval(functionSelector, newTimelockInterval);
  }

  /**
   * @notice Internal function to ensure that a timelock is complete and to
   * clear the existing timelock so it cannot later be reused.
   * @param functionSelector function to be called.   
   * @param arguments The abi-encoded arguments of the function to be called.
   */
  function _enforceTimelock(
    bytes4 functionSelector,
    bytes memory arguments
  ) internal {
    // Get timelock ID using the supplied function arguments.
    bytes32 timelockID = keccak256(abi.encodePacked(arguments));

    // Get the current timelock, if any.
    uint256 currentTimelock = _timelocks[functionSelector][timelockID];

    // Ensure that the timelock is set and has completed.
    require(
      currentTimelock != 0 && currentTimelock <= now,
      "Function cannot be called until a timelock has been set and has expired."
    );

    // Clear out the existing timelock so that it cannot be reused.
    delete _timelocks[functionSelector][timelockID];
  }

  /**
   * @notice Private function for setting a new timelock interval for a given 
   * function selector.
   * @param functionSelector the selector of the function to set the timelock
   * interval for.
   * @param newTimelockInterval the new minimum timelock interval to set for the
   * given function.
   */
  function _setTimelockInterval(
    bytes4 functionSelector,
    uint256 newTimelockInterval
  ) private {
    // Get the existing timelock interval, if any.
    uint256 oldTimelockInterval = _timelockIntervals[functionSelector];

    // Update the timelock interval on the provided function.
    _timelockIntervals[functionSelector] = newTimelockInterval;

    // Emit a `TimelockIntervalModified` event with the appropriate arguments.
    emit TimelockIntervalModified(
      functionSelector, oldTimelockInterval, newTimelockInterval
    );
  }
}

pragma solidity 0.5.11;


/**
 * @title AdharmaKeyRingImplementation
 * @author 0age
 * @notice The Adharma Key Ring is an emergency implementation that can be
 * immediately upgraded to by the Upgrade Beacon Controller Manager in the event
 * of a critical-severity exploit, or after a 90-day period of inactivity by
 * Dharma. It gives the user direct, sole custody and control over issuing calls
 * from their keyring, using any of their Admin or Dual keys, until the Upgrade
 * Beacon Controller Manager issues another upgrade to the implementation
 * contract.
 */
contract AdharmaKeyRingImplementation {
  event KeyModified(address indexed key, bool standard, bool admin);

  enum KeyType {
    None,
    Standard,
    Admin,
    Dual
  }

  struct AdditionalKeyCount {
    uint128 standard;
    uint128 admin;
  }

  struct AdditionalThreshold {
    uint128 standard;
    uint128 admin;
  }

  // WARNING: DO NOT REMOVE OR REORDER STORAGE WHEN WRITING NEW IMPLEMENTATIONS!

  // Track all keys as an address (as uint160) => key type mapping in slot zero.
  mapping (uint160 => KeyType) private _keys;

  // Track the nonce in slot 1 so that actions cannot be replayed. Note that
  // proper nonce management must be managed by the implementing contract when
  // using `isValidSignature`, as it is a static method and cannot change state.
  uint256 private _nonce;

  // Track the total number of standard and admin keys in storage slot 2.
  AdditionalKeyCount private _additionalKeyCounts;

  // Track the required threshold standard and admin actions in storage slot 3.
  AdditionalThreshold private _additionalThresholds;

  // END STORAGE DECLARATIONS - DO NOT REMOVE OR REORDER STORAGE ABOVE HERE!

  // Keep the initializer function on the contract in case a keyring has not yet
  // been deployed but an account it controls still contains user funds.
  function initialize(
    uint128 adminThreshold,
    uint128 executorThreshold,
    address[] calldata keys,
    uint8[] calldata keyTypes // 1: standard, 2: admin, 3: dual
  ) external {
    // Ensure that this function is only callable during contract construction.
    assembly { if extcodesize(address) { revert(0, 0) } }

    uint128 adminKeys;
    uint128 executorKeys;

    require(keys.length > 0, "Must supply at least one key.");

    require(adminThreshold > 0, "Admin threshold cannot be zero.");

    require(executorThreshold > 0, "Executor threshold cannot be zero.");

    require(
      keys.length == keyTypes.length,
      "Length of keys array and keyTypes arrays must be the same."
    );

    for (uint256 i = 0; i < keys.length; i++) {
      uint160 key = uint160(keys[i]);

      require(key != uint160(0), "Cannot supply the null address as a key.");

      require(_keys[key] == KeyType.None, "Cannot supply duplicate keys.");

      KeyType keyType = KeyType(keyTypes[i]);

      _keys[key] = keyType;

      bool isStandard = (keyType == KeyType.Standard || keyType == KeyType.Dual);
      bool isAdmin = (keyType == KeyType.Admin || keyType == KeyType.Dual);

      emit KeyModified(keys[i], isStandard, isAdmin);

      if (isStandard) {
        executorKeys++;
      }

      if (isAdmin) {
        adminKeys++;
      }
    }

    require(adminKeys > 0, "Must supply at least one admin key.");

    require(executorKeys > 0, "Must supply at least one executor key.");

    require(
      adminThreshold >= adminKeys,
      "Admin threshold cannot be less than the total supplied admin keys."
    );

    require(
      executorThreshold >= executorKeys,
      "Executor threshold cannot be less than the total supplied executor keys."
    );

    if (adminKeys > 1 || executorKeys > 1) {
      _additionalKeyCounts = AdditionalKeyCount({
        standard: executorKeys - 1,
        admin: adminKeys - 1
      });
    }

    if (adminThreshold > 1 || executorThreshold > 1) {
      _additionalThresholds = AdditionalThreshold({
        standard: executorThreshold - 1,
        admin: adminThreshold - 1
      });
    }
  }

  // Admin or Dual key holders have authority to issue actions from the keyring.
  function takeAction(
    address payable to, uint256 value, bytes calldata data, bytes calldata
  ) external returns (bool ok, bytes memory returnData) {
    require(
      _keys[uint160(msg.sender)] == KeyType.Admin ||
      _keys[uint160(msg.sender)] == KeyType.Dual,
      "Only Admin or Dual key holders can call this function."
    );

    (ok, returnData) = to.call.value(value)(data);
  }
}

pragma solidity 0.5.11;

import "@openzeppelin/contracts/cryptography/ECDSA.sol";
import "../../../interfaces/DharmaKeyRingImplementationV0Interface.sol";
import "../../../interfaces/ERC1271.sol";


/**
 * @title DharmaKeyRingImplementationV0
 * @author 0age
 * @notice The Dharma Key Ring is a smart contract that implements ERC-1271 and
 * can be used in place of an externally-owned account for the user signing key
 * on the Dharma Smart Wallet to support multiple user signing keys. For this V0
 * implementation, new Dual keys (standard + admin) can be added, but cannot be
 * removed, and the action threshold is fixed at one. Upgrades are managed by an
 * upgrade beacon, similar to the one utilized by the Dharma Smart Wallet.
 */
contract DharmaKeyRingImplementationV0 is
  DharmaKeyRingImplementationV0Interface,
  ERC1271 {
  using ECDSA for bytes32;
  // WARNING: DO NOT REMOVE OR REORDER STORAGE WHEN WRITING NEW IMPLEMENTATIONS!

  // Track all keys as an address (as uint160) => key type mapping in slot zero.
  mapping (uint160 => KeyType) private _keys;

  // Track the nonce in slot 1 so that actions cannot be replayed. Note that
  // proper nonce management must be managed by the implementing contract when
  // using `isValidSignature`, as it is a static method and cannot change state.
  uint256 private _nonce;

  // Track the total number of standard and admin keys in storage slot 2.
  AdditionalKeyCount private _additionalKeyCounts;

  // Track the required threshold standard and admin actions in storage slot 3.
  // AdditionalThreshold private _additionalThresholds;

  // END STORAGE DECLARATIONS - DO NOT REMOVE OR REORDER STORAGE ABOVE HERE!

  // The key ring version will be used when constructing valid signatures.
  uint256 internal constant _DHARMA_KEY_RING_VERSION = 0;

  // ERC-1271 must return this magic value when `isValidSignature` is called.
  bytes4 internal constant _ERC_1271_MAGIC_VALUE = bytes4(0x20c13b0b);

  function initialize(
    uint128 adminThreshold,
    uint128 executorThreshold,
    address[] calldata keys,
    uint8[] calldata keyTypes // must all be 3 (Dual) for V0
  ) external {
    // Ensure that this function is only callable during contract construction.
    assembly { if extcodesize(address) { revert(0, 0) } }

    require(keys.length == 1, "Must supply exactly one key in V0.");

    require(keys[0] != address(0), "Cannot supply the null address as a key.");

    require(
      keyTypes.length == 1 && keyTypes[0] == uint8(3),
      "Must supply exactly one Dual keyType (3) in V0."
    );

    require(adminThreshold == 1, "Admin threshold must be exactly one in V0.");

    require(
      executorThreshold == 1, "Executor threshold must be exactly one in V0."
    );

    _keys[uint160(keys[0])] = KeyType.Dual;

    emit KeyModified(keys[0], true, true);

    // Note: skip additional key counts + thresholds setup in V0 (only one key).
  }

  function takeAdminAction(
    AdminActionType adminActionType, uint160 argument, bytes calldata signatures
  ) external {
    // Only Admin Action Type 6 (AddDualKey) is supported in V0.
    require(
      adminActionType == AdminActionType.AddDualKey,
      "Only adding new Dual key types (admin action type 6) is supported in V0."
    );

    require(argument != uint160(0), "Cannot supply the null address as a key.");

    require(_keys[argument] == KeyType.None, "Key already exists.");

    _verifyOrderedSignatures(_getAdminActionHash(argument), signatures);

    _additionalKeyCounts.standard++;
    _additionalKeyCounts.admin++;

    _keys[argument] = KeyType.Dual;

    emit KeyModified(address(argument), true, true);

    _nonce++;
  }

  function isValidSignature(
    bytes calldata data, bytes calldata signatures
  ) external view returns (bytes4 magicValue) {
    (bytes32 hash, , ) = abi.decode(data, (bytes32, uint8, bytes));

    _verifyOrderedSignatures(hash, signatures);

    magicValue = _ERC_1271_MAGIC_VALUE;
  }

  function getAdminActionID(
    AdminActionType adminActionType, uint160 argument
  ) external view returns (bytes32 adminActionID) {
    adminActionType;
    adminActionID = _getAdminActionHash(argument);
  }

  /**
   * @notice Pure function for getting the current Dharma Key Ring version.
   * @return The current Dharma Key Ring version.
   */
  function getVersion() external pure returns (uint256 version) {
    version = _DHARMA_KEY_RING_VERSION;
  }

  function _getAdminActionHash(
    uint160 argument
  ) internal view returns (bytes32 hash) {
    hash = keccak256(
      abi.encodePacked(
        address(this), _DHARMA_KEY_RING_VERSION, _nonce, argument
      )
    );
  }

  function _verifyOrderedSignatures(
    bytes32 hash, bytes memory signature
  ) internal view {   
    require(
      _keys[uint160(hash.recover(signature))] == KeyType.Dual,
      "Supplied signature does not have a signer with the required key type."
    );
  }
}

pragma solidity 0.5.11;

import "../../helpers/ECDSAGroup.sol";
import "../../../interfaces/DharmaKeyRingImplementationV0Interface.sol";
import "../../../interfaces/DharmaKeyRingImplementationV1Interface.sol";
import "../../../interfaces/ERC1271.sol";


/**
 * @title DharmaKeyRingImplementationV1
 * @author 0age
 * @notice The Dharma Key Ring is a smart contract that implements ERC-1271 and
 * can be used in place of an externally-owned account for the user signing key
 * on the Dharma Smart Wallet to support multiple user signing keys. It
 * distinguishes between Admin keys, which are used to modify sigining keys that
 * are set on the key ring or to set a new signing key for the user on the smart
 * wallet, and Standard or Executor keys, which are used when calling 
 * `isValidSignature` from the smart wallet in order to validate all other smart
 * wallet actions. Upgrades are managed by an upgrade beacon, similar to the one
 * utilized by the Dharma Smart Wallet.
 * @dev There are multiple enhancements that can be made to this POC from here,
 * including (but not limited to):
 *   - Iterating over all keys that have been set on the keyring
 *   - Allowing for other smart contracts to be specified as signers
 *   - Allowing for keys that have a more restrictive set of permissions
 */
contract DharmaKeyRingImplementationV1 is
  DharmaKeyRingImplementationV0Interface,
  DharmaKeyRingImplementationV1Interface,
  ERC1271 {
  using ECDSAGroup for bytes32;

  // WARNING: DO NOT REMOVE OR REORDER STORAGE WHEN WRITING NEW IMPLEMENTATIONS!

  // Track all keys as an address (as uint160) => key type mapping in slot zero.
  mapping (uint160 => KeyType) private _keys;

  // Track the nonce in slot 1 so that actions cannot be replayed. Note that
  // proper nonce management must be managed by the implementing contract when
  // using `isValidSignature`, as it is a static method and cannot change state.
  uint256 private _nonce;

  // Track the total number of standard and admin keys in storage slot 2.
  AdditionalKeyCount private _additionalKeyCounts;

  // Track the required threshold standard and admin actions in storage slot 3.
  AdditionalThreshold private _additionalThresholds;

  // END STORAGE DECLARATIONS - DO NOT REMOVE OR REORDER STORAGE ABOVE HERE!

  // The key ring version will be used when constructing valid signatures.
  uint256 internal constant _DHARMA_KEY_RING_VERSION = 1;

  // ERC-1271 must return this magic value when `isValidSignature` is called.
  bytes4 internal constant _ERC_1271_MAGIC_VALUE = bytes4(0x20c13b0b);

  function initialize(
    uint128 adminThreshold,
    uint128 executorThreshold,
    address[] calldata keys,
    uint8[] calldata keyTypes // 1: standard, 2: admin, 3: dual
  ) external {
    // Ensure that this function is only callable during contract construction.
    assembly { if extcodesize(address) { revert(0, 0) } }

    uint128 adminKeys;
    uint128 executorKeys;

    require(keys.length > 0, "Must supply at least one key.");

    require(adminThreshold > 0, "Admin threshold cannot be zero.");

    require(executorThreshold > 0, "Executor threshold cannot be zero.");

    require(
      keys.length == keyTypes.length,
      "Length of keys array and keyTypes arrays must be the same."
    );

    for (uint256 i = 0; i < keys.length; i++) {
      uint160 key = uint160(keys[i]);

      require(key != uint160(0), "Cannot supply the null address as a key.");

      require(_keys[key] == KeyType.None, "Cannot supply duplicate keys.");

      KeyType keyType = KeyType(keyTypes[i]);

      _keys[key] = keyType;

      bool isStandard = (keyType == KeyType.Standard || keyType == KeyType.Dual);
      bool isAdmin = (keyType == KeyType.Admin || keyType == KeyType.Dual);

      emit KeyModified(keys[i], isStandard, isAdmin);

      if (isStandard) {
        executorKeys++;
      }

      if (isAdmin) {
        adminKeys++;
      }
    }

    require(adminKeys > 0, "Must supply at least one admin key.");

    require(executorKeys > 0, "Must supply at least one executor key.");

    require(
      adminThreshold >= adminKeys,
      "Admin threshold cannot be less than the total supplied admin keys."
    );

    require(
      executorThreshold >= executorKeys,
      "Executor threshold cannot be less than the total supplied executor keys."
    );

    if (adminKeys > 1 || executorKeys > 1) {
      _additionalKeyCounts = AdditionalKeyCount({
        standard: executorKeys - 1,
        admin: adminKeys - 1
      });
    }

    if (adminThreshold > 1 || executorThreshold > 1) {
      _additionalThresholds = AdditionalThreshold({
        standard: executorThreshold - 1,
        admin: adminThreshold - 1
      });
    }
  }

  function takeAdminAction(
    AdminActionType adminActionType, uint160 argument, bytes calldata signatures
  ) external {
    _verifyOrderedSignatures(
      KeyType.Admin, _getAdminActionHash(adminActionType, argument), signatures
    );

    uint8 adminActionCategory = uint8(adminActionType) % 3;
    uint8 adminActionKeyCategory = uint8(adminActionType) / 3 + 1;
    bool isStandard = adminActionKeyCategory != 2;
    bool isAdmin = adminActionKeyCategory != 1;

    if (adminActionCategory == 0) { // Add
      require(argument != uint160(0), "Cannot supply null address as a key.");

      require(_keys[argument] == KeyType.None, "Key already exists.");

      _additionalKeyCounts = AdditionalKeyCount({
        standard: _additionalKeyCounts.standard + (isStandard ? 1 : 0),
        admin: _additionalKeyCounts.admin + (isAdmin ? 1 : 0)
      });

      _keys[argument] = KeyType(adminActionKeyCategory);
    } else if (adminActionCategory == 1) { // Remove
      require(_keys[argument] != KeyType.None, "Key does not exist.");

      if (isStandard) {
        require(
          _additionalThresholds.standard > _additionalKeyCounts.standard,
          "Cannot reduce number of standard keys below required threshold."
        );
      }

      if (isAdmin) {
        require(
          _additionalThresholds.admin > _additionalKeyCounts.admin,
          "Cannot reduce number of admin keys below required threshold."
        );
      }

      _additionalKeyCounts = AdditionalKeyCount({
        standard: _additionalKeyCounts.standard - (isStandard ? 1 : 0),
        admin: _additionalKeyCounts.admin - (isAdmin ? 1 : 0)
      });

      KeyType currentKeyType = _keys[argument];
      if (
        adminActionKeyCategory == 3 ||
        currentKeyType == KeyType(adminActionKeyCategory)
      ) {
        delete _keys[argument];
      } else if (currentKeyType == KeyType.Dual) {
        _keys[argument] = KeyType(isStandard ? 2 : 1);
      } else {
        revert("Supplied key type is not currently set.");
      }

    } else if (adminActionCategory == 2) { // SetThreshold
      uint128 threshold = uint128(argument);
      require(threshold > 0, "Cannot reduce threshold to zero.");
      threshold--;

      if (isStandard) {
        require(
          threshold <= _additionalKeyCounts.standard,
          "Cannot increase standard threshold above number of standard keys."
        );
      }

      if (isAdmin) {
        require(
          threshold <= _additionalKeyCounts.admin,
          "Cannot increase admin threshold above number of admin keys."
        );
      }

      _additionalThresholds = AdditionalThreshold({
        standard: isStandard ? threshold : _additionalThresholds.standard,
        admin: isAdmin ? threshold : _additionalThresholds.admin
      });

      emit ThresholdModified(
        uint256(_additionalThresholds.standard),
        uint256(_additionalThresholds.admin)
      );
    }

    if (adminActionCategory != 2) {
      emit KeyModified(
        address(argument),
        _keys[argument] == KeyType.Standard || _keys[argument] == KeyType.Dual,
        _keys[argument] == KeyType.Admin || _keys[argument] == KeyType.Dual
      );
    }

    _nonce++;
  }

  function takeAction(
    address payable to, uint256 value, bytes calldata data, bytes calldata signatures
  ) external returns (bool ok, bytes memory returnData) {
    // admin-only: 0x44f62b3c => setUserSigningKey(address,uint256,bytes,bytes)
    _verifyOrderedSignatures(
      (
        (
          data.length >= 4 &&
          data[0] == byte(0x44) &&
          data[1] == byte(0xf6) &&
          data[2] == byte(0x2b) &&
          data[3] == byte(0x3c)
        )
        ? KeyType.Admin
        : KeyType.Standard
      ),
      _getStandardActionHash(to, value, data),
      signatures
    );

    _nonce++;

    (ok, returnData) = to.call.value(value)(data);
  }

  function isValidSignature(
    bytes calldata data, bytes calldata signatures
  ) external view returns (bytes4 magicValue) {
    (bytes32 hash, uint8 action, ) = abi.decode(data, (bytes32, uint8, bytes));

    // Calling setUserSigningKey (ActionType 1) requires admin signatures.
    _verifyOrderedSignatures(
      action != 1 ? KeyType.Standard : KeyType.Admin,
      hash,
      signatures
    );

    magicValue = _ERC_1271_MAGIC_VALUE;
  }

  function getActionID(
    address payable to, uint256 value, bytes calldata data
  ) external view returns (bytes32 actionID) {
    actionID = _getStandardActionHash(to, value, data);
  }

  function getAdminActionID(
    AdminActionType adminActionType, uint160 argument
  ) external view returns (bytes32 adminActionID) {
    adminActionID = _getAdminActionHash(adminActionType, argument);
  }

  /**
   * @notice Pure function for getting the current Dharma Key Ring version.
   * @return The current Dharma Key Ring version.
   */
  function getVersion() external pure returns (uint256 version) {
    version = _DHARMA_KEY_RING_VERSION;
  }

  function _getStandardActionHash(
    address payable to, uint256 value, bytes memory data
  ) internal view returns (bytes32 hash) {
    hash = keccak256(
      abi.encodePacked(
        address(this),
        _DHARMA_KEY_RING_VERSION,
        _nonce,
        KeyType.Standard,
        to,
        value,
        data
      )
    );
  }

  function _getAdminActionHash(
    AdminActionType adminActionType, uint160 argument
  ) internal view returns (bytes32 hash) {
    hash = keccak256(
      abi.encodePacked(
        address(this),
        _DHARMA_KEY_RING_VERSION,
        _nonce,
        KeyType.Admin,
        adminActionType,
        argument
      )
    );
  }

  function _verifyOrderedSignatures(
    KeyType requiredKeyType, bytes32 hash, bytes memory signatures
  ) internal view {
    uint160[] memory signers = hash.recoverGroup(signatures);

    uint256 threshold = (
      requiredKeyType == KeyType.Standard
        ? uint256(_additionalThresholds.standard)
        : uint256(_additionalThresholds.admin)
    ) + 1;

    require(
      signers.length >= threshold,
      "Supplied number of signatures does not meet the required threshold."
    );

    uint160 lastSigner = 0;
    for (uint256 i = 0; i < signers.length; i++) {
      uint160 signer = signers[i];
      KeyType keyType = _keys[signer];
      require(
        keyType == KeyType.Dual || keyType == requiredKeyType,
        "Supplied signature does not have a signer with the required key type."
      );
      require(signer > lastSigner, "Invalid signature ordering.");
      lastSigner = signer;
    }
  }
}

pragma solidity 0.5.11;


/**
 * @title AdharmaSmartWalletImplementation
 * @author 0age
 * @notice The Adharma smart wallet is an emergency implementation wallet that
 * can be immediately upgraded to by the Upgrade Beacon Controller Manager in
 * the event of a critical-severity exploit, or after a 90-day period of
 * inactivity by Dharma. It gives the user direct, sole custody and control over
 * their smart wallet until the Upgrade Beacon Controller Manager issues another
 * upgrade to the implementation contract.
 */
contract AdharmaSmartWalletImplementation {
  // The user's key is still held in storage slot zero.
  address private _key;

  // the smart wallet can still receive funds, though it is inadvisable.
  function () external payable {}

  // Keep the initializer function on the contract in case a smart wallet has
  // not yet been deployed but the account still contains user funds.
  function initialize(address key) external {
    // Ensure that this function is only callable during contract construction.
    assembly { if extcodesize(address) { revert(0, 0) } }

    // Set up the user's key.
    _key = key;
  }

  // the key's owner has sole authority to make calls from the smart wallet.
  function performCall(
    address payable to,
    uint256 amount,
    bytes calldata data
  ) external payable returns (
    bool ok,
    bytes memory returnData
  ) {
    require(msg.sender == _key, "Caller prohibited.");
    (ok, returnData) = to.call.value(amount)(data);
    require(ok, string(returnData));
  }
}

pragma solidity 0.5.11;

import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "../../../interfaces/DharmaSmartWalletImplementationV0Interface.sol";
import "../../../interfaces/CTokenInterface.sol";
import "../../../interfaces/USDCV1Interface.sol";
import "../../../interfaces/ComptrollerInterface.sol";
import "../../../interfaces/DharmaKeyRegistryInterface.sol";


/**
 * @title DharmaSmartWalletImplementationV0
 * @author 0age
 * @notice The V0 implementation for the Dharma Smart Wallet contains helper
 * functions to facilitate lending funds to CompoundV2 and for preparing Dharma
 * users for a smooth transition to a joint-custody smart wallet. It supports
 * meta-transactions, signed by a key corresponding to the public key returned
 * by the Dharma Key Registry and relayed by any transaction submitter that has
 * provided the specified gas requirement. The smart wallet instances utilizing
 * this implementation are deployed through the Dharma Smart Wallet Factory via
 * `CREATE2`, which allows for their address to be known ahead of time, and any
 * Dai or USDC that has already been sent into that address will automatically
 * be deposited into Compound upon deployment of the new smart wallet instance.
 */
contract DharmaSmartWalletImplementationV0 is DharmaSmartWalletImplementationV0Interface {
  using Address for address;
  using ECDSA for bytes32;
  // WARNING: DO NOT REMOVE OR REORDER STORAGE WHEN WRITING NEW IMPLEMENTATIONS!

  // The user signing key associated with this account is in storage slot 0.
  // It is the core differentiator when it comes to the account in question.
  address private _userSigningKey;

  // The nonce associated with this account is in storage slot 1. Every time a
  // signature is submitted, it must have the appropriate nonce, and once it has
  // been accepted the nonce will be incremented.
  uint256 private _nonce;

  // The self-call context flag is in storage slot 2. Some protected functions
  // may only be called externally from calls originating from other methods on
  // this contract, which enables appropriate exception handling on reverts.
  // Any storage should only be set immediately preceding a self-call and should
  // be cleared upon entering the protected function being called.
  bytes4 internal _selfCallContext;

  // END STORAGE DECLARATIONS - DO NOT REMOVE OR REORDER STORAGE ABOVE HERE!

  // The smart wallet version will be used when constructing valid signatures.
  uint256 internal constant _DHARMA_SMART_WALLET_VERSION = 0;

  // The Dharma Key Registry holds a public key for verifying meta-transactions.
  DharmaKeyRegistryInterface internal constant _DHARMA_KEY_REGISTRY = (
    DharmaKeyRegistryInterface(0x000000005D7065eB9716a410070Ee62d51092C98)
  );

  // This contract interfaces with Dai, USDC, and related CompoundV2 contracts.
  CTokenInterface internal constant _CDAI = CTokenInterface(
    0xF5DCe57282A584D2746FaF1593d3121Fcac444dC // mainnet
  );

  CTokenInterface internal constant _CUSDC = CTokenInterface(
    0x39AA39c021dfbaE8faC545936693aC917d5E7563 // mainnet
  );

  IERC20 internal constant _DAI = IERC20(
    0x89d24A6b4CcB1B6fAA2625fE562bDD9a23260359 // mainnet
  );

  IERC20 internal constant _USDC = IERC20(
    0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48 // mainnet
  );

  USDCV1Interface internal constant _USDC_NAUGHTY = USDCV1Interface(
    0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48 // mainnet
  );

  ComptrollerInterface internal constant _COMPTROLLER = ComptrollerInterface(
    0x3d9819210A31b4961b30EF54bE2aeD79B9c9Cd3B // mainnet
  );

  // Compound returns a value of 0 to indicate success, or lack of an error.
  uint256 internal constant _COMPOUND_SUCCESS = 0;

  /**
   * @notice In initializer, set up user signing key, set approval on the cDAI
   * and cUSDC contracts, deposit any Dai and/or USDC already at the address to
   * Compound, and enter markets for cDAI, cUSDC, and cETH (just so it doesn't
   * need to be performed at some later stage when we move to a borrow-enabled
   * smart wallet). In V0, the user signing key is not actually used to sign
   * actions - the goal is to get all of the smart wallets set up with a user
   * signing key before V1. Note that this initializer is only callable while
   * the smart wallet instance is still in the contract creation phase.
   * @param userSigningKey address The initial user signing key for the smart
   * wallet.
   */
  function initialize(address userSigningKey) external {
    // Ensure that this function is only callable during contract construction.
    assembly { if extcodesize(address) { revert(0, 0) } }

    // Set up the user's signing key and emit a corresponding event.
    _setUserSigningKey(userSigningKey);

    // Approve the cDAI contract to transfer Dai on behalf of this contract.
    if (_setFullApproval(AssetType.DAI)) {
      // Get the current Dai balance on this contract.
      uint256 daiBalance = _DAI.balanceOf(address(this));

      // Try to deposit any dai balance on Compound.
      _depositOnCompound(AssetType.DAI, daiBalance);
    }

    // Approve the cUSDC contract to transfer USDC on behalf of this contract.
    if (_setFullApproval(AssetType.USDC)) {
      // Get the current USDC balance on this contract.
      uint256 usdcBalance = _USDC.balanceOf(address(this));

      // Try to deposit any USDC balance on Compound.
      _depositOnCompound(AssetType.USDC, usdcBalance);
    }

    // Enter DAI + USDC + ETH markets now to avoid a need to reinitialize later.
    _enterMarkets();
  }

  /**
   * @notice Deposit all Dai and USDC currently residing at this address to
   * Compound. Note that "repay" is not currently implemented, but the function
   * is still named "repayAndDeposit" so that infrastructure around calling this
   * function will not need to be altered for a future smart wallet version. If
   * some step of this function fails, the function itself will still succeed,
   * but an ExternalError with information on what went wrong will be emitted.
   */
  function repayAndDeposit() external {
    // Get the current Dai balance on this contract.
    uint256 daiBalance = _DAI.balanceOf(address(this));

    // Deposit any available Dai.
    _depositOnCompound(AssetType.DAI, daiBalance);

    // Get the current USDC balance on this contract.
    uint256 usdcBalance = _USDC.balanceOf(address(this));

    // If there is any USDC balance, check for adequate approval for cUSDC.
    if (usdcBalance > 0) {
      uint256 usdcAllowance = _USDC.allowance(address(this), address(_CUSDC));
      // If allowance is insufficient, try to set it before depositing.
      if (usdcAllowance < usdcBalance) {
        if (_setFullApproval(AssetType.USDC)) {
          // Deposit any available USDC.
          _depositOnCompound(AssetType.USDC, usdcBalance);
        }
      // Otherwise, go ahead and try the deposit.
      } else {
        // Deposit any available USDC.
        _depositOnCompound(AssetType.USDC, usdcBalance);
      }
    }
  }

  /**
   * @notice Withdraw Dai to a provided recipient address by redeeming the
   * underlying Dai from the cDAI contract and transferring it to the recipient.
   * All Dai in Compound and in the smart wallet itself can be withdrawn by
   * providing an amount of uint256(-1) or 0xfff...fff. This function can be
   * called directly by the account set as the global key on the Dharma Key
   * Registry, or by any relayer that provides a signed message from the same
   * keyholder. The nonce used for the signature must match the current nonce on
   * the smart wallet, and gas supplied to the call must exceed the specified
   * minimum action gas, plus the gas that will be spent before the gas check is
   * reached - usually somewhere around 25,000 gas. If the withdrawal fails, an
   * ExternalError with additional details on what went wrong will be emitted.
   * Note that some dust may still be left over, even in the event of a max
   * withdrawal, due to the fact that Dai has a higher precision than cDAI. Also
   * note that the withdrawal will fail in the event that Compound does not have
   * sufficient Dai available to withdraw.
   * @param amount uint256 The amount of Dai to withdraw.
   * @param recipient address The account to transfer the withdrawn Dai to.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes Unused in V0.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function withdrawDai(
    uint256 amount,
    address recipient,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok) {
    // Declare the unused value to avoid compiler and linter warnings.
    userSignature;

    // Ensure either caller or supplied signature is valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.DAIWithdrawal,
      amount,
      recipient,
      minimumActionGas,
      dharmaSignature
    );

    // Set the self-call context so we can call _withdrawDaiAtomic.
    _selfCallContext = this.withdrawDai.selector;

    // Make the atomic self-call - if redeemUnderlying fails on cDAI, it will
    // succeed but nothing will happen except firing an ExternalError event. If
    // the second part of the self-call (the Dai transfer) fails, it will revert
    // and roll back the first part of the call, and we'll fire an ExternalError
    // event after returning from the failed call.
    bytes memory returnData;
    (ok, returnData) = address(this).call(abi.encodeWithSelector(
      this._withdrawDaiAtomic.selector, amount, recipient
    ));

    // If the atomic call failed, diagnose the reason and emit an event.
    if (!ok) {
      // This revert could be caused by cDai MathError or Dai transfer error.
      _diagnoseAndEmitErrorRelatedToWithdrawal(AssetType.DAI);
    } else {
      // Set ok to false if the call succeeded but the withdrawal failed.
      ok = abi.decode(returnData, (bool));
    }
  }

  /**
   * @notice Protected function that can only be called from `withdrawDai` on
   * this contract. It will attempt to withdraw the supplied amount of Dai, or
   * the maximum amount if specified using `uint256(-1)`, to the supplied
   * recipient address by redeeming the underlying Dai from the cDAI contract
   * and transferring it to the recipient. An ExternalError will be emitted and
   * the transfer will be skipped if the call to `redeemUnderlying` fails, and
   * any revert will be caught by `withdrawDai` and diagnosed in order to emit
   * an appropriate ExternalError as well.
   * @param amount uint256 The amount of Dai to withdraw.
   * @param recipient address The account to transfer the withdrawn Dai to.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function _withdrawDaiAtomic(
    uint256 amount,
    address recipient
  ) external returns (bool success) {
    // Ensure caller is this contract and self-call context is correctly set.
    _enforceSelfCallFrom(this.withdrawDai.selector);

    // If amount = 0xfff...fff, withdraw the maximum amount possible.
    bool maxWithdraw = (amount == uint256(-1));
    uint256 redeemUnderlyingAmount;
    if (maxWithdraw) {
      redeemUnderlyingAmount = _CDAI.balanceOfUnderlying(address(this));
    } else {
      redeemUnderlyingAmount = amount;
    }

    // Attempt to withdraw specified Dai amount from Compound before proceeding.
    if (_withdrawFromCompound(AssetType.DAI, redeemUnderlyingAmount)) {
      // At this point dai transfer *should* never fail - wrap it just in case.
      if (maxWithdraw) {
        require(_DAI.transfer(recipient, _DAI.balanceOf(address(this))));
      } else {
        require(_DAI.transfer(recipient, amount));
      }
      success = true;
    }
  }

  /**
   * @notice Withdraw USDC to a provided recipient address by redeeming the
   * underlying USDC from the cUSDC contract and transferring it to recipient.
   * All USDC in Compound and in the smart wallet itself can be withdrawn by
   * providing an amount of uint256(-1) or 0xfff...fff. This function can be
   * called directly by the account set as the global key on the Dharma Key
   * Registry, or by any relayer that provides a signed message from the same
   * keyholder. The nonce used for the signature must match the current nonce on
   * the smart wallet, and gas supplied to the call must exceed the specified
   * minimum action gas, plus the gas that will be spent before the gas check is
   * reached - usually somewhere around 25,000 gas. If the withdrawal fails, an
   * ExternalError with additional details on what went wrong will be emitted.
   * Note that the USDC contract can be paused and also allows for blacklisting
   * accounts - either of these possibilities may cause a withdrawal to fail. In
   * addition, Compound may not have sufficient USDC available at the time to
   * withdraw.
   * @param amount uint256 The amount of USDC to withdraw.
   * @param recipient address The account to transfer the withdrawn USDC to.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes Unused in V0.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function withdrawUSDC(
    uint256 amount,
    address recipient,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok) {
    // Declare the unused value to avoid compiler and linter warnings.
    userSignature;

    // Ensure either caller or supplied signature is valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.USDCWithdrawal,
      amount,
      recipient,
      minimumActionGas,
      dharmaSignature
    );

    // Set the self-call context so we can call _withdrawUSDCAtomic.
    _selfCallContext = this.withdrawUSDC.selector;

    // Make the atomic self-call - if redeemUnderlying fails on cUSDC, it will
    // succeed but nothing will happen except firing an ExternalError event. If
    // the second part of the self-call (USDC transfer) fails, it will revert
    // and roll back the first part of the call, and we'll fire an ExternalError
    // event after returning from the failed call.
    bytes memory returnData;
    (ok, returnData) = address(this).call(abi.encodeWithSelector(
      this._withdrawUSDCAtomic.selector, amount, recipient
    ));
    if (!ok) {
      // This revert could be caused by cUSDC MathError or USDC transfer error.
      _diagnoseAndEmitErrorRelatedToWithdrawal(AssetType.USDC);
    } else {
      // Ensure that ok == false in the event the withdrawal failed.
      ok = abi.decode(returnData, (bool));
    }
  }

  /**
   * @notice Protected function that can only be called from `withdrawUSDC` on
   * this contract. It will attempt to withdraw the supplied amount of USDC, or
   * the maximum amount if specified using `uint256(-1)`, to the supplied
   * recipient address by redeeming the underlying USDC from the cUSDC contract
   * and transferring it to the recipient. An ExternalError will be emitted and
   * the transfer will be skipped if the call to `redeemUnderlying` fails, and
   * any revert will be caught by `withdrawUSDC` and diagnosed in order to emit
   * an appropriate ExternalError as well.
   * @param amount uint256 The amount of USDC to withdraw.
   * @param recipient address The account to transfer the withdrawn USDC to.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function _withdrawUSDCAtomic(
    uint256 amount,
    address recipient
  ) external returns (bool success) {
    // Ensure caller is this contract and self-call context is correctly set.
    _enforceSelfCallFrom(this.withdrawUSDC.selector);

    // If amount = 0xfff...fff, withdraw the maximum amount possible.
    bool maxWithdraw = (amount == uint256(-1));
    uint256 redeemUnderlyingAmount;
    if (maxWithdraw) {
      redeemUnderlyingAmount = _CUSDC.balanceOfUnderlying(address(this));
    } else {
      redeemUnderlyingAmount = amount;
    }

    // Try to withdraw specified USDC amount from Compound before proceeding.
    if (_withdrawFromCompound(AssetType.USDC, redeemUnderlyingAmount)) {
      // Ensure that the USDC transfer does not fail.
      if (maxWithdraw) {
        require(_USDC.transfer(recipient, _USDC.balanceOf(address(this))));
      } else {
        require(_USDC.transfer(recipient, amount));
      }
      success = true;
    }
  }

  /**
   * @notice Allow signatory to increment the nonce at any point. The current
   * nonce needs to be provided as an argument to the a signature so as not to
   * enable griefing attacks. All arguments can be omitted if called directly.
   * No value is returned from this function - it will either succeed or revert.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param signature bytes A signature that resolves to the public key returned
   * for this account from the Dharma Key Registry. A unique hash returned from
   * `getCustomActionID` is prefixed and hashed to create the signed message.
   */  
  function cancel(
    uint256 minimumActionGas,
    bytes calldata signature
  ) external {
    // Ensure either caller or supplied signature is valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.Cancel,
      0,
      address(0),
      minimumActionGas,
      signature
    );
  }

  /**
   * @notice Allow signatory to set a new user signing key. The current nonce
   * needs to be provided as an argument to the a signature so as not to enable
   * griefing attacks. All arguments apart from the user signing key can be
   * omitted if called directly. No value is returned from this function - it
   * will either succeed or revert.
   * @param userSigningKey address The new user signing key to set on this smart
   * wallet.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes Unused in V0.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   */
  function setUserSigningKey(
    address userSigningKey,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external {
    // Declare the unused value to avoid compiler and linter warnings.
    userSignature;

    // Ensure either caller or supplied signature is valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.SetUserSigningKey,
      0,
      userSigningKey,
      minimumActionGas,
      dharmaSignature
    );

    // Set new user signing key on smart wallet and emit a corresponding event.
    _setUserSigningKey(userSigningKey);
  }

  /**
   * @notice Retrieve the Dai and USDC balances held by the smart wallet, both
   * directly and held in Compound. This is not a view function since Compound
   * will calculate accrued interest as part of the underlying balance checks,
   * but can still be called from an off-chain source as though it were a view
   * function.
   * @return The Dai balance, the USDC balance, the underlying Dai balance of
   * the cDAI balance, and the underlying USDC balance of the cUSDC balance.
   */
  function getBalances() external returns (
    uint256 daiBalance,
    uint256 usdcBalance,
    uint256 etherBalance, // always returns 0
    uint256 cDaiUnderlyingDaiBalance,
    uint256 cUsdcUnderlyingUsdcBalance,
    uint256 cEtherUnderlyingEtherBalance // always returns 0
  ) {
    daiBalance = _DAI.balanceOf(address(this));
    usdcBalance = _USDC.balanceOf(address(this));
    cDaiUnderlyingDaiBalance = _CDAI.balanceOfUnderlying(address(this));
    cUsdcUnderlyingUsdcBalance = _CUSDC.balanceOfUnderlying(address(this));
  }

  /**
   * @notice View function for getting the current user signing key for the
   * smart wallet.
   * @return The current user signing key.
   */
  function getUserSigningKey() external view returns (address userSigningKey) {
    userSigningKey = _userSigningKey;
  }

  /**
   * @notice View function for getting the current nonce of the smart wallet.
   * This nonce is incremented whenever an action is taken that requires a
   * signature and/or a specific caller.
   * @return The current nonce.
   */
  function getNonce() external view returns (uint256 nonce) {
    nonce = _nonce;
  }

  /**
   * @notice View function that, given an action type and arguments, will return
   * the action ID or message hash that will need to be prefixed (according to
   * EIP-191 0x45), hashed, and signed by the key designated by the Dharma Key
   * Registry in order to construct a valid signature for the corresponding
   * action. The current nonce will be used, which means that it will only be
   * valid for the next action taken.
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V0 include Cancel (0), SetUserSigningKey (1), DAIWithdrawal (4),
   * and USDCWithdrawal (5).
   * @param amount uint256 The amount to withdraw for Withdrawal actions, or 0
   * for other action types.
   * @param recipient address The account to transfer withdrawn funds to, the
   * new user signing key, or the null address for cancelling.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @return The action ID, which will need to be prefixed, hashed and signed in
   * order to construct a valid signature.
   */
  function getNextCustomActionID(
    ActionType action,
    uint256 amount,
    address recipient,
    uint256 minimumActionGas
  ) external view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getCustomActionID(
      action, amount, recipient, _nonce, minimumActionGas, _getDharmaSigningKey()
    );
  }

  /**
   * @notice View function that, given an action type and arguments, will return
   * the action ID or message hash that will need to be prefixed (according to
   * EIP-191 0x45), hashed, and signed by the key designated by the Dharma Key
   * Registry in order to construct a valid signature for the corresponding
   * action. Any nonce value may be supplied, which enables constructing valid
   * message hashes for multiple future actions ahead of time.
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V0 include Cancel (0), SetUserSigningKey (1), DAIWithdrawal (4),
   * and USDCWithdrawal (5).
   * @param amount uint256 The amount to withdraw for Withdrawal actions, or 0
   * for other action types.
   * @param recipient address The account to transfer withdrawn funds to, the
   * new user signing key, or the null address for cancelling.
   * @param nonce uint256 The nonce to use.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @return The action ID, which will need to be prefixed, hashed and signed in
   * order to construct a valid signature.
   */
  function getCustomActionID(
    ActionType action,
    uint256 amount,
    address recipient,
    uint256 nonce,
    uint256 minimumActionGas
  ) external view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getCustomActionID(
      action, amount, recipient, nonce, minimumActionGas, _getDharmaSigningKey()
    );
  }

  /**
   * @notice Pure function for getting the current Dharma Smart Wallet version.
   * @return The current Dharma Smart Wallet version.
   */
  function getVersion() external pure returns (uint256 version) {
    version = _DHARMA_SMART_WALLET_VERSION;
  }

  function test() external pure returns (bool) {
    return true;
  }

  function testRevert() external pure returns (bool) {
    revert("This revert message should be visible.");
  }

  /**
   * @notice Internal function for setting a new user signing key. A
   * NewUserSigningKey event will also be emitted.
   * @param userSigningKey address The new user signing key to set on this smart
   * wallet.
   */
  function _setUserSigningKey(address userSigningKey) internal {
    // Ensure that a user signing key is set on this smart wallet.
    require(userSigningKey != address(0), "No user signing key provided.");

    _userSigningKey = userSigningKey;
    emit NewUserSigningKey(userSigningKey);
  }

  /**
   * @notice Internal function for incrementing the nonce.
   */
  function _incrementNonce() internal {
    _nonce++;
  }

  /**
   * @notice Internal function for setting the allowance of a given ERC20 asset
   * to the maximum value. This enables the corresponding cToken for the asset
   * to pull in tokens in order to make deposits.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   * @return True if the approval succeeded, otherwise false.
   */
  function _setFullApproval(AssetType asset) internal returns (bool ok) {
    // Get asset's underlying token address and corresponding cToken address.
    address token;
    address cToken;
    if (asset == AssetType.DAI) {
      token = address(_DAI);
      cToken = address(_CDAI);
    } else {
      token = address(_USDC);
      cToken = address(_CUSDC);
    }

    // Approve cToken contract to transfer underlying on behalf of this wallet.
    (ok, ) = token.call(abi.encodeWithSelector(
      // Note: since both cTokens have the same interface, just use cDAI's.
      _DAI.approve.selector, cToken, uint256(-1)
    ));

    // Emit a corresponding event if the approval failed.
    if (!ok) {
      if (asset == AssetType.DAI) {
        emit ExternalError(address(_DAI), "DAI contract reverted on approval.");
      } else {
        // Find out why USDC transfer reverted (it doesn't give revert reasons).
        _diagnoseAndEmitUSDCSpecificError(_USDC.approve.selector);
      }
    }
  }

  /**
   * @notice Internal function for depositing a given ERC20 asset and balance on
   * the corresponding cToken. No value is returned, as no additional steps need
   * to be conditionally performed after the deposit.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   * @param balance uint256 The amount of the asset to deposit. Note that an
   * attempt to deposit "dust" (i.e. very small amounts) may result in 0 cTokens
   * being minted, or in fewer cTokens being minted than is implied by the
   * current exchange rate (due to lack of sufficient precision on the tokens).
   */
  function _depositOnCompound(AssetType asset, uint256 balance) internal {
    // Only perform a deposit if the balance is non-zero. This could also take
    // into account the safe deposit threshold for each asset - for instance, a
    // deposit of 1 wei of Dai will mint 0 cDai, since cDai precision is lower.
    if (balance > 0) {
      // Get cToken address for the asset type.
      address cToken = asset == AssetType.DAI ? address(_CDAI) : address(_CUSDC);

      // Attempt to mint the balance on the cToken contract.
      (bool ok, bytes memory data) = cToken.call(abi.encodeWithSelector(
        // Note: since both cTokens have the same interface, just use cDAI's.
        _CDAI.mint.selector, balance
      ));

      // Log an external error if something went wrong with the attempt.
      _checkCompoundInteractionAndLogAnyErrors(
        asset, _CDAI.mint.selector, ok, data
      );
    }
  }

  /**
   * @notice Internal function for withdrawing a given ERC20 asset and balance
   * from the corresponding cToken. Note that the requested balance may not be
   * currently available on Compound, which will cause the withdrawal to fail.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   * @param balance uint256 The amount of the asset to withdraw, denominated in
   * the underlying token. Note that an attempt to withdraw "dust" (i.e. very
   * small amounts) may result in 0 underlying tokens being redeemed, or in
   * fewer tokens being redeemed than is implied by the current exchange rate
   * (due to lack of sufficient precision on the tokens).
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function _withdrawFromCompound(
    AssetType asset,
    uint256 balance
  ) internal returns (bool success) {
    // Get cToken address for the asset type.
    address cToken = asset == AssetType.DAI ? address(_CDAI) : address(_CUSDC);

    // Attempt to redeem the underlying balance from the cToken contract.
    (bool ok, bytes memory data) = cToken.call(abi.encodeWithSelector(
      // Note: since both cTokens have the same interface, just use cDAI's.
      _CDAI.redeemUnderlying.selector, balance
    ));

    // Log an external error if something went wrong with the attempt.
    success = _checkCompoundInteractionAndLogAnyErrors(
      asset, _CDAI.redeemUnderlying.selector, ok, data
    );
  }

  /**
   * @notice Internal function for validating supplied gas (if specified),
   * retrieving the signer's public key from the Dharma Key Registry, deriving
   * the action ID, validating the provided signature using the signer's key and
   * the action ID, and incrementing the nonce. This function serves as the
   * entrypoint for all protected "actions" on the smart wallet, and is the only
   * area where these functions should revert (other than due to out-of-gas
   * errors, which can be guarded against by supplying a minimum action gas
   * requirement).
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V0 include Cancel (0), SetUserSigningKey (1), DAIWithdrawal (4),
   * and USDCWithdrawal (5).
   * @param amount uint256 The amount to withdraw for Withdrawal actions, or 0
   * for other action types.
   * @param recipient address The account to transfer withdrawn funds to, the
   * new user signing key, or the null address for cancelling.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   */
  function _validateActionAndIncrementNonce(
    ActionType action,
    uint256 amount,
    address recipient,
    uint256 minimumActionGas,
    bytes memory dharmaSignature
  ) internal {
    // Ensure that the current gas exceeds the minimum required action gas.
    // This prevents griefing attacks where an attacker can invalidate a
    // signature without providing enough gas for the action to succeed. Also
    // note that some gas will be spent before this check is reached - supplying
    // ~30,000 additional gas should suffice when submitting transactions. To
    // skip this requirement, supply zero for the minimumActionGas argument.
    if (minimumActionGas != 0) {
      require(
        gasleft() >= minimumActionGas,
        "Invalid action - insufficient gas supplied by transaction submitter."
      );
    }

    // Get the Dharma signing key that will be used to verify the signature.
    address dharmaSigningKey = _getDharmaSigningKey();

    // Determine the actionID - this serves as the signature hash.
    bytes32 actionID = _getCustomActionID(
      action, amount, recipient, _nonce, minimumActionGas, dharmaSigningKey
    );

    // Validate Dharma signing key signature unless it is `msg.sender`.
    if (msg.sender != dharmaSigningKey) {
      require(
        dharmaSigningKey == actionID.toEthSignedMessageHash().recover(
          dharmaSignature
        ),
        "Invalid action - invalid Dharma signature."
      );
    }

    // Increment nonce in order to prevent reuse of signatures after the call.
    _incrementNonce();
  }

  /**
   * @notice Internal function for entering cDAI, cUSDC, and cETH markets. This
   * is performed now so that V0 smart wallets will not need to be reinitialized
   * in order to support using these assets as collateral when borrowing funds.
   */
  function _enterMarkets() internal {
    // Create input array with each cToken address on which to enter a market. 
    address[] memory marketsToEnter = new address[](3);
    marketsToEnter[0] = address(_CDAI);
    marketsToEnter[1] = address(_CUSDC);
    marketsToEnter[2] = address(0x4Ddc2D193948926D02f9B1fE9e1daa0718270ED5); // CEther

    // Attempt to enter each market by calling into the Comptroller contract.
    (bool ok, bytes memory data) = address(_COMPTROLLER).call(abi.encodeWithSelector(
      _COMPTROLLER.enterMarkets.selector, marketsToEnter
    ));

    // Log an external error if something went wrong with the attempt.
    if (ok) {
      uint256[] memory compoundErrors = abi.decode(data, (uint256[]));
      for (uint256 i = 0; i < compoundErrors.length; i++) {
        uint256 compoundError = compoundErrors[i];
        if (compoundError != _COMPOUND_SUCCESS) {
          emit ExternalError(
            address(_COMPTROLLER),
            string(
              abi.encodePacked(
                "Compound Comptroller contract returned error code ",
                uint8((compoundError / 10) + 48),
                uint8((compoundError % 10) + 48),
                " while attempting to call enterMarkets."
              )
            )
          );
        }
      }
    } else {
      // Decode the revert reason in the event one was returned.
      string memory revertReason = _decodeRevertReason(data);

      emit ExternalError(
        address(_COMPTROLLER),
        string(
          abi.encodePacked(
            "Compound Comptroller contract reverted on enterMarkets: ",
            revertReason
          )
        )
      );
    }
  }

  /**
   * @notice Internal function to determine whether a call to a given cToken
   * succeeded, and to emit a relevant ExternalError event if it failed. The
   * failure can be caused by a call that reverts, or by a call that does not
   * revert but returns a non-zero error code.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   * @param functionSelector bytes4 The function selector that was called on the
   * corresponding cToken of the asset type.
   * @param ok bool A boolean representing whether the call returned or
   * reverted.
   * @param data bytes The data provided by the returned or reverted call.
   * @return True if the interaction was successful, otherwise false. This will
   * be used to determine if subsequent steps in the action should be attempted
   * or not, specifically a transfer following a withdrawal.
   */
  function _checkCompoundInteractionAndLogAnyErrors(
    AssetType asset,
    bytes4 functionSelector,
    bool ok,
    bytes memory data
  ) internal returns (bool success) {
    // Log an external error if something went wrong with the attempt.
    if (ok) {
      uint256 compoundError = abi.decode(data, (uint256));
      if (compoundError != _COMPOUND_SUCCESS) {
        // Get called contract address, name of contract, and function name.
        (address account, string memory name, string memory functionName) = (
          _getCTokenDetails(asset, functionSelector)
        );

        emit ExternalError(
          account,
          string(
            abi.encodePacked(
              "Compound ",
              name,
              " contract returned error code ",
              uint8((compoundError / 10) + 48),
              uint8((compoundError % 10) + 48),
              " while attempting to call ",
              functionName,
              "."
            )
          )
        );
      } else {
        success = true;
      }
    } else {
      // Get called contract address, name of contract, and function name.
      (address account, string memory name, string memory functionName) = (
        _getCTokenDetails(asset, functionSelector)
      );

      // Decode the revert reason in the event one was returned.
      string memory revertReason = _decodeRevertReason(data);

      emit ExternalError(
        account,
        string(
          abi.encodePacked(
            "Compound ",
            name,
            " contract reverted while attempting to call ",
            functionName,
            ": ",
            revertReason
          )
        )
      );
    }
  }

  /**
   * @notice Internal function to diagnose the reason that a withdrawal attempt
   * failed and to emit a corresponding ExternalError event. Errors related to
   * the call to `redeemUnderlying` on the cToken are handled by
   * `_checkCompoundInteractionAndLogAnyErrors` - if the error did not originate
   * from that call, it could be caused by a call to `balanceOfUnderlying` (i.e.
   * when attempting a maximum withdrawal) or by the call to `transfer` on the
   * underlying token after the withdrawal has been completed.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   */
  function _diagnoseAndEmitErrorRelatedToWithdrawal(AssetType asset) internal {
    // Get called contract address and name of contract (no need for selector).
    (address cToken, string memory name, ) = _getCTokenDetails(
      asset, bytes4(0)
    );

    // Revert could be caused by cToken MathError or underlying transfer error.
    (bool check, ) = cToken.call(abi.encodeWithSelector(
      // Note: since both cTokens have the same interface, just use cDAI's.
      _CDAI.balanceOfUnderlying.selector, address(this)
    ));
    if (!check) {
      emit ExternalError(
        cToken,
        string(
          abi.encodePacked(
            name, " contract reverted on call to balanceOfUnderlying."
          )
        )
      );
    } else {
      if (asset == AssetType.DAI) {
        emit ExternalError(address(_DAI), "DAI contract reverted on transfer.");
      } else {
        // Find out why USDC transfer reverted (it doesn't give revert reasons).
        _diagnoseAndEmitUSDCSpecificError(_USDC.transfer.selector);
      }   
    }
  }

  /**
   * @notice Internal function to diagnose the reason that a call to the USDC
   * contract failed and to emit a corresponding ExternalError event. USDC can
   * blacklist accounts and pause the contract, which can both cause a transfer
   * or approval to fail.
   * @param functionSelector bytes4 The function selector that was called on the
   * USDC contract.
   */
  function _diagnoseAndEmitUSDCSpecificError(bytes4 functionSelector) internal {
    // Determine the name of the function that was called on USDC.
    string memory functionName;
    if (functionSelector == _USDC.transfer.selector) {
      functionName = "transfer";
    } else {
      functionName = "approve";
    }

    // Find out why USDC transfer reverted (it doesn't give revert reasons).
    if (_USDC_NAUGHTY.isBlacklisted(address(this))) {
      emit ExternalError(
        address(_USDC),
        string(
          abi.encodePacked(
            functionName, " failed - USDC has blacklisted this user."
          )
        )
      );
    } else { // Note: `else if` breaks coverage.
      if (_USDC_NAUGHTY.paused()) {
        emit ExternalError(
          address(_USDC),
          string(
            abi.encodePacked(
              functionName, " failed - USDC contract is currently paused."
            )
          )
        );
      } else {
        emit ExternalError(
          address(_USDC),
          string(
            abi.encodePacked(
              "USDC contract reverted on ", functionName, "."
            )
          )
        );
      }
    }
  }

  /**
   * @notice Internal function to ensure that protected functions can only be
   * called from this contract and that they have the appropriate context set.
   * The self-call context is then cleared. It is used as an additional guard
   * against reentrancy, especially once generic actions are supported by the
   * smart wallet in future versions.
   * @param selfCallContext bytes4 The expected self-call context, equal to the
   * function selector of the approved calling function.
   */
  function _enforceSelfCallFrom(bytes4 selfCallContext) internal {
    // Ensure caller is this contract and self-call context is correctly set.
    require(
      msg.sender == address(this) &&
      _selfCallContext == selfCallContext,
      "External accounts or unapproved internal functions cannot call this."
    );

    // Clear the self-call context.
    delete _selfCallContext;
  }

  /**
   * @notice Internal view function to get the Dharma signing key for the smart
   * wallet from the Dharma Key Registry. Note that, for V0, this is actually
   * the *only* key used, as the primary user signing key will first need to be
   * provided for each smart wallet. This version uses the global key from the
   * Dharma Key Registry; to support the use of user-specific keys with a global
   * fallback, instead call `getKey()` on the registry.
   * @return The address of the Dharma signing key, or public key corresponding
   * to the secondary signer.
   */
  function _getDharmaSigningKey() internal view returns (
    address dharmaSigningKey
  ) {
    dharmaSigningKey = _DHARMA_KEY_REGISTRY.getGlobalKey();
  }

  /**
   * @notice Internal view function that, given an action type and arguments,
   * will return the action ID or message hash that will need to be prefixed
   * (according to EIP-191 0x45), hashed, and signed by the key designated by
   * the Dharma Key Registry in order to construct a valid signature for the
   * corresponding action. The current nonce will be supplied to this function
   * when reconstructing an action ID during protected function execution based
   * on the supplied parameters.
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V0 include Cancel (0), SetUserSigningKey (1), DAIWithdrawal (4),
   * and USDCWithdrawal (5).
   * @param amount uint256 The amount to withdraw for Withdrawal actions, or 0
   * for other action types.
   * @param recipient address The account to transfer withdrawn funds to, the
   * new user signing key, or the null address for cancelling.
   * @param nonce uint256 The nonce to use.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param dharmaSigningKey address The address of the secondary key, or public
   * key corresponding to the secondary signer.
   * @return The action ID, which will need to be prefixed, hashed and signed in
   * order to construct a valid signature.
   */
  function _getCustomActionID(
    ActionType action,
    uint256 amount,
    address recipient,
    uint256 nonce,
    uint256 minimumActionGas,
    address dharmaSigningKey
  ) internal view returns (bytes32 actionID) {
    // The actionID is constructed according to EIP-191-0x45 to prevent replays.
    actionID = keccak256(
      abi.encodePacked(
        address(this),
        _DHARMA_SMART_WALLET_VERSION,
        _userSigningKey,
        dharmaSigningKey,
        nonce,
        minimumActionGas,
        action,
        amount,
        recipient
      )
    );
  }

  /**
   * @notice Internal pure function to get the cToken address, it's name, and
   * the name of the called function, based on a supplied asset type and
   * function selector. It is used to help construct ExternalError events.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   * @param functionSelector bytes4 The function selector that was called on the
   * corresponding cToken of the asset type.
   * @return The cToken address, it's name, and the name of the called function.
   */
  function _getCTokenDetails(
    AssetType asset,
    bytes4 functionSelector
  ) internal pure returns (
    address account,
    string memory name,
    string memory functionName
  ) {
    if (asset == AssetType.DAI) {
      account = address(_CDAI);
      name = "cDAI";
    } else {
      account = address(_CUSDC);
      name = "cUSDC";
    }

    // Note: since both cTokens have the same interface, just use cDAI's.
    if (functionSelector == _CDAI.mint.selector) {
      functionName = "mint";
    } else {
      functionName = "redeemUnderlying";
    }
  }

  /**
   * @notice Internal pure function to decode revert reasons. The revert reason
   * prefix is removed and the remaining string argument is decoded.
   * @param revertData bytes The raw data supplied alongside the revert.
   * @return The decoded revert reason string.
   */
  function _decodeRevertReason(
    bytes memory revertData
  ) internal pure returns (string memory revertReason) {
    // Solidity prefixes revert reason with 0x08c379a0 -> Error(string) selector
    if (
      revertData.length > 68 && // prefix (4) + position (32) + length (32)
      revertData[0] == byte(0x08) &&
      revertData[1] == byte(0xc3) &&
      revertData[2] == byte(0x79) &&
      revertData[3] == byte(0xa0)
    ) {
      // Get the revert reason without the prefix from the revert data.
      bytes memory revertReasonBytes = new bytes(revertData.length - 4);
      for (uint256 i = 4; i < revertData.length; i++) {
        revertReasonBytes[i - 4] = revertData[i];
      }

      // Decode the resultant revert reason as a string.
      revertReason = abi.decode(revertReasonBytes, (string));
    } else {
      // Simply return the default, with no revert reason.
      revertReason = "(no revert reason)";
    }
  }
}

pragma solidity 0.5.11; // optimization runs: 200, evm version: petersburg
// WARNING - `executeActionWithAtomicBatchCalls` has a `bytes[]` argument that
// requires ABIEncoderV2. Exercise caution when calling that specific function.
pragma experimental ABIEncoderV2;

import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "../../../interfaces/DharmaSmartWalletImplementationV0Interface.sol";
import "../../../interfaces/DharmaSmartWalletImplementationV1Interface.sol";
import "../../../interfaces/CTokenInterface.sol";
import "../../../interfaces/USDCV1Interface.sol";
import "../../../interfaces/ComptrollerInterface.sol";
import "../../../interfaces/DharmaKeyRegistryInterface.sol";
import "../../../interfaces/ERC1271.sol";


/**
 * @title DharmaSmartWalletImplementationV1
 * @author 0age
 * @notice The V1 implementation for the Dharma smart wallet is a joint-custody,
 * meta-transaction-enabled wallet with helper functions to facilitate lending
 * funds using CompoundV2. It also contains methods to support account recovery
 * and generic actions, including in an atomic batch. The smart wallet instances
 * utilizing this implementation are deployed through the Dharma Smart Wallet
 * Factory via `CREATE2`, which allows for their address to be known ahead of
 * time, and any Dai, USDC, or Ether that has already been sent into that
 * address will automatically be deposited into Compound upon deployment of the
 * new smart wallet instance.
 */
contract DharmaSmartWalletImplementationV1 is
  DharmaSmartWalletImplementationV0Interface,
  DharmaSmartWalletImplementationV1Interface {
  using Address for address;
  using ECDSA for bytes32;
  // WARNING: DO NOT REMOVE OR REORDER STORAGE WHEN WRITING NEW IMPLEMENTATIONS!

  // The user signing key associated with this account is in storage slot 0.
  // It is the core differentiator when it comes to the account in question.
  address private _userSigningKey;

  // The nonce associated with this account is in storage slot 1. Every time a
  // signature is submitted, it must have the appropriate nonce, and once it has
  // been accepted the nonce will be incremented.
  uint256 private _nonce;

  // The self-call context flag is in storage slot 2. Some protected functions
  // may only be called externally from calls originating from other methods on
  // this contract, which enables appropriate exception handling on reverts.
  // Any storage should only be set immediately preceding a self-call and should
  // be cleared upon entering the protected function being called.
  bytes4 internal _selfCallContext;

  // END STORAGE DECLARATIONS - DO NOT REMOVE OR REORDER STORAGE ABOVE HERE!

  // The smart wallet version will be used when constructing valid signatures.
  uint256 internal constant _DHARMA_SMART_WALLET_VERSION = 1;

  // The Dharma Key Registry holds a public key for verifying meta-transactions.
  DharmaKeyRegistryInterface internal constant _DHARMA_KEY_REGISTRY = (
    DharmaKeyRegistryInterface(0x000000005D7065eB9716a410070Ee62d51092C98)
  );

  // Account recovery is facilitated using a hard-coded recovery manager,
  // controlled by Dharma and implementing appropriate timelocks.
  address internal constant _ACCOUNT_RECOVERY_MANAGER = address(
    0x00000000d750176e38660203C678D88eE7e28d36
  );

  // This contract interfaces with Dai, USDC, and related CompoundV2 contracts.
  CTokenInterface internal constant _CDAI = CTokenInterface(
    0xF5DCe57282A584D2746FaF1593d3121Fcac444dC // mainnet
  );

  CTokenInterface internal constant _CUSDC = CTokenInterface(
    0x39AA39c021dfbaE8faC545936693aC917d5E7563 // mainnet
  );

  IERC20 internal constant _DAI = IERC20(
    0x89d24A6b4CcB1B6fAA2625fE562bDD9a23260359 // mainnet
  );

  IERC20 internal constant _USDC = IERC20(
    0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48 // mainnet
  );

  USDCV1Interface internal constant _USDC_NAUGHTY = USDCV1Interface(
    0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48 // mainnet
  );

  ComptrollerInterface internal constant _COMPTROLLER = ComptrollerInterface(
    0x3d9819210A31b4961b30EF54bE2aeD79B9c9Cd3B // mainnet
  );

  // Compound returns a value of 0 to indicate success, or lack of an error.
  uint256 internal constant _COMPOUND_SUCCESS = 0;

  // ERC-1271 must return this magic value when `isValidSignature` is called.
  bytes4 internal constant _ERC_1271_MAGIC_VALUE = bytes4(0x20c13b0b);

  /**
   * @notice In initializer, set up user signing key, set approval on the cDAI
   * and cUSDC contracts, deposit any Dai, USDC, and ETH already at the address
   * to Compound, and enter markets for cDAI, cUSDC, and cETH. Note that this
   * initializer is only callable while the smart wallet instance is still in
   * the contract creation phase.
   * @param userSigningKey address The initial user signing key for the smart
   * wallet.
   */
  function initialize(address userSigningKey) external {
    // Ensure that this function is only callable during contract construction.
    assembly { if extcodesize(address) { revert(0, 0) } }

    // Set up the user's signing key and emit a corresponding event.
    _setUserSigningKey(userSigningKey);

    // Approve the cDAI contract to transfer Dai on behalf of this contract.
    if (_setFullApproval(AssetType.DAI)) {
      // Get the current Dai balance on this contract.
      uint256 daiBalance = _DAI.balanceOf(address(this));

      // Try to deposit any dai balance on Compound.
      _depositOnCompound(AssetType.DAI, daiBalance);
    }

    // Approve the cUSDC contract to transfer USDC on behalf of this contract.
    if (_setFullApproval(AssetType.USDC)) {
      // Get the current USDC balance on this contract.
      uint256 usdcBalance = _USDC.balanceOf(address(this));

      // Try to deposit any USDC balance on Compound.
      _depositOnCompound(AssetType.USDC, usdcBalance);
    }

    // Enter DAI + USDC + ETH markets now to avoid a need to reinitialize later.
    _enterMarkets();
  }

  /**
   * @notice Deposit all Dai and USDC currently residing at this address to
   * Compound. Note that "repay" is not currently implemented, but the function
   * is still named "repayAndDeposit" so that infrastructure around calling this
   * function will not need to be altered for a future smart wallet version. If
   * some step of this function fails, the function itself will still succeed,
   * but an ExternalError with information on what went wrong will be emitted.
   */
  function repayAndDeposit() external {
    // Get the current Dai balance on this contract.
    uint256 daiBalance = _DAI.balanceOf(address(this));

    // Deposit any available Dai.
    _depositOnCompound(AssetType.DAI, daiBalance);

    // Get the current USDC balance on this contract.
    uint256 usdcBalance = _USDC.balanceOf(address(this));

    // If there is any USDC balance, check for adequate approval for cUSDC.
    if (usdcBalance > 0) {
      uint256 usdcAllowance = _USDC.allowance(address(this), address(_CUSDC));
      // If allowance is insufficient, try to set it before depositing.
      if (usdcAllowance < usdcBalance) {
        if (_setFullApproval(AssetType.USDC)) {
          // Deposit any available USDC.
          _depositOnCompound(AssetType.USDC, usdcBalance);
        }
      // Otherwise, go ahead and try the deposit.
      } else {
        // Deposit any available USDC.
        _depositOnCompound(AssetType.USDC, usdcBalance);
      }
    }
  }

  /**
   * @notice Withdraw Dai to a provided recipient address by redeeming the
   * underlying Dai from the cDAI contract and transferring it to the recipient.
   * All Dai in Compound and in the smart wallet itself can be withdrawn by
   * providing an amount of uint256(-1) or 0xfff...fff. This function can be
   * called directly by the account set as the global key on the Dharma Key
   * Registry, or by any relayer that provides a signed message from the same
   * keyholder. The nonce used for the signature must match the current nonce on
   * the smart wallet, and gas supplied to the call must exceed the specified
   * minimum action gas, plus the gas that will be spent before the gas check is
   * reached - usually somewhere around 25,000 gas. If the withdrawal fails, an
   * ExternalError with additional details on what went wrong will be emitted.
   * Note that some dust may still be left over, even in the event of a max
   * withdrawal, due to the fact that Dai has a higher precision than cDAI. Also
   * note that the withdrawal will fail in the event that Compound does not have
   * sufficient Dai available to withdraw.
   * @param amount uint256 The amount of Dai to withdraw.
   * @param recipient address The account to transfer the withdrawn Dai to.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function withdrawDai(
    uint256 amount,
    address recipient,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok) {
    // Ensure caller and/or supplied signatures are valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.DAIWithdrawal,
      abi.encode(amount, recipient),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Set the self-call context so we can call _withdrawDaiAtomic.
    _selfCallContext = this.withdrawDai.selector;

    // Make the atomic self-call - if redeemUnderlying fails on cDAI, it will
    // succeed but nothing will happen except firing an ExternalError event. If
    // the second part of the self-call (the Dai transfer) fails, it will revert
    // and roll back the first part of the call, and we'll fire an ExternalError
    // event after returning from the failed call.
    bytes memory returnData;
    (ok, returnData) = address(this).call(abi.encodeWithSelector(
      this._withdrawDaiAtomic.selector, amount, recipient
    ));

    // If the atomic call failed, diagnose the reason and emit an event.
    if (!ok) {
      // This revert could be caused by cDai MathError or Dai transfer error.
      _diagnoseAndEmitErrorRelatedToWithdrawal(AssetType.DAI);
    } else {
      // Set ok to false if the call succeeded but the withdrawal failed.
      ok = abi.decode(returnData, (bool));
    }
  }

  /**
   * @notice Protected function that can only be called from `withdrawDai` on
   * this contract. It will attempt to withdraw the supplied amount of Dai, or
   * the maximum amount if specified using `uint256(-1)`, to the supplied
   * recipient address by redeeming the underlying Dai from the cDAI contract
   * and transferring it to the recipient. An ExternalError will be emitted and
   * the transfer will be skipped if the call to `redeemUnderlying` fails, and
   * any revert will be caught by `withdrawDai` and diagnosed in order to emit
   * an appropriate ExternalError as well.
   * @param amount uint256 The amount of Dai to withdraw.
   * @param recipient address The account to transfer the withdrawn Dai to.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function _withdrawDaiAtomic(
    uint256 amount,
    address recipient
  ) external returns (bool success) {
    // Ensure caller is this contract and self-call context is correctly set.
    _enforceSelfCallFrom(this.withdrawDai.selector);

    // If amount = 0xfff...fff, withdraw the maximum amount possible.
    bool maxWithdraw = (amount == uint256(-1));
    uint256 redeemUnderlyingAmount;
    if (maxWithdraw) {
      redeemUnderlyingAmount = _CDAI.balanceOfUnderlying(address(this));
    } else {
      redeemUnderlyingAmount = amount;
    }

    // Attempt to withdraw specified Dai amount from Compound before proceeding.
    if (_withdrawFromCompound(AssetType.DAI, redeemUnderlyingAmount)) {
      // At this point dai transfer *should* never fail - wrap it just in case.
      if (maxWithdraw) {
        require(_DAI.transfer(recipient, _DAI.balanceOf(address(this))));
      } else {
        require(_DAI.transfer(recipient, amount));
      }
      success = true;
    }
  }

  /**
   * @notice Withdraw USDC to a provided recipient address by redeeming the
   * underlying USDC from the cUSDC contract and transferring it to recipient.
   * All USDC in Compound and in the smart wallet itself can be withdrawn by
   * providing an amount of uint256(-1) or 0xfff...fff. This function can be
   * called directly by the account set as the global key on the Dharma Key
   * Registry, or by any relayer that provides a signed message from the same
   * keyholder. The nonce used for the signature must match the current nonce on
   * the smart wallet, and gas supplied to the call must exceed the specified
   * minimum action gas, plus the gas that will be spent before the gas check is
   * reached - usually somewhere around 25,000 gas. If the withdrawal fails, an
   * ExternalError with additional details on what went wrong will be emitted.
   * Note that the USDC contract can be paused and also allows for blacklisting
   * accounts - either of these possibilities may cause a withdrawal to fail. In
   * addition, Compound may not have sufficient USDC available at the time to
   * withdraw.
   * @param amount uint256 The amount of USDC to withdraw.
   * @param recipient address The account to transfer the withdrawn USDC to.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function withdrawUSDC(
    uint256 amount,
    address recipient,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok) {
    // Ensure caller and/or supplied signatures are valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.USDCWithdrawal,
      abi.encode(amount, recipient),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Set the self-call context so we can call _withdrawUSDCAtomic.
    _selfCallContext = this.withdrawUSDC.selector;

    // Make the atomic self-call - if redeemUnderlying fails on cUSDC, it will
    // succeed but nothing will happen except firing an ExternalError event. If
    // the second part of the self-call (USDC transfer) fails, it will revert
    // and roll back the first part of the call, and we'll fire an ExternalError
    // event after returning from the failed call.
    bytes memory returnData;
    (ok, returnData) = address(this).call(abi.encodeWithSelector(
      this._withdrawUSDCAtomic.selector, amount, recipient
    ));
    if (!ok) {
      // This revert could be caused by cUSDC MathError or USDC transfer error.
      _diagnoseAndEmitErrorRelatedToWithdrawal(AssetType.USDC);
    } else {
      // Ensure that ok == false in the event the withdrawal failed.
      ok = abi.decode(returnData, (bool));
    }
  }

  /**
   * @notice Protected function that can only be called from `withdrawUSDC` on
   * this contract. It will attempt to withdraw the supplied amount of USDC, or
   * the maximum amount if specified using `uint256(-1)`, to the supplied
   * recipient address by redeeming the underlying USDC from the cUSDC contract
   * and transferring it to the recipient. An ExternalError will be emitted and
   * the transfer will be skipped if the call to `redeemUnderlying` fails, and
   * any revert will be caught by `withdrawUSDC` and diagnosed in order to emit
   * an appropriate ExternalError as well.
   * @param amount uint256 The amount of USDC to withdraw.
   * @param recipient address The account to transfer the withdrawn USDC to.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function _withdrawUSDCAtomic(
    uint256 amount,
    address recipient
  ) external returns (bool success) {
    // Ensure caller is this contract and self-call context is correctly set.
    _enforceSelfCallFrom(this.withdrawUSDC.selector);

    // If amount = 0xfff...fff, withdraw the maximum amount possible.
    bool maxWithdraw = (amount == uint256(-1));
    uint256 redeemUnderlyingAmount;
    if (maxWithdraw) {
      redeemUnderlyingAmount = _CUSDC.balanceOfUnderlying(address(this));
    } else {
      redeemUnderlyingAmount = amount;
    }

    // Try to withdraw specified USDC amount from Compound before proceeding.
    if (_withdrawFromCompound(AssetType.USDC, redeemUnderlyingAmount)) {
      // Ensure that the USDC transfer does not fail.
      if (maxWithdraw) {
        require(_USDC.transfer(recipient, _USDC.balanceOf(address(this))));
      } else {
        require(_USDC.transfer(recipient, amount));
      }
      success = true;
    }
  }

  /**
   * @notice Withdraw Ether to a provided recipient address by transferring it
   * to a recipient. This is only intended to be utilized on V1 as a mechanism
   * for recovering Ether from this contract.
   * @param amount uint256 The amount of Ether to withdraw.
   * @param recipient address The account to transfer the Ether to.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return True if the transfer succeeded, otherwise false.
   */
  function withdrawEther(
    uint256 amount,
    address payable recipient,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok) {
    // Ensure caller and/or supplied signatures are valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.ETHWithdrawal,
      abi.encode(amount, recipient),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Attempt to perform the transfer and emit an event if it fails.
    (ok, ) = recipient.call.gas(2300).value(amount)("");
    if (!ok) {
      emit ExternalError(address(this), "Ether transfer was unsuccessful.");
    }
  }

  /**
   * @notice Allow a signatory to increment the nonce at any point. The current
   * nonce needs to be provided as an argument to the a signature so as not to
   * enable griefing attacks. All arguments can be omitted if called directly.
   * No value is returned from this function - it will either succeed or revert.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param signature bytes A signature that resolves to either the public key
   * set for this account in storage slot zero, `_userSigningKey`, or the public
   * key returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   */  
  function cancel(
    uint256 minimumActionGas,
    bytes calldata signature
  ) external {
    // Ensure the caller or the supplied signature is valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.Cancel,
      abi.encode(),
      minimumActionGas,
      signature,
      signature
    );
  }

  /**
   * @notice Perform a generic call to another contract. Note that accounts with
   * no code may not be specified, nor may the smart wallet itself. In order to
   * increment the nonce and invalidate the signature, a call to this function
   * with a valid target, signatutes, and gas will always succeed. To determine
   * whether the call made as part of the action was successful or not, either
   * the return values or the `CallSuccess` or `CallFailure` event can be used.
   * @param to address The contract to call.
   * @param data bytes The calldata to provide when making the call.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return A boolean signifying the status of the call, as well as any data
   * returned from the call.
   */
  function executeAction(
    address to,
    bytes calldata data,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok, bytes memory returnData) {
    // Ensure that the `to` address is a contract and is not this contract.
    _ensureValidGenericCallTarget(to);

    // Ensure caller and/or supplied signatures are valid and increment nonce.
    (bytes32 actionID, uint256 nonce) = _validateActionAndIncrementNonce(
      ActionType.Generic,
      abi.encode(to, data),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Note: from this point on, there are no reverts (apart from out-of-gas or
    // call-depth-exceeded) originating from this action. However, the call
    // itself may revert, in which case the function will return `false`, along
    // with the revert reason encoded as bytes, and fire an CallFailure event.

    // Perform the action via low-level call and set return values using result.
    (ok, returnData) = to.call(data);

    // Emit a CallSuccess or CallFailure event based on the outcome of the call.
    if (ok) {
      // Note: while the call succeeded, the action may still have "failed"
      // (for example, successful calls to Compound can still return an error).
      emit CallSuccess(actionID, false, nonce, to, data, returnData);
    } else {
      // Note: while the call failed, the nonce will still be incremented, which
      // will invalidate all supplied signatures.
      emit CallFailure(actionID, nonce, to, data, string(returnData));
    }
  }

  /**
   * @notice Allow signatory to set a new user signing key. The current nonce
   * needs to be provided as an argument to the a signature so as not to enable
   * griefing attacks. No value is returned from this function - it will either
   * succeed or revert.
   * @param userSigningKey address The new user signing key to set on this smart
   * wallet.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   */
  function setUserSigningKey(
    address userSigningKey,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external {
    // Ensure caller and/or supplied signatures are valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.SetUserSigningKey,
      abi.encode(userSigningKey),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Set new user signing key on smart wallet and emit a corresponding event.
    _setUserSigningKey(userSigningKey);
  }

  // Allow the account recovery manager to change the user signing key.
  function recover(address newUserSigningKey) external {
    require(
      msg.sender == _ACCOUNT_RECOVERY_MANAGER,
      "Only the account recovery manager may call this function."
    );

    // Set up the user's new dharma key and emit a corresponding event.
    _setUserSigningKey(newUserSigningKey);
  }

  /**
   * @notice Retrieve the Dai and USDC balances held by the smart wallet, both
   * directly and held in Compound. This is not a view function since Compound
   * will calculate accrued interest as part of the underlying balance checks,
   * but can still be called from an off-chain source as though it were a view
   * function.
   * @return The Dai balance, the USDC balance, the underlying Dai balance of
   * the cDAI balance, and the underlying USDC balance of the cUSDC balance.
   */
  function getBalances() external returns (
    uint256 daiBalance,
    uint256 usdcBalance,
    uint256 etherBalance, // always returns 0
    uint256 cDaiUnderlyingDaiBalance,
    uint256 cUsdcUnderlyingUsdcBalance,
    uint256 cEtherUnderlyingEtherBalance // always returns 0
  ) {
    daiBalance = _DAI.balanceOf(address(this));
    usdcBalance = _USDC.balanceOf(address(this));
    cDaiUnderlyingDaiBalance = _CDAI.balanceOfUnderlying(address(this));
    cUsdcUnderlyingUsdcBalance = _CUSDC.balanceOfUnderlying(address(this));
  }

  /**
   * @notice View function for getting the current user signing key for the
   * smart wallet.
   * @return The current user signing key.
   */
  function getUserSigningKey() external view returns (address userSigningKey) {
    userSigningKey = _userSigningKey;
  }

  /**
   * @notice View function for getting the current nonce of the smart wallet.
   * This nonce is incremented whenever an action is taken that requires a
   * signature and/or a specific caller.
   * @return The current nonce.
   */
  function getNonce() external view returns (uint256 nonce) {
    nonce = _nonce;
  }

  /**
   * @notice View function that, given an action type and arguments, will return
   * the action ID or message hash that will need to be prefixed (according to
   * EIP-191 0x45), hashed, and signed by the key designated by the Dharma Key
   * Registry in order to construct a valid signature for the corresponding
   * action. The current nonce will be used, which means that it will only be
   * valid for the next action taken.
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V1 include Cancel (0), SetUserSigningKey (1), Generic (2), 
   * GenericAtomicBatch (3), DAIWithdrawal (4), USDCWithdrawal (5), and
   * ETHWithdrawal (6).
   * @param amount uint256 The amount to withdraw for Withdrawal actions, or 0
   * for other action types.
   * @param recipient address The account to transfer withdrawn funds to, the
   * new user signing key, or the null address for cancelling.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @return The action ID, which will need to be prefixed, hashed and signed in
   * order to construct a valid signature.
   */
  function getNextCustomActionID(
    ActionType action,
    uint256 amount,
    address recipient,
    uint256 minimumActionGas
  ) external view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getActionID(
      action,
      abi.encode(amount, recipient),
      _nonce,
      minimumActionGas,
      _userSigningKey,
      _getDharmaSigningKey()
    );
  }

  /**
   * @notice View function that, given an action type and arguments, will return
   * the action ID or message hash that will need to be prefixed (according to
   * EIP-191 0x45), hashed, and signed by the key designated by the Dharma Key
   * Registry in order to construct a valid signature for the corresponding
   * action. Any nonce value may be supplied, which enables constructing valid
   * message hashes for multiple future actions ahead of time.
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V1 include Cancel (0), SetUserSigningKey (1), Generic (2), 
   * GenericAtomicBatch (3), DAIWithdrawal (4), USDCWithdrawal (5), and
   * ETHWithdrawal (6).
   * @param amount uint256 The amount to withdraw for Withdrawal actions, or 0
   * for other action types.
   * @param recipient address The account to transfer withdrawn funds to, the
   * new user signing key, or the null address for cancelling.
   * @param nonce uint256 The nonce to use.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @return The action ID, which will need to be prefixed, hashed and signed in
   * order to construct a valid signature.
   */
  function getCustomActionID(
    ActionType action,
    uint256 amount,
    address recipient,
    uint256 nonce,
    uint256 minimumActionGas
  ) external view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getActionID(
      action,
      abi.encode(amount, recipient),
      nonce,
      minimumActionGas,
      _userSigningKey,
      _getDharmaSigningKey()
    );
  }

  function getNextGenericActionID(
    address to,
    bytes calldata data,
    uint256 minimumActionGas
  ) external view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getActionID(
      ActionType.Generic,
      abi.encode(to, data),
      _nonce,
      minimumActionGas,
      _userSigningKey,
      _getDharmaSigningKey()
    );
  }

  function getGenericActionID(
    address to,
    bytes calldata data,
    uint256 nonce,
    uint256 minimumActionGas
  ) external view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getActionID(
      ActionType.Generic,
      abi.encode(to, data),
      nonce,
      minimumActionGas,
      _userSigningKey,
      _getDharmaSigningKey()
    );
  }

  /**
   * @notice Pure function for getting the current Dharma Smart Wallet version.
   * @return The current Dharma Smart Wallet version.
   */
  function getVersion() external pure returns (uint256 version) {
    version = _DHARMA_SMART_WALLET_VERSION;
  }

  // Note: this must currently be implemented as a public function (instead of
  // as an external one) due to an ABIEncoderV2 `UnimplementedFeatureError`.
  // Also note that the returned `ok` boolean only signifies that a call was
  // successfully completed during execution - the call will be rolled back
  // unless EVERY call succeeded and therefore the whole `ok` array is true.
  function executeActionWithAtomicBatchCalls(
    Call[] memory calls,
    uint256 minimumActionGas,
    bytes memory userSignature,
    bytes memory dharmaSignature
  ) public returns (bool[] memory ok, bytes[] memory returnData) {
    // Ensure that each `to` address is a contract and is not this contract.
    for (uint256 i = 0; i < calls.length; i++) {
      _ensureValidGenericCallTarget(calls[i].to);
    }

    // Ensure caller and/or supplied signatures are valid and increment nonce.
    (bytes32 actionID, uint256 nonce) = _validateActionAndIncrementNonce(
      ActionType.GenericAtomicBatch,
      abi.encode(calls),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Note: from this point on, there are no reverts (apart from out-of-gas or
    // call-depth-exceeded) originating from this contract. However, one of the
    // calls may revert, in which case the function will return `false`, along
    // with the revert reason encoded as bytes, and fire an CallFailure event.

    // Specify length of returned values in order to work with them in memory.
    ok = new bool[](calls.length);
    returnData = new bytes[](calls.length);

    // Set self-call context to call _executeActionWithAtomicBatchCallsAtomic.
    _selfCallContext = this.executeActionWithAtomicBatchCalls.selector;

    // Make the atomic self-call - if any call fails, calls that preceded it
    // will be rolled back and calls that follow it will not be made.
    (bool externalOk, bytes memory rawCallResults) = address(this).call(
      abi.encodeWithSelector(
        this._executeActionWithAtomicBatchCallsAtomic.selector, calls
      )
    );

    // Parse data returned from self-call into each call result and store / log.
    CallReturn[] memory callResults = abi.decode(rawCallResults, (CallReturn[]));
    for (uint256 i = 0; i < callResults.length; i++) {
      Call memory currentCall = calls[i];

      // Set the status and the return data / revert reason from the call.
      ok[i] = callResults[i].ok;
      returnData[i] = callResults[i].returnData;

      // Emit CallSuccess or CallFailure event based on the outcome of the call.
      if (callResults[i].ok) {
        // Note: while the call succeeded, the action may still have "failed"
        // (i.e. a successful calls to Compound can still return an error).
        emit CallSuccess(
          actionID,
          !externalOk, // if another call failed this will have been rolled back
          nonce,
          currentCall.to,
          currentCall.data,
          callResults[i].returnData
        );
      } else {
        // Note: while the call failed, the nonce will still be incremented,
        // which will invalidate all supplied signatures.
        emit CallFailure(
          actionID,
          nonce,
          currentCall.to,
          currentCall.data,
          string(callResults[i].returnData)
        );

        // exit early - any calls after the first failed call will not execute.
        break;
      }
    }
  }

  // Note: this must currently be implemented as a public function (instead of
  // as an external one) due to an ABIEncoderV2 `UnimplementedFeatureError`
  function _executeActionWithAtomicBatchCallsAtomic(
    Call[] memory calls
  ) public returns (CallReturn[] memory callResults) {
    // Ensure caller is this contract and self-call context is correctly set.
    _enforceSelfCallFrom(this.executeActionWithAtomicBatchCalls.selector);

    bool rollBack = false;
    callResults = new CallReturn[](calls.length);

    for (uint256 i = 0; i < calls.length; i++) {
      // Perform low-level call and set return values using result.
      (bool ok, bytes memory returnData) = calls[i].to.call(calls[i].data);
      callResults[i] = CallReturn({ok: ok, returnData: returnData});
      if (!ok) {
        // exit early - any calls after the first failed call will not execute.
        rollBack = true;
        break;
      }
    }

    if (rollBack) {
      // wrap in length encoding and revert (provide data instead of a string)
      bytes memory callResultsBytes = abi.encode(callResults);
      assembly { revert(add(32, callResultsBytes), mload(callResultsBytes)) }
    }
  }

  // cannot be implemented as an external function: `UnimplementedFeatureError`
  function getNextGenericAtomicBatchActionID(
    Call[] memory calls,
    uint256 minimumActionGas
  ) public view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getActionID(
      ActionType.GenericAtomicBatch,
      abi.encode(calls),
      _nonce,
      minimumActionGas,
      _userSigningKey,
      _getDharmaSigningKey()
    );
  }

  // cannot be implemented as an external function: `UnimplementedFeatureError`
  function getGenericAtomicBatchActionID(
    Call[] memory calls,
    uint256 nonce,
    uint256 minimumActionGas
  ) public view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getActionID(
      ActionType.GenericAtomicBatch,
      abi.encode(calls),
      nonce,
      minimumActionGas,
      _userSigningKey,
      _getDharmaSigningKey()
    );
  }

  /**
   * @notice Internal function for setting a new user signing key. A
   * NewUserSigningKey event will also be emitted.
   * @param userSigningKey address The new user signing key to set on this smart
   * wallet.
   */
  function _setUserSigningKey(address userSigningKey) internal {
    // Ensure that a user signing key is set on this smart wallet.
    require(userSigningKey != address(0), "No user signing key provided.");

    _userSigningKey = userSigningKey;
    emit NewUserSigningKey(userSigningKey);
  }

  /**
   * @notice Internal function for incrementing the nonce.
   */
  function _incrementNonce() internal {
    _nonce++;
  }

  /**
   * @notice Internal function for setting the allowance of a given ERC20 asset
   * to the maximum value. This enables the corresponding cToken for the asset
   * to pull in tokens in order to make deposits.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   * @return True if the approval succeeded, otherwise false.
   */
  function _setFullApproval(AssetType asset) internal returns (bool ok) {
    // Get asset's underlying token address and corresponding cToken address.
    address token;
    address cToken;
    if (asset == AssetType.DAI) {
      token = address(_DAI);
      cToken = address(_CDAI);
    } else {
      token = address(_USDC);
      cToken = address(_CUSDC);
    }

    // Approve cToken contract to transfer underlying on behalf of this wallet.
    (ok, ) = token.call(abi.encodeWithSelector(
      // Note: since both cTokens have the same interface, just use cDAI's.
      _DAI.approve.selector, cToken, uint256(-1)
    ));

    // Emit a corresponding event if the approval failed.
    if (!ok) {
      if (asset == AssetType.DAI) {
        emit ExternalError(address(_DAI), "DAI contract reverted on approval.");
      } else {
        // Find out why USDC transfer reverted (it doesn't give revert reasons).
        _diagnoseAndEmitUSDCSpecificError(_USDC.approve.selector);
      }
    }
  }

  /**
   * @notice Internal function for depositing a given ERC20 asset and balance on
   * the corresponding cToken. No value is returned, as no additional steps need
   * to be conditionally performed after the deposit.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   * @param balance uint256 The amount of the asset to deposit. Note that an
   * attempt to deposit "dust" (i.e. very small amounts) may result in 0 cTokens
   * being minted, or in fewer cTokens being minted than is implied by the
   * current exchange rate (due to lack of sufficient precision on the tokens).
   */
  function _depositOnCompound(AssetType asset, uint256 balance) internal {
    // Only perform a deposit if the balance is non-zero. This could also take
    // into account the safe deposit threshold for each asset - for instance, a
    // deposit of 1 wei of Dai will mint 0 cDai, since cDai precision is lower.
    if (balance > 0) {
      // Get cToken address for the asset type.
      address cToken = asset == AssetType.DAI ? address(_CDAI) : address(_CUSDC);

      // Attempt to mint the balance on the cToken contract.
      (bool ok, bytes memory data) = cToken.call(abi.encodeWithSelector(
        // Note: since both cTokens have the same interface, just use cDAI's.
        _CDAI.mint.selector, balance
      ));

      // Log an external error if something went wrong with the attempt.
      _checkCompoundInteractionAndLogAnyErrors(
        asset, _CDAI.mint.selector, ok, data
      );
    }
  }

  /**
   * @notice Internal function for withdrawing a given underlying asset balance
   * from the corresponding cToken. Note that the requested balance may not be
   * currently available on Compound, which will cause the withdrawal to fail.
   * @param asset uint256 The asset's ID, either Dai (0) or USDC (1).
   * @param balance uint256 The amount of the asset to withdraw, denominated in
   * the underlying token. Note that an attempt to withdraw "dust" (i.e. very
   * small amounts) may result in 0 underlying tokens being redeemed, or in
   * fewer tokens being redeemed than is implied by the current exchange rate
   * (due to lack of sufficient precision on the tokens).
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function _withdrawFromCompound(
    AssetType asset,
    uint256 balance
  ) internal returns (bool success) {
    // Get cToken address for the asset type. (No custom ETH withdrawal action.)
    address cToken = asset == AssetType.DAI ? address(_CDAI) : address(_CUSDC);

    // Attempt to redeem the underlying balance from the cToken contract.
    (bool ok, bytes memory data) = cToken.call(abi.encodeWithSelector(
      // Note: function selector is the same for each cToken so just use cDAI's.
      _CDAI.redeemUnderlying.selector, balance
    ));

    // Log an external error if something went wrong with the attempt.
    success = _checkCompoundInteractionAndLogAnyErrors(
      asset, _CDAI.redeemUnderlying.selector, ok, data
    );
  }

  /**
   * @notice Internal function for validating supplied gas (if specified),
   * retrieving the signer's public key from the Dharma Key Registry, deriving
   * the action ID, validating the provided caller and/or signatures using that
   * action ID, and incrementing the nonce. This function serves as the
   * entrypoint for all protected "actions" on the smart wallet, and is the only
   * area where these functions should revert (other than due to out-of-gas
   * errors, which can be guarded against by supplying a minimum action gas
   * requirement).
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V1 include Cancel (0), SetUserSigningKey (1), Generic (2), 
   * GenericAtomicBatch (3), DAIWithdrawal (4), USDCWithdrawal (5), and
   * ETHWithdrawal (6).
   * @param arguments bytes ABI-encoded arguments for the action.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return The nonce of the current action (prior to incrementing it).
   */
  function _validateActionAndIncrementNonce(
    ActionType action,
    bytes memory arguments,
    uint256 minimumActionGas,
    bytes memory userSignature,
    bytes memory dharmaSignature
  ) internal returns (bytes32 actionID, uint256 actionNonce) {
    // Ensure that the current gas exceeds the minimum required action gas.
    // This prevents griefing attacks where an attacker can invalidate a
    // signature without providing enough gas for the action to succeed. Also
    // note that some gas will be spent before this check is reached - supplying
    // ~30,000 additional gas should suffice when submitting transactions. To
    // skip this requirement, supply zero for the minimumActionGas argument.
    if (minimumActionGas != 0) {
      require(
        gasleft() >= minimumActionGas,
        "Invalid action - insufficient gas supplied by transaction submitter."
      );
    }

    // Get the current nonce for the action to be performed.
    actionNonce = _nonce;

    // Get the user signing key that will be used to verify their signature.
    address userSigningKey = _userSigningKey;

    // Get the Dharma signing key that will be used to verify their signature.
    address dharmaSigningKey = _getDharmaSigningKey();

    // Determine the actionID - this serves as the signature hash.
    actionID = _getActionID(
      action,
      arguments,
      actionNonce,
      minimumActionGas,
      userSigningKey,
      dharmaSigningKey
    );

    // Compute the message hash - the hashed, EIP-191-0x45-prefixed action ID.
    bytes32 messageHash = actionID.toEthSignedMessageHash();

    // Actions other than Cancel require both signatures; Cancel only needs one.
    if (action != ActionType.Cancel) {
      // Validate user signing key signature unless it is `msg.sender`.
      if (msg.sender != userSigningKey) {
        require(
          _validateUserSignature(
            messageHash, action, arguments, userSigningKey, userSignature
          ),
          "Invalid action - invalid user signature."
        );
      }

      // Validate Dharma signing key signature unless it is `msg.sender`.
      if (msg.sender != dharmaSigningKey) {
        require(
          dharmaSigningKey == messageHash.recover(dharmaSignature),
          "Invalid action - invalid Dharma signature."
        );
      }
    } else {
      // Validate signing key signature unless user or Dharma is `msg.sender`.
      if (msg.sender != userSigningKey && msg.sender != dharmaSigningKey) {
        require(
          dharmaSigningKey == messageHash.recover(dharmaSignature) ||
          _validateUserSignature(
            messageHash, action, arguments, userSigningKey, userSignature
          ),
          "Invalid action - invalid signature."
        );
      }
    }

    // Increment nonce in order to prevent reuse of signatures after the call.
    _incrementNonce();
  }

  /**
   * @notice Internal function for entering cDAI, cUSDC, and cETH markets. This
   * is performed now so that V0 smart wallets will not need to be reinitialized
   * in order to support using these assets as collateral when borrowing funds.
   */
  function _enterMarkets() internal {
    // Create input array with each cToken address on which to enter a market. 
    address[] memory marketsToEnter = new address[](3);
    marketsToEnter[0] = address(_CDAI);
    marketsToEnter[1] = address(_CUSDC);
    marketsToEnter[2] = address(
      0x4Ddc2D193948926D02f9B1fE9e1daa0718270ED5
    ); // CEther

    // Attempt to enter each market by calling into the Comptroller contract.
    (bool ok, bytes memory data) = address(_COMPTROLLER).call(
      abi.encodeWithSelector(_COMPTROLLER.enterMarkets.selector, marketsToEnter)
    );

    // Log an external error if something went wrong with the attempt.
    if (ok) {
      uint256[] memory compoundErrors = abi.decode(data, (uint256[]));
      for (uint256 i = 0; i < compoundErrors.length; i++) {
        uint256 compoundError = compoundErrors[i];
        if (compoundError != _COMPOUND_SUCCESS) {
          emit ExternalError(
            address(_COMPTROLLER),
            string(
              abi.encodePacked(
                "Compound Comptroller contract returned error code ",
                uint8((compoundError / 10) + 48),
                uint8((compoundError % 10) + 48),
                " while attempting to call enterMarkets."
              )
            )
          );
        }
      }
    } else {
      // Decode the revert reason in the event one was returned.
      string memory revertReason = _decodeRevertReason(data);

      emit ExternalError(
        address(_COMPTROLLER),
        string(
          abi.encodePacked(
            "Compound Comptroller contract reverted on enterMarkets: ",
            revertReason
          )
        )
      );
    }
  }

  /**
   * @notice Internal function to determine whether a call to a given cToken
   * succeeded, and to emit a relevant ExternalError event if it failed. The
   * failure can be caused by a call that reverts, or by a call that does not
   * revert but returns a non-zero error code.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   * @param functionSelector bytes4 The function selector that was called on the
   * corresponding cToken of the asset type.
   * @param ok bool A boolean representing whether the call returned or
   * reverted.
   * @param data bytes The data provided by the returned or reverted call.
   * @return True if the interaction was successful, otherwise false. This will
   * be used to determine if subsequent steps in the action should be attempted
   * or not, specifically a transfer following a withdrawal.
   */
  function _checkCompoundInteractionAndLogAnyErrors(
    AssetType asset,
    bytes4 functionSelector,
    bool ok,
    bytes memory data
  ) internal returns (bool success) {
    // Log an external error if something went wrong with the attempt.
    if (ok) {
      uint256 compoundError = abi.decode(data, (uint256));
      if (compoundError != _COMPOUND_SUCCESS) {
        // Get called contract address, name of contract, and function name.
        (address account, string memory name, string memory functionName) = (
          _getCTokenDetails(asset, functionSelector)
        );

        emit ExternalError(
          account,
          string(
            abi.encodePacked(
              "Compound ",
              name,
              " contract returned error code ",
              uint8((compoundError / 10) + 48),
              uint8((compoundError % 10) + 48),
              " while attempting to call ",
              functionName,
              "."
            )
          )
        );
      } else {
        success = true;
      }
    } else {
      // Get called contract address, name of contract, and function name.
      (address account, string memory name, string memory functionName) = (
        _getCTokenDetails(asset, functionSelector)
      );

      // Decode the revert reason in the event one was returned.
      string memory revertReason = _decodeRevertReason(data);

      emit ExternalError(
        account,
        string(
          abi.encodePacked(
            "Compound ",
            name,
            " contract reverted while attempting to call ",
            functionName,
            ": ",
            revertReason
          )
        )
      );
    }
  }

  /**
   * @notice Internal function to diagnose the reason that a withdrawal attempt
   * failed and to emit a corresponding ExternalError event. Errors related to
   * the call to `redeemUnderlying` on the cToken are handled by
   * `_checkCompoundInteractionAndLogAnyErrors` - if the error did not originate
   * from that call, it could be caused by a call to `balanceOfUnderlying` (i.e.
   * when attempting a maximum withdrawal) or by the call to `transfer` on the
   * underlying token after the withdrawal has been completed.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   */
  function _diagnoseAndEmitErrorRelatedToWithdrawal(AssetType asset) internal {
    // Get called contract address and name of contract (no need for selector).
    (address cToken, string memory name, ) = _getCTokenDetails(
      asset, bytes4(0)
    );

    // Revert could be caused by cToken MathError or underlying transfer error.
    (bool check, ) = cToken.call(abi.encodeWithSelector(
      // Note: since both cTokens have the same interface, just use cDAI's.
      _CDAI.balanceOfUnderlying.selector, address(this)
    ));
    if (!check) {
      emit ExternalError(
        cToken,
        string(
          abi.encodePacked(
            name, " contract reverted on call to balanceOfUnderlying."
          )
        )
      );
    } else {
      if (asset == AssetType.DAI) {
        emit ExternalError(address(_DAI), "DAI contract reverted on transfer.");
      } else {
        // Find out why USDC transfer reverted (doesn't give revert reasons).
        _diagnoseAndEmitUSDCSpecificError(_USDC.transfer.selector);
      }
    }
  }

  /**
   * @notice Internal function to diagnose the reason that a call to the USDC
   * contract failed and to emit a corresponding ExternalError event. USDC can
   * blacklist accounts and pause the contract, which can both cause a transfer
   * or approval to fail.
   * @param functionSelector bytes4 The function selector that was called on the
   * USDC contract.
   */
  function _diagnoseAndEmitUSDCSpecificError(bytes4 functionSelector) internal {
    // Determine the name of the function that was called on USDC.
    string memory functionName;
    if (functionSelector == _USDC.transfer.selector) {
      functionName = "transfer";
    } else {
      functionName = "approve";
    }

    // Find out why USDC transfer reverted (it doesn't give revert reasons).
    if (_USDC_NAUGHTY.isBlacklisted(address(this))) {
      emit ExternalError(
        address(_USDC),
        string(
          abi.encodePacked(
            functionName, " failed - USDC has blacklisted this user."
          )
        )
      );
    } else { // Note: `else if` breaks coverage.
      if (_USDC_NAUGHTY.paused()) {
        emit ExternalError(
          address(_USDC),
          string(
            abi.encodePacked(
              functionName, " failed - USDC contract is currently paused."
            )
          )
        );
      } else {
        emit ExternalError(
          address(_USDC),
          string(
            abi.encodePacked(
              "USDC contract reverted on ", functionName, "."
            )
          )
        );
      }
    }
  }

  /**
   * @notice Internal function to ensure that protected functions can only be
   * called from this contract and that they have the appropriate context set.
   * The self-call context is then cleared. It is used as an additional guard
   * against reentrancy, especially once generic actions are supported by the
   * smart wallet in future versions.
   * @param selfCallContext bytes4 The expected self-call context, equal to the
   * function selector of the approved calling function.
   */
  function _enforceSelfCallFrom(bytes4 selfCallContext) internal {
    // Ensure caller is this contract and self-call context is correctly set.
    require(
      msg.sender == address(this) &&
      _selfCallContext == selfCallContext,
      "External accounts or unapproved internal functions cannot call this."
    );

    // Clear the self-call context.
    delete _selfCallContext;
  }

  /**
   * @notice Internal view function for validating a user's signature. If the
   * user's signing key does not have contract code, it will be validated via
   * ecrecover; otherwise, it will be validated using ERC-1271, passing the
   * message hash that was signed, the action type, and the arguments as data.
   * @param messageHash bytes32 The message hash that is signed by the user. It
   * is derived by prefixing (according to EIP-191 0x45) and hashing an actionID
   * returned from `getCustomActionID`.
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V1 include Cancel (0), SetUserSigningKey (1), Generic (2), 
   * GenericAtomicBatch (3), DAIWithdrawal (4), USDCWithdrawal (5), and
   * ETHWithdrawal (6).
   * @param arguments bytes ABI-encoded arguments for the action.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used.
   * @return A boolean representing the validity of the supplied user signature.
   */
  function _validateUserSignature(
    bytes32 messageHash,
    ActionType action,
    bytes memory arguments,
    address userSigningKey,
    bytes memory userSignature
  ) internal view returns (bool valid) {
    if (!userSigningKey.isContract()) {
      valid = userSigningKey == messageHash.recover(userSignature);
    } else {
      bytes memory data = abi.encode(messageHash, action, arguments);
      valid = (
        ERC1271(userSigningKey).isValidSignature(
          data, userSignature
        ) == _ERC_1271_MAGIC_VALUE
      );
    }
  }

  /**
   * @notice Internal view function to get the Dharma signing key for the smart
   * wallet from the Dharma Key Registry. This key can be set for each specific
   * smart wallet - if none has been set, a global fallback key will be used.
   * @return The address of the Dharma signing key, or public key corresponding
   * to the secondary signer.
   */
  function _getDharmaSigningKey() internal view returns (
    address dharmaSigningKey
  ) {
    dharmaSigningKey = _DHARMA_KEY_REGISTRY.getKey();
  }

  /**
   * @notice Internal view function that, given an action type and arguments,
   * will return the action ID or message hash that will need to be prefixed
   * (according to EIP-191 0x45), hashed, and signed by the key designated by
   * the Dharma Key Registry in order to construct a valid signature for the
   * corresponding action. The current nonce will be supplied to this function
   * when reconstructing an action ID during protected function execution based
   * on the supplied parameters.
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V1 include Cancel (0), SetUserSigningKey (1), Generic (2), 
   * GenericAtomicBatch (3), DAIWithdrawal (4), USDCWithdrawal (5), and
   * ETHWithdrawal (6).
   * @param arguments bytes ABI-encoded arguments for the action.
   * @param nonce uint256 The nonce to use.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param dharmaSigningKey address The address of the secondary key, or public
   * key corresponding to the secondary signer.
   * @return The action ID, which will need to be prefixed, hashed and signed in
   * order to construct a valid signature.
   */
  function _getActionID(
    ActionType action,
    bytes memory arguments,
    uint256 nonce,
    uint256 minimumActionGas,
    address userSigningKey,
    address dharmaSigningKey
  ) internal view returns (bytes32 actionID) {
    // The actionID is constructed according to EIP-191-0x45 to prevent replays.
    actionID = keccak256(
      abi.encodePacked(
        address(this),
        _DHARMA_SMART_WALLET_VERSION,
        userSigningKey,
        dharmaSigningKey,
        nonce,
        minimumActionGas,
        action,
        arguments
      )
    );
  }

  /**
   * @notice Internal pure function to get the cToken address, it's name, and
   * the name of the called function, based on a supplied asset type and
   * function selector. It is used to help construct ExternalError events.
   * @param asset uint256 The ID of the asset, either Dai (0) or USDC (1).
   * @param functionSelector bytes4 The function selector that was called on the
   * corresponding cToken of the asset type.
   * @return The cToken address, it's name, and the name of the called function.
   */
  function _getCTokenDetails(
    AssetType asset,
    bytes4 functionSelector
  ) internal pure returns (
    address account,
    string memory name,
    string memory functionName
  ) {
    if (asset == AssetType.DAI) {
      account = address(_CDAI);
      name = "cDAI";
    } else {
      account = address(_CUSDC);
      name = "cUSDC";
    }

    // Note: since both cTokens have the same interface, just use cDAI's.
    if (functionSelector == _CDAI.mint.selector) {
      functionName = "mint";
    } else {
      functionName = "redeemUnderlying";
    }
  }

  /**
   * @notice Internal pure function to ensure that a given `to` address provided
   * as part of a generic action is valid. Calls cannot be performed to accounts
   * without code or back into the smart wallet itself.
   */
  function _ensureValidGenericCallTarget(address to) internal view {
    require(
      to.isContract(),
      "Invalid `to` parameter - must supply a contract address containing code."
    );

    require(
      to != address(this),
      "Invalid `to` parameter - cannot supply the address of this contract."
    );
  }

  /**
   * @notice Internal pure function to decode revert reasons. The revert reason
   * prefix is removed and the remaining string argument is decoded.
   * @param revertData bytes The raw data supplied alongside the revert.
   * @return The decoded revert reason string.
   */
  function _decodeRevertReason(
    bytes memory revertData
  ) internal pure returns (string memory revertReason) {
    // Solidity prefixes revert reason with 0x08c379a0 -> Error(string) selector
    if (
      revertData.length > 68 && // prefix (4) + position (32) + length (32)
      revertData[0] == byte(0x08) &&
      revertData[1] == byte(0xc3) &&
      revertData[2] == byte(0x79) &&
      revertData[3] == byte(0xa0)
    ) {
      // Get the revert reason without the prefix from the revert data.
      bytes memory revertReasonBytes = new bytes(revertData.length - 4);
      for (uint256 i = 4; i < revertData.length; i++) {
        revertReasonBytes[i - 4] = revertData[i];
      }

      // Decode the resultant revert reason as a string.
      revertReason = abi.decode(revertReasonBytes, (string));
    } else {
      // Simply return the default, with no revert reason.
      revertReason = "(no revert reason)";
    }
  }
}

pragma solidity 0.5.11; // optimization runs: 200, evm version: petersburg
// WARNING - `executeActionWithAtomicBatchCalls` has a `bytes[]` argument that
// requires ABIEncoderV2. Exercise caution when calling that specific function.
pragma experimental ABIEncoderV2;

import "@openzeppelin/contracts/utils/Address.sol";
import "@openzeppelin/contracts/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "../../../interfaces/DharmaSmartWalletImplementationV0Interface.sol";
import "../../../interfaces/DharmaSmartWalletImplementationV1Interface.sol";
import "../../../interfaces/CTokenInterface.sol";
import "../../../interfaces/USDCV1Interface.sol";
import "../../../interfaces/ComptrollerInterface.sol";
import "../../../interfaces/DharmaKeyRegistryInterface.sol";
import "../../../interfaces/ERC1271.sol";


/**
 * @title DharmaSmartWalletImplementationV2
 * @author 0age
 * @notice The V2 implementation for the Dharma smart wallet is a joint-custody,
 * meta-transaction-enabled wallet with helper functions to facilitate lending
 * funds using CompoundV2. It makes a few minor fixes and changes to the V1
 * implementation to improve efficiency and reliability for an initial save-only
 * Dharma Smart Wallet. It also contains methods to support account recovery and
 * generic actions, including in an atomic batch. The smart wallet instances
 * utilizing this implementation are deployed through the Dharma Smart Wallet
 * Factory via `CREATE2`, which allows for their address to be known ahead of
 * time, and any Dai or USDC that has already been sent into that address will
 * automatically be deposited into Compound upon deployment of the new smart
 * wallet instance.
 */
contract DharmaSmartWalletImplementationV2 is
  DharmaSmartWalletImplementationV0Interface,
  DharmaSmartWalletImplementationV1Interface {
  using Address for address;
  using ECDSA for bytes32;
  // WARNING: DO NOT REMOVE OR REORDER STORAGE WHEN WRITING NEW IMPLEMENTATIONS!

  // The user signing key associated with this account is in storage slot 0.
  // It is the core differentiator when it comes to the account in question.
  address private _userSigningKey;

  // The nonce associated with this account is in storage slot 1. Every time a
  // signature is submitted, it must have the appropriate nonce, and once it has
  // been accepted the nonce will be incremented.
  uint256 private _nonce;

  // The self-call context flag is in storage slot 2. Some protected functions
  // may only be called externally from calls originating from other methods on
  // this contract, which enables appropriate exception handling on reverts.
  // Any storage should only be set immediately preceding a self-call and should
  // be cleared upon entering the protected function being called.
  bytes4 internal _selfCallContext;

  // END STORAGE DECLARATIONS - DO NOT REMOVE OR REORDER STORAGE ABOVE HERE!

  // The smart wallet version will be used when constructing valid signatures.
  uint256 internal constant _DHARMA_SMART_WALLET_VERSION = 2;

  // The Dharma Key Registry holds a public key for verifying meta-transactions.
  DharmaKeyRegistryInterface internal constant _DHARMA_KEY_REGISTRY = (
    DharmaKeyRegistryInterface(0x000000005D7065eB9716a410070Ee62d51092C98)
  );

  // Account recovery is facilitated using a hard-coded recovery manager,
  // controlled by Dharma and implementing appropriate timelocks.
  address internal constant _ACCOUNT_RECOVERY_MANAGER = address(
    0x00000000d750176e38660203C678D88eE7e28d36
  );

  // This contract interfaces with Dai, USDC, and related CompoundV2 contracts.
  CTokenInterface internal constant _CDAI = CTokenInterface(
    0xF5DCe57282A584D2746FaF1593d3121Fcac444dC // mainnet
  );

  CTokenInterface internal constant _CUSDC = CTokenInterface(
    0x39AA39c021dfbaE8faC545936693aC917d5E7563 // mainnet
  );

  IERC20 internal constant _DAI = IERC20(
    0x89d24A6b4CcB1B6fAA2625fE562bDD9a23260359 // mainnet
  );

  IERC20 internal constant _USDC = IERC20(
    0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48 // mainnet
  );

  USDCV1Interface internal constant _USDC_NAUGHTY = USDCV1Interface(
    0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48 // mainnet
  );

  ComptrollerInterface internal constant _COMPTROLLER = ComptrollerInterface(
    0x3d9819210A31b4961b30EF54bE2aeD79B9c9Cd3B // mainnet
  );

  // Compound returns a value of 0 to indicate success, or lack of an error.
  uint256 internal constant _COMPOUND_SUCCESS = 0;

  // ERC-1271 must return this magic value when `isValidSignature` is called.
  bytes4 internal constant _ERC_1271_MAGIC_VALUE = bytes4(0x20c13b0b);

  /**
   * @notice In initializer, set up user signing key, set approval on the cDAI
   * and cUSDC contracts, and deposit any Dai or USDC already at the address to
   * Compound. Note that this initializer is only callable while the smart
   * wallet instance is still in the contract creation phase.
   * @param userSigningKey address The initial user signing key for the smart
   * wallet.
   */
  function initialize(address userSigningKey) external {
    // Ensure that this function is only callable during contract construction.
    assembly { if extcodesize(address) { revert(0, 0) } }

    // Set up the user's signing key and emit a corresponding event.
    _setUserSigningKey(userSigningKey);

    // Approve the cDAI contract to transfer Dai on behalf of this contract.
    if (_setFullApproval(AssetType.DAI)) {
      // Get the current Dai balance on this contract.
      uint256 daiBalance = _DAI.balanceOf(address(this));

      // Try to deposit any dai balance on Compound.
      _depositOnCompound(AssetType.DAI, daiBalance);
    }

    // Approve the cUSDC contract to transfer USDC on behalf of this contract.
    if (_setFullApproval(AssetType.USDC)) {
      // Get the current USDC balance on this contract.
      uint256 usdcBalance = _USDC.balanceOf(address(this));

      // Try to deposit any USDC balance on Compound.
      _depositOnCompound(AssetType.USDC, usdcBalance);
    }
  }

  /**
   * @notice Deposit all Dai and USDC currently residing at this address to
   * Compound. Note that "repay" is not currently implemented, but the function
   * is still named "repayAndDeposit" so that infrastructure around calling this
   * function will not need to be altered for a future smart wallet version. If
   * some step of this function fails, the function itself will still succeed,
   * but an ExternalError with information on what went wrong will be emitted.
   */
  function repayAndDeposit() external {
    // Get the current Dai balance on this contract.
    uint256 daiBalance = _DAI.balanceOf(address(this));

    // Deposit any available Dai.
    _depositOnCompound(AssetType.DAI, daiBalance);

    // Get the current USDC balance on this contract.
    uint256 usdcBalance = _USDC.balanceOf(address(this));

    // If there is any USDC balance, check for adequate approval for cUSDC.
    if (usdcBalance > 0) {
      uint256 usdcAllowance = _USDC.allowance(address(this), address(_CUSDC));
      // If allowance is insufficient, try to set it before depositing.
      if (usdcAllowance < usdcBalance) {
        if (_setFullApproval(AssetType.USDC)) {
          // Deposit any available USDC.
          _depositOnCompound(AssetType.USDC, usdcBalance);
        }
      // Otherwise, go ahead and try the deposit.
      } else {
        // Deposit any available USDC.
        _depositOnCompound(AssetType.USDC, usdcBalance);
      }
    }
  }

  /**
   * @notice Withdraw Dai to a provided recipient address by redeeming the
   * underlying Dai from the cDAI contract and transferring it to the recipient.
   * All Dai in Compound and in the smart wallet itself can be withdrawn by
   * providing an amount of uint256(-1) or 0xfff...fff. This function can be
   * called directly by the account set as the global key on the Dharma Key
   * Registry, or by any relayer that provides a signed message from the same
   * keyholder. The nonce used for the signature must match the current nonce on
   * the smart wallet, and gas supplied to the call must exceed the specified
   * minimum action gas, plus the gas that will be spent before the gas check is
   * reached - usually somewhere around 25,000 gas. If the withdrawal fails, an
   * ExternalError with additional details on what went wrong will be emitted.
   * Note that some dust may still be left over, even in the event of a max
   * withdrawal, due to the fact that Dai has a higher precision than cDAI. Also
   * note that the withdrawal will fail in the event that Compound does not have
   * sufficient Dai available to withdraw.
   * @param amount uint256 The amount of Dai to withdraw.
   * @param recipient address The account to transfer the withdrawn Dai to.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function withdrawDai(
    uint256 amount,
    address recipient,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok) {
    // Ensure caller and/or supplied signatures are valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.DAIWithdrawal,
      abi.encode(amount, recipient),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Set the self-call context so we can call _withdrawDaiAtomic.
    _selfCallContext = this.withdrawDai.selector;

    // Make the atomic self-call - if redeemUnderlying fails on cDAI, it will
    // succeed but nothing will happen except firing an ExternalError event. If
    // the second part of the self-call (the Dai transfer) fails, it will revert
    // and roll back the first part of the call, and we'll fire an ExternalError
    // event after returning from the failed call.
    bytes memory returnData;
    (ok, returnData) = address(this).call(abi.encodeWithSelector(
      this._withdrawDaiAtomic.selector, amount, recipient
    ));

    // If the atomic call failed, emit an event signifying a transfer failure.
    if (!ok) {
      emit ExternalError(address(_DAI), "DAI contract reverted on transfer.");
    } else {
      // Set ok to false if the call succeeded but the withdrawal failed.
      ok = abi.decode(returnData, (bool));
    }
  }

  /**
   * @notice Protected function that can only be called from `withdrawDai` on
   * this contract. It will attempt to withdraw the supplied amount of Dai, or
   * the maximum amount if specified using `uint256(-1)`, to the supplied
   * recipient address by redeeming the underlying Dai from the cDAI contract
   * and transferring it to the recipient. An ExternalError will be emitted and
   * the transfer will be skipped if the call to `redeem` or `redeemUnderlying`
   * fails, and any revert will be caught by `withdrawDai` and diagnosed in
   * order to emit an appropriate ExternalError as well.
   * @param amount uint256 The amount of Dai to withdraw.
   * @param recipient address The account to transfer the withdrawn Dai to.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function _withdrawDaiAtomic(
    uint256 amount,
    address recipient
  ) external returns (bool success) {
    // Ensure caller is this contract and self-call context is correctly set.
    _enforceSelfCallFrom(this.withdrawDai.selector);

    // If amount = 0xfff...fff, withdraw the maximum amount possible.
    bool maxWithdraw = (amount == uint256(-1));
    if (maxWithdraw) {
      // Attempt to withdraw all Dai from Compound before proceeding.
      if (_withdrawMaxFromCompound(AssetType.DAI)) {
        // At this point dai transfer should never fail - wrap it just in case.
        require(_DAI.transfer(recipient, _DAI.balanceOf(address(this))));
        success = true;
      }
    } else {
      // Attempt to withdraw specified Dai from Compound before proceeding.
      if (_withdrawFromCompound(AssetType.DAI, amount)) {
        // At this point dai transfer should never fail - wrap it just in case.
        require(_DAI.transfer(recipient, amount));
        success = true;
      }
    }
  }

  /**
   * @notice Withdraw USDC to a provided recipient address by redeeming the
   * underlying USDC from the cUSDC contract and transferring it to recipient.
   * All USDC in Compound and in the smart wallet itself can be withdrawn by
   * providing an amount of uint256(-1) or 0xfff...fff. This function can be
   * called directly by the account set as the global key on the Dharma Key
   * Registry, or by any relayer that provides a signed message from the same
   * keyholder. The nonce used for the signature must match the current nonce on
   * the smart wallet, and gas supplied to the call must exceed the specified
   * minimum action gas, plus the gas that will be spent before the gas check is
   * reached - usually somewhere around 25,000 gas. If the withdrawal fails, an
   * ExternalError with additional details on what went wrong will be emitted.
   * Note that the USDC contract can be paused and also allows for blacklisting
   * accounts - either of these possibilities may cause a withdrawal to fail. In
   * addition, Compound may not have sufficient USDC available at the time to
   * withdraw.
   * @param amount uint256 The amount of USDC to withdraw.
   * @param recipient address The account to transfer the withdrawn USDC to.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function withdrawUSDC(
    uint256 amount,
    address recipient,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok) {
    // Ensure caller and/or supplied signatures are valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.USDCWithdrawal,
      abi.encode(amount, recipient),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Set the self-call context so we can call _withdrawUSDCAtomic.
    _selfCallContext = this.withdrawUSDC.selector;

    // Make the atomic self-call - if redeemUnderlying fails on cUSDC, it will
    // succeed but nothing will happen except firing an ExternalError event. If
    // the second part of the self-call (USDC transfer) fails, it will revert
    // and roll back the first part of the call, and we'll fire an ExternalError
    // event after returning from the failed call.
    bytes memory returnData;
    (ok, returnData) = address(this).call(abi.encodeWithSelector(
      this._withdrawUSDCAtomic.selector, amount, recipient
    ));
    if (!ok) {
      // Find out why USDC transfer reverted (doesn't give revert reasons).
      _diagnoseAndEmitUSDCSpecificError(_USDC.transfer.selector);
    } else {
      // Ensure that ok == false in the event the withdrawal failed.
      ok = abi.decode(returnData, (bool));
    }
  }

  /**
   * @notice Protected function that can only be called from `withdrawUSDC` on
   * this contract. It will attempt to withdraw the supplied amount of USDC, or
   * the maximum amount if specified using `uint256(-1)`, to the supplied
   * recipient address by redeeming the underlying USDC from the cUSDC contract
   * and transferring it to the recipient. An ExternalError will be emitted and
   * the transfer will be skipped if the call to `redeemUnderlying` fails, and
   * any revert will be caught by `withdrawUSDC` and diagnosed in order to emit
   * an appropriate ExternalError as well.
   * @param amount uint256 The amount of USDC to withdraw.
   * @param recipient address The account to transfer the withdrawn USDC to.
   * @return True if the withdrawal succeeded, otherwise false.
   */
  function _withdrawUSDCAtomic(
    uint256 amount,
    address recipient
  ) external returns (bool success) {
    // Ensure caller is this contract and self-call context is correctly set.
    _enforceSelfCallFrom(this.withdrawUSDC.selector);

    // If amount = 0xfff...fff, withdraw the maximum amount possible.
    bool maxWithdraw = (amount == uint256(-1));
    if (maxWithdraw) {
      // Attempt to withdraw all USDC from Compound before proceeding.
      if (_withdrawMaxFromCompound(AssetType.USDC)) {
        // Ensure that the USDC transfer does not fail.
        require(_USDC.transfer(recipient, _USDC.balanceOf(address(this))));
        success = true;
      }
    } else {
      // Attempt to withdraw specified USDC from Compound before proceeding.
      if (_withdrawFromCompound(AssetType.USDC, amount)) {
        // Ensure that the USDC transfer does not fail.
        require(_USDC.transfer(recipient, amount));
        success = true;
      }
    }
  }

  /**
   * @notice Withdraw Ether to a provided recipient address by transferring it
   * to a recipient. This is only intended to be utilized on V2 as a mechanism
   * for recovering Ether from this contract.
   * @param amount uint256 The amount of Ether to withdraw.
   * @param recipient address The account to transfer the Ether to.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return True if the transfer succeeded, otherwise false.
   */
  function withdrawEther(
    uint256 amount,
    address payable recipient,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok) {
    // Ensure caller and/or supplied signatures are valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.ETHWithdrawal,
      abi.encode(amount, recipient),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Attempt to perform the transfer and emit an event if it fails.
    (ok, ) = recipient.call.gas(2300).value(amount)("");
    if (!ok) {
      emit ExternalError(recipient, "Recipient rejected ether transfer.");
    }
  }

  /**
   * @notice Allow a signatory to increment the nonce at any point. The current
   * nonce needs to be provided as an argument to the a signature so as not to
   * enable griefing attacks. All arguments can be omitted if called directly.
   * No value is returned from this function - it will either succeed or revert.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param signature bytes A signature that resolves to either the public key
   * set for this account in storage slot zero, `_userSigningKey`, or the public
   * key returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   */  
  function cancel(
    uint256 minimumActionGas,
    bytes calldata signature
  ) external {
    // Ensure the caller or the supplied signature is valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.Cancel,
      abi.encode(),
      minimumActionGas,
      signature,
      signature
    );
  }

  /**
   * @notice Perform a generic call to another contract. Note that accounts with
   * no code may not be specified, nor may the smart wallet itself. In order to
   * increment the nonce and invalidate the signature, a call to this function
   * with a valid target, signatutes, and gas will always succeed. To determine
   * whether the call made as part of the action was successful or not, either
   * the return values or the `CallSuccess` or `CallFailure` event can be used.
   * @param to address The contract to call.
   * @param data bytes The calldata to provide when making the call.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   * @return A boolean signifying the status of the call, as well as any data
   * returned from the call.
   */
  function executeAction(
    address to,
    bytes calldata data,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external returns (bool ok, bytes memory returnData) {
    // Ensure that the `to` address is a contract and is not this contract.
    _ensureValidGenericCallTarget(to);

    // Ensure caller and/or supplied signatures are valid and increment nonce.
    (bytes32 actionID, uint256 nonce) = _validateActionAndIncrementNonce(
      ActionType.Generic,
      abi.encode(to, data),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Note: from this point on, there are no reverts (apart from out-of-gas or
    // call-depth-exceeded) originating from this action. However, the call
    // itself may revert, in which case the function will return `false`, along
    // with the revert reason encoded as bytes, and fire an CallFailure event.

    // Perform the action via low-level call and set return values using result.
    (ok, returnData) = to.call(data);

    // Emit a CallSuccess or CallFailure event based on the outcome of the call.
    if (ok) {
      // Note: while the call succeeded, the action may still have "failed"
      // (for example, successful calls to Compound can still return an error).
      emit CallSuccess(actionID, false, nonce, to, data, returnData);
    } else {
      // Note: while the call failed, the nonce will still be incremented, which
      // will invalidate all supplied signatures.
      emit CallFailure(actionID, nonce, to, data, string(returnData));
    }
  }

  /**
   * @notice Allow signatory to set a new user signing key. The current nonce
   * needs to be provided as an argument to the a signature so as not to enable
   * griefing attacks. No value is returned from this function - it will either
   * succeed or revert.
   * @param userSigningKey address The new user signing key to set on this smart
   * wallet.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @param userSignature bytes A signature that resolves to the public key
   * set for this account in storage slot zero, `_userSigningKey`. If the user
   * signing key is not a contract, ecrecover will be used; otherwise, ERC1271
   * will be used. A unique hash returned from `getCustomActionID` is prefixed
   * and hashed to create the message hash for the signature.
   * @param dharmaSignature bytes A signature that resolves to the public key
   * returned for this account from the Dharma Key Registry. A unique hash
   * returned from `getCustomActionID` is prefixed and hashed to create the
   * signed message.
   */
  function setUserSigningKey(
    address userSigningKey,
    uint256 minimumActionGas,
    bytes calldata userSignature,
    bytes calldata dharmaSignature
  ) external {
    // Ensure caller and/or supplied signatures are valid and increment nonce.
    _validateActionAndIncrementNonce(
      ActionType.SetUserSigningKey,
      abi.encode(userSigningKey),
      minimumActionGas,
      userSignature,
      dharmaSignature
    );

    // Set new user signing key on smart wallet and emit a corresponding event.
    _setUserSigningKey(userSigningKey);
  }

  // Allow the account recovery manager to change the user signing key.
  function recover(address newUserSigningKey) external {
    require(
      msg.sender == _ACCOUNT_RECOVERY_MANAGER,
      "Only the account recovery manager may call this function."
    );

    // Set up the user's new dharma key and emit a corresponding event.
    _setUserSigningKey(newUserSigningKey);
  }

  /**
   * @notice Retrieve the Dai and USDC balances held by the smart wallet, both
   * directly and held in Compound. This is not a view function since Compound
   * will calculate accrued interest as part of the underlying balance checks,
   * but can still be called from an off-chain source as though it were a view
   * function.
   * @return The Dai balance, the USDC balance, the underlying Dai balance of
   * the cDAI balance, and the underlying USDC balance of the cUSDC balance.
   */
  function getBalances() external returns (
    uint256 daiBalance,
    uint256 usdcBalance,
    uint256 etherBalance, // always returns 0
    uint256 cDaiUnderlyingDaiBalance,
    uint256 cUsdcUnderlyingUsdcBalance,
    uint256 cEtherUnderlyingEtherBalance // always returns 0
  ) {
    daiBalance = _DAI.balanceOf(address(this));
    usdcBalance = _USDC.balanceOf(address(this));
    cDaiUnderlyingDaiBalance = _CDAI.balanceOfUnderlying(address(this));
    cUsdcUnderlyingUsdcBalance = _CUSDC.balanceOfUnderlying(address(this));
  }

  /**
   * @notice View function for getting the current user signing key for the
   * smart wallet.
   * @return The current user signing key.
   */
  function getUserSigningKey() external view returns (address userSigningKey) {
    userSigningKey = _userSigningKey;
  }

  /**
   * @notice View function for getting the current nonce of the smart wallet.
   * This nonce is incremented whenever an action is taken that requires a
   * signature and/or a specific caller.
   * @return The current nonce.
   */
  function getNonce() external view returns (uint256 nonce) {
    nonce = _nonce;
  }

  /**
   * @notice View function that, given an action type and arguments, will return
   * the action ID or message hash that will need to be prefixed (according to
   * EIP-191 0x45), hashed, and signed by the key designated by the Dharma Key
   * Registry in order to construct a valid signature for the corresponding
   * action. The current nonce will be used, which means that it will only be
   * valid for the next action taken.
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V2 include Cancel (0), SetUserSigningKey (1), Generic (2), 
   * GenericAtomicBatch (3), DAIWithdrawal (4), USDCWithdrawal (5), and
   * ETHWithdrawal (6).
   * @param amount uint256 The amount to withdraw for Withdrawal actions, or 0
   * for other action types.
   * @param recipient address The account to transfer withdrawn funds to, the
   * new user signing key, or the null address for cancelling.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @return The action ID, which will need to be prefixed, hashed and signed in
   * order to construct a valid signature.
   */
  function getNextCustomActionID(
    ActionType action,
    uint256 amount,
    address recipient,
    uint256 minimumActionGas
  ) external view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getActionID(
      action,
      abi.encode(amount, recipient),
      _nonce,
      minimumActionGas,
      _userSigningKey,
      _getDharmaSigningKey()
    );
  }

  /**
   * @notice View function that, given an action type and arguments, will return
   * the action ID or message hash that will need to be prefixed (according to
   * EIP-191 0x45), hashed, and signed by the key designated by the Dharma Key
   * Registry in order to construct a valid signature for the corresponding
   * action. Any nonce value may be supplied, which enables constructing valid
   * message hashes for multiple future actions ahead of time.
   * @param action uint8 The type of action, designated by it's index. Valid
   * actions in V2 include Cancel (0), SetUserSigningKey (1), Generic (2), 
   * GenericAtomicBatch (3), DAIWithdrawal (4), USDCWithdrawal (5), and
   * ETHWithdrawal (6).
   * @param amount uint256 The amount to withdraw for Withdrawal actions, or 0
   * for other action types.
   * @param recipient address The account to transfer withdrawn funds to, the
   * new user signing key, or the null address for cancelling.
   * @param nonce uint256 The nonce to use.
   * @param minimumActionGas uint256 The minimum amount of gas that must be
   * provided to this call - be aware that additional gas must still be included
   * to account for the cost of overhead incurred up until the start of this
   * function call.
   * @return The action ID, which will need to be prefixed, hashed and signed in
   * order to construct a valid signature.
   */
  function getCustomActionID(
    ActionType action,
    uint256 amount,
    address recipient,
    uint256 nonce,
    uint256 minimumActionGas
  ) external view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getActionID(
      action,
      abi.encode(amount, recipient),
      nonce,
      minimumActionGas,
      _userSigningKey,
      _getDharmaSigningKey()
    );
  }

  function getNextGenericActionID(
    address to,
    bytes calldata data,
    uint256 minimumActionGas
  ) external view returns (bytes32 actionID) {
    // Determine the actionID - this serves as a signature hash for an action.
    actionID = _getActionID(
      ActionType.Generic,
      abi.encode(to, data),
      _nonce,
      minimumActionGas,
      _userSigningKey,
      _getDharmaSigningKey()
    );
  }

  function getGenericActionID(
    address to,
    bytes calldata data,
    uint256 nonce,
