contract CurveAMO_V4 is AccessControl, Initializable {
    using SafeMath for uint256;

    /* ========== STATE VARIABLES ========== */

    IMetaImplementationUSD private frax3crv_metapool;
    IStableSwap3Pool private three_pool;
    IYearnVault private crvFRAX_vault;
