    Types.AssetAmount memory amount = Types.AssetAmount(
      _sign,
      Types.AssetDenomination.Wei,
      Types.AssetReference.Delta,
      _amt
    );
    bytes memory empty;
    Actions.ActionType action = _sign ? Actions.ActionType.Deposit : Actions.ActionType.Withdraw;
